  a.id as account_id,
  a.code,
  a.name,
  a.type,
  COALESCE(SUM(jl.debit), 0) as total_debit,
  COALESCE(SUM(jl.credit), 0) as total_credit,
  COALESCE(SUM(jl.debit) - SUM(jl.credit), 0) as balance
FROM companies c
