CREATE OR REPLACE FUNCTION public.deactivate_inactive_expired_companies(p_cutoff TIMESTAMPTZ)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_sub subscriptions%ROWTYPE; v_companies INT:=0; v_users INT:=0; v_rows INT;
BEGIN
  IF p_cutoff IS NULL OR p_cutoff>now()-INTERVAL '14 days' THEN RAISE EXCEPTION 'فترة عدم النشاط غير صالحة'; END IF;
  FOR v_sub IN
    SELECT s.* FROM subscriptions s
    JOIN companies c ON c.id=s.company_id
    WHERE COALESCE(c.is_active,TRUE)=TRUE
      AND s.status IN ('trial','expired','cancelled')
      AND COALESCE(s.trial_end_date,s.end_date,s.updated_at::DATE)<p_cutoff::DATE
      AND NOT EXISTS(
        SELECT 1 FROM users u WHERE u.company_id=s.company_id AND u.is_active=TRUE
          AND COALESCE(u.last_activity,u.last_login,u.created_at)>=p_cutoff
      )
    ORDER BY s.company_id FOR UPDATE OF s
  LOOP
    UPDATE companies SET is_active=FALSE WHERE id=v_sub.company_id AND COALESCE(is_active,TRUE)=TRUE;
    GET DIAGNOSTICS v_rows=ROW_COUNT; v_companies:=v_companies+v_rows;
    UPDATE users SET is_active=FALSE WHERE company_id=v_sub.company_id AND is_active=TRUE;
    GET DIAGNOSTICS v_rows=ROW_COUNT; v_users:=v_users+v_rows;
    UPDATE subscriptions SET status='cancelled',auto_renew=FALSE,updated_at=now() WHERE id=v_sub.id;
    INSERT INTO security_audit_log(company_id,action,details)
    VALUES(v_sub.company_id,'inactive_company_deactivated',jsonb_build_object('cutoff',p_cutoff,'subscription_id',v_sub.id));
  END LOOP;
  RETURN jsonb_build_object('deactivated_companies',v_companies,'deactivated_users',v_users);
END;
$$;
REVOKE ALL ON FUNCTION public.deactivate_inactive_expired_companies(TIMESTAMPTZ) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.deactivate_inactive_expired_companies(TIMESTAMPTZ) TO service_role;

CREATE OR REPLACE FUNCTION public.restore_company_backup_atomic(
  p_company_id UUID, p_user_id UUID, p_hmac_signature TEXT, p_data JSONB
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_table TEXT; v_row JSONB; v_existing_company UUID; v_updates TEXT;
  v_restored INT:=0; v_table_count INT:=0;
  v_restore_tables CONSTANT TEXT[]:=ARRAY['accounts','contacts','projects','banks_safes','inventory_items','employees'];
  v_known_tables CONSTANT TEXT[]:=ARRAY['accounts','journal_entries','journal_lines','invoices','invoice_items','contacts','clients','projects','banks_safes','cash_transactions','inventory_items','employees','payroll'];
BEGIN
  IF NOT jsonb_typeof(p_data)='object' THEN RAISE EXCEPTION 'بيانات النسخة غير صالحة'; END IF;
  PERFORM 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE AND role='admin';
  IF NOT FOUND THEN RAISE EXCEPTION 'المستخدم غير مخول بالاستعادة'; END IF;
  PERFORM 1 FROM backup_logs WHERE company_id=p_company_id AND hmac_signature=p_hmac_signature;
  IF NOT FOUND THEN RAISE EXCEPTION 'توقيع النسخة غير صالح'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE NOT (k=ANY(v_known_tables))) THEN
    RAISE EXCEPTION 'النسخة تحتوي على جدول غير مسموح';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('backup:'||p_company_id::TEXT,0));

  FOREACH v_table IN ARRAY v_restore_tables LOOP
    IF p_data ? v_table THEN
      IF jsonb_typeof(p_data->v_table)<>'array' THEN RAISE EXCEPTION 'بيانات الجدول % غير صالحة',v_table; END IF;
      v_table_count:=v_table_count+1;
      SELECT string_agg(format('%1$I=EXCLUDED.%1$I',a.attname),',') INTO v_updates
      FROM pg_attribute a WHERE a.attrelid=format('public.%I',v_table)::regclass
        AND a.attnum>0 AND NOT a.attisdropped AND a.attname NOT IN('id','company_id','created_at');
      FOR v_row IN SELECT value FROM jsonb_array_elements(p_data->v_table) LOOP
        IF jsonb_typeof(v_row)<>'object' OR NOT(v_row?'id') THEN RAISE EXCEPTION 'سجل غير صالح في %',v_table; END IF;
        IF v_row?'company_id' AND v_row->>'company_id'<>p_company_id::TEXT THEN
          RAISE EXCEPTION 'سجل من شركة أخرى في %',v_table;
        END IF;
        EXECUTE format('SELECT company_id FROM public.%I WHERE id=$1 FOR UPDATE',v_table)
          INTO v_existing_company USING (v_row->>'id')::UUID;
        IF v_existing_company IS NOT NULL AND v_existing_company<>p_company_id THEN
          RAISE EXCEPTION 'المعرف مستخدم بواسطة شركة أخرى في %',v_table;
        END IF;
        v_row:=v_row||jsonb_build_object('company_id',p_company_id);
        EXECUTE format(
          'INSERT INTO public.%1$I SELECT (jsonb_populate_record(NULL::public.%1$I,$1)).* '
          'ON CONFLICT(id) DO UPDATE SET %2$s WHERE %1$I.company_id=$2',v_table,v_updates
        ) USING v_row,p_company_id;
        v_restored:=v_restored+1;
      END LOOP;
    END IF;
  END LOOP;
  INSERT INTO security_audit_log(company_id,user_id,action,details)
  VALUES(p_company_id,p_user_id,'backup_restore_atomic',jsonb_build_object('restored_records',v_restored,'restored_tables',v_table_count));
  RETURN jsonb_build_object('restored_records',v_restored,'restored_tables',v_table_count);
END;
$$;
REVOKE ALL ON FUNCTION public.restore_company_backup_atomic(UUID,UUID,TEXT,JSONB) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.restore_company_backup_atomic(UUID,UUID,TEXT,JSONB) TO service_role;

CREATE OR REPLACE FUNCTION public.respond_approval_request_atomic(
  p_company_id UUID,p_approval_id UUID,p_action TEXT,p_approver_user_id UUID,p_comments TEXT DEFAULT ''
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_req approval_requests%ROWTYPE; v_role TEXT; v_type TEXT; v_final_status TEXT; v_entity_id UUID; v_now TIMESTAMPTZ:=now();
BEGIN
  IF p_action NOT IN('approve','reject') THEN RAISE EXCEPTION 'قرار الاعتماد غير صالح'; END IF;
  v_final_status:=CASE WHEN p_action='approve' THEN 'approved' ELSE 'rejected' END;
  IF length(COALESCE(p_comments,''))>2000 THEN RAISE EXCEPTION 'تعليق الاعتماد طويل جداً'; END IF;
  SELECT role INTO v_role FROM users WHERE id=p_approver_user_id AND company_id=p_company_id AND is_active=TRUE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المعتمد لا ينتمي للشركة'; END IF;
  SELECT * INTO v_req FROM approval_requests WHERE id=p_approval_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'طلب الاعتماد غير موجود'; END IF;
  IF v_req.requester_id=p_approver_user_id THEN RAISE EXCEPTION 'لا يمكن اعتماد طلبك بنفسك'; END IF;
  IF v_req.approver_id IS DISTINCT FROM p_approver_user_id AND v_role<>'admin' THEN RAISE EXCEPTION 'لست المخول بالاعتماد على هذا الطلب'; END IF;
  IF v_req.status IN('approved','rejected') THEN
    IF v_req.status=v_final_status THEN
      RETURN jsonb_build_object('id',v_req.id,'status',v_req.status,'replayed',TRUE);
    END IF;
    RAISE EXCEPTION 'تمت معالجة طلب الاعتماد مسبقاً';
  END IF;
  IF v_req.status NOT IN('pending','processing') THEN RAISE EXCEPTION 'طلب الاعتماد غير قابل للمعالجة'; END IF;
  IF v_req.status='processing' AND v_req.approved_by IS DISTINCT FROM p_approver_user_id AND v_role<>'admin' THEN
    RAISE EXCEPTION 'طلب الاعتماد قيد المعالجة بواسطة مستخدم آخر';
  END IF;
  v_type:=COALESCE(v_req.entity_type,v_req.transaction_type);
  BEGIN v_entity_id:=COALESCE(v_req.entity_id,v_req.transaction_id::UUID); EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'معرف العنصر غير صالح'; END;
  IF v_type IN('voucher_receipt','voucher_disbursement') THEN RAISE EXCEPTION 'استخدم معاملة اعتماد السند المخصصة'; END IF;

  IF p_action='approve' THEN
    IF v_type='journal_entry' THEN
      UPDATE journal_entries SET status='posted',approved_by=p_approver_user_id,approved_at=v_now WHERE id=v_entity_id AND company_id=p_company_id;
    ELSIF v_type='purchase_invoice' THEN
      UPDATE purchase_invoices SET approved_by=p_approver_user_id,approved_at=v_now WHERE id=v_entity_id AND company_id=p_company_id;
    ELSIF v_type='payroll' THEN
      UPDATE salary_sheets SET status='approved',approved_by=p_approver_user_id,approved_at=v_now WHERE id=v_entity_id AND company_id=p_company_id;
    ELSIF v_type='cash_transaction' THEN
      UPDATE cash_transactions SET approved_by=p_approver_user_id,approved_at=v_now WHERE id=v_entity_id AND company_id=p_company_id AND status<>'cancelled';
    ELSE RAISE EXCEPTION 'نوع العنصر غير مدعوم للاعتماد';
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'العنصر المطلوب اعتماده غير موجود أو غير قابل للاعتماد'; END IF;
  END IF;

  UPDATE approval_requests SET status=v_final_status,
    approved_by=p_approver_user_id,approved_at=v_now,approval_comments=NULLIF(trim(COALESCE(p_comments,'')),''),updated_at=v_now
    WHERE id=p_approval_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_approver_user_id,p_action||'_approval','approval_request',p_approval_id,
    jsonb_build_object('status',v_req.status),jsonb_build_object('status',v_final_status,'entity_type',v_type,'entity_id',v_entity_id,'comments',p_comments));
  IF v_req.requester_id IS NOT NULL THEN
    INSERT INTO notifications(company_id,user_id,type,title,message,entity_type,entity_id)
    VALUES(p_company_id,v_req.requester_id,'approval_response',CASE WHEN p_action='approve' THEN 'تم اعتماد طلبك' ELSE 'تم رفض طلبك' END,
      left(COALESCE(NULLIF(trim(p_comments),''),CASE WHEN p_action='approve' THEN 'تم الاعتماد بنجاح' ELSE 'تم الرفض' END),1000),'approval_request',p_approval_id);
  END IF;
  RETURN jsonb_build_object('id',p_approval_id,'status',v_final_status,'approved_by',p_approver_user_id,'approved_at',v_now,'replayed',FALSE);
END;
$$;
REVOKE ALL ON FUNCTION public.respond_approval_request_atomic(UUID,UUID,TEXT,UUID,TEXT) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.respond_approval_request_atomic(UUID,UUID,TEXT,UUID,TEXT) TO service_role;

UPDATE subscriptions s SET trial_extended_by=NULL
WHERE trial_extended_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM admin_users a WHERE a.id=s.trial_extended_by);
ALTER TABLE subscriptions DROP CONSTRAINT IF EXISTS subscriptions_trial_extended_by_fkey;
ALTER TABLE subscriptions ADD CONSTRAINT subscriptions_trial_extended_by_fkey
  FOREIGN KEY(trial_extended_by) REFERENCES admin_users(id) ON DELETE SET NULL;

CREATE OR REPLACE FUNCTION public.extend_company_trial_atomic(
  p_company_id UUID,p_admin_id UUID,p_days INT,p_reason TEXT DEFAULT ''
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_sub subscriptions%ROWTYPE; v_old_end DATE; v_new_end DATE;
BEGIN
  IF p_days<>7 OR length(COALESCE(p_reason,''))>500 THEN RAISE EXCEPTION 'بيانات تمديد التجربة غير صالحة'; END IF;
  IF NOT EXISTS(SELECT 1 FROM admin_users WHERE id=p_admin_id AND is_active=TRUE) THEN RAISE EXCEPTION 'المدير غير صالح'; END IF;
  IF NOT EXISTS(SELECT 1 FROM companies WHERE id=p_company_id) THEN RAISE EXCEPTION 'الشركة غير موجودة'; END IF;
  SELECT * INTO v_sub FROM subscriptions WHERE company_id=p_company_id ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'لا يوجد اشتراك لهذه الشركة'; END IF;
  IF v_sub.status<>'trial' THEN RAISE EXCEPTION 'التمديد متاح فقط للباقات التجريبية'; END IF;
  IF COALESCE(v_sub.trial_extended,FALSE) THEN
    RETURN jsonb_build_object('id',v_sub.id,'end_date',v_sub.end_date,'trial_end_date',v_sub.trial_end_date,'already_extended',TRUE);
  END IF;
  v_old_end:=COALESCE(v_sub.trial_end_date,v_sub.end_date,CURRENT_DATE);
  v_new_end:=v_old_end+p_days;
  UPDATE subscriptions SET end_date=v_new_end,trial_end_date=v_new_end,trial_extended=TRUE,
    trial_extended_by=p_admin_id,trial_extended_at=now(),original_end_date=v_old_end,updated_at=now()
    WHERE id=v_sub.id RETURNING * INTO v_sub;
  INSERT INTO admin_audit_log(admin_id,action,details,target_type,target_id)
  VALUES(p_admin_id,'extend_trial',format('Extended trial by %s days. Reason: %s',p_days,COALESCE(NULLIF(trim(p_reason),''),'N/A')),'company',p_company_id);
  INSERT INTO notifications(company_id,type,title,message)
  VALUES(p_company_id,'subscription','تم تمديد الفترة التجريبية','تم تمديد فترتك التجريبية 7 أيام إضافية. تنتهي الآن في '||v_new_end::TEXT);
  RETURN jsonb_build_object('id',v_sub.id,'end_date',v_sub.end_date,'trial_end_date',v_sub.trial_end_date,'already_extended',FALSE);
END;
$$;
REVOKE ALL ON FUNCTION public.extend_company_trial_atomic(UUID,UUID,INT,TEXT) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.extend_company_trial_atomic(UUID,UUID,INT,TEXT) TO service_role;

CREATE OR REPLACE FUNCTION public.create_vat_return_filing_atomic(
  p_company_id UUID,p_period_from DATE,p_period_to DATE,p_status TEXT,p_notes TEXT,p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_filing vat_return_filings%ROWTYPE;
BEGIN
  IF p_period_from IS NULL OR p_period_to IS NULL OR p_period_from>p_period_to OR p_status NOT IN('draft','filed')
    OR length(COALESCE(p_notes,''))>2000 THEN RAISE EXCEPTION 'بيانات الإقرار الضريبي غير صالحة'; END IF;
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE) THEN
    RAISE EXCEPTION 'المستخدم غير صالح';
  END IF;
  -- Summary evaluation and insertion are one SQL statement and therefore use
  -- one MVCC snapshot of the posted ledger.
  WITH summary AS (
    SELECT get_vat_return_summary(p_company_id,p_period_from,p_period_to) value
  ), inserted AS (
    INSERT INTO vat_return_filings(company_id,period_from,period_to,output_vat,input_vat,net_vat,
      total_sales,total_purchases,status,filed_at,filed_by,notes,created_by)
    SELECT p_company_id,p_period_from,p_period_to,
      COALESCE((value->>'outputVat')::NUMERIC,0),COALESCE((value->>'inputVat')::NUMERIC,0),
      COALESCE((value->>'outputVat')::NUMERIC,0)-COALESCE((value->>'inputVat')::NUMERIC,0),
      COALESCE((value->>'totalSales')::NUMERIC,0),COALESCE((value->>'totalPurchases')::NUMERIC,0),
      p_status,CASE WHEN p_status='filed' THEN now() END,CASE WHEN p_status='filed' THEN p_user_id END,
      NULLIF(trim(COALESCE(p_notes,'')),''),p_user_id FROM summary RETURNING *
  ) SELECT * INTO v_filing FROM inserted;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','vat_return_filing',v_filing.id,to_jsonb(v_filing));
  RETURN to_jsonb(v_filing);
END;
$$;
REVOKE ALL ON FUNCTION public.create_vat_return_filing_atomic(UUID,DATE,DATE,TEXT,TEXT,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_vat_return_filing_atomic(UUID,DATE,DATE,TEXT,TEXT,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.deactivate_company_user_atomic(p_company_id UUID,p_target_user_id UUID,p_actor_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_target users%ROWTYPE; v_admins INT;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_actor_user_id AND company_id=p_company_id AND is_active=TRUE AND role='admin')
  THEN RAISE EXCEPTION 'المدير غير صالح'; END IF;
  IF p_target_user_id=p_actor_user_id THEN RAISE EXCEPTION 'لا يمكنك تعطيل حسابك الخاص'; END IF;
  PERFORM 1 FROM users WHERE company_id=p_company_id ORDER BY id FOR UPDATE;
  SELECT * INTO v_target FROM users WHERE id=p_target_user_id AND company_id=p_company_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'المستخدم غير موجود'; END IF;
  IF NOT COALESCE(v_target.is_active,FALSE) THEN RETURN jsonb_build_object('id',v_target.id,'is_active',FALSE,'already_inactive',TRUE); END IF;
  IF v_target.role='admin' THEN
    SELECT count(*) INTO v_admins FROM users WHERE company_id=p_company_id AND role='admin' AND is_active=TRUE;
    IF v_admins<=1 THEN RAISE EXCEPTION 'لا يمكن تعطيل آخر مدير في الشركة'; END IF;
  END IF;
  UPDATE users SET is_active=FALSE,token_version=COALESCE(token_version,0)+1,updated_at=now() WHERE id=v_target.id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_actor_user_id,'deactivate_user','user',v_target.id,to_jsonb(v_target),jsonb_build_object('is_active',FALSE));
  RETURN jsonb_build_object('id',v_target.id,'is_active',FALSE,'already_inactive',FALSE);
END;
$$;
REVOKE ALL ON FUNCTION public.deactivate_company_user_atomic(UUID,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.deactivate_company_user_atomic(UUID,UUID,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.delete_custom_module_atomic(p_company_id UUID,p_module_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_module custom_modules%ROWTYPE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE AND role='admin')
  THEN RAISE EXCEPTION 'المدير غير صالح'; END IF;
  SELECT * INTO v_module FROM custom_modules WHERE id=p_module_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'القسم غير موجود'; END IF;
  IF v_module.is_system THEN RAISE EXCEPTION 'لا يمكن حذف قسم نظامي'; END IF;
  DELETE FROM user_permissions WHERE company_id=p_company_id AND module IN(v_module.code,v_module.name);
  DELETE FROM custom_modules WHERE id=p_module_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values)
  VALUES(p_company_id,p_user_id,'delete','custom_module',p_module_id,to_jsonb(v_module));
  RETURN jsonb_build_object('id',p_module_id,'deleted',TRUE);
END;
$$;
REVOKE ALL ON FUNCTION public.delete_custom_module_atomic(UUID,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.delete_custom_module_atomic(UUID,UUID,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.delete_unstarted_project_task_atomic(p_company_id UUID,p_task_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_task project_tasks%ROWTYPE; v_count INT;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  SELECT * INTO v_task FROM project_tasks WHERE id=p_task_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المهمة غير موجودة'; END IF;
  PERFORM 1 FROM project_tasks WHERE company_id=p_company_id AND project_id=v_task.project_id FOR UPDATE;
  IF EXISTS(
    WITH RECURSIVE tree AS (
      SELECT id,progress FROM project_tasks WHERE id=p_task_id AND company_id=p_company_id
      UNION ALL SELECT child.id,child.progress FROM project_tasks child JOIN tree parent ON child.parent_task_id=parent.id
        WHERE child.company_id=p_company_id AND child.project_id=v_task.project_id
    ) SELECT 1 FROM tree WHERE COALESCE(progress,0)>0
  ) THEN RAISE EXCEPTION 'لا يمكن حذف مهمة أو مهمة فرعية بدأ تنفيذها'; END IF;
  WITH RECURSIVE tree AS (
    SELECT id FROM project_tasks WHERE id=p_task_id AND company_id=p_company_id
    UNION ALL SELECT child.id FROM project_tasks child JOIN tree parent ON child.parent_task_id=parent.id
      WHERE child.company_id=p_company_id AND child.project_id=v_task.project_id
  ) DELETE FROM project_tasks WHERE id IN(SELECT id FROM tree) AND company_id=p_company_id;
  GET DIAGNOSTICS v_count=ROW_COUNT;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values)
  VALUES(p_company_id,p_user_id,'delete','project_task',p_task_id,to_jsonb(v_task));
  RETURN jsonb_build_object('id',p_task_id,'deleted',TRUE,'deleted_tasks',v_count);
END;
$$;
REVOKE ALL ON FUNCTION public.delete_unstarted_project_task_atomic(UUID,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.delete_unstarted_project_task_atomic(UUID,UUID,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.delete_draft_tender_atomic(p_company_id UUID,p_tender_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_tender tenders%ROWTYPE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  SELECT * INTO v_tender FROM tenders WHERE id=p_tender_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المناقصة غير موجودة'; END IF;
  IF v_tender.status<>'draft' OR v_tender.project_id IS NOT NULL THEN RAISE EXCEPTION 'لا يمكن حذف مناقصة دخلت دورة العمل'; END IF;
  IF EXISTS(SELECT 1 FROM bonds WHERE tender_id=p_tender_id AND company_id=p_company_id) THEN RAISE EXCEPTION 'لا يمكن حذف مناقصة مرتبطة بضمان'; END IF;
  DELETE FROM tenders WHERE id=p_tender_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values)
  VALUES(p_company_id,p_user_id,'delete','tender',p_tender_id,to_jsonb(v_tender));
  RETURN jsonb_build_object('id',p_tender_id,'deleted',TRUE);
END;
$$;
REVOKE ALL ON FUNCTION public.delete_draft_tender_atomic(UUID,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.delete_draft_tender_atomic(UUID,UUID,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.convert_won_tender_to_project_atomic(p_company_id UUID,p_tender_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_tender tenders%ROWTYPE; v_project JSONB; v_end DATE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  SELECT * INTO v_tender FROM tenders WHERE id=p_tender_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المناقصة غير موجودة'; END IF;
  IF v_tender.project_id IS NOT NULL THEN RETURN jsonb_build_object('project',jsonb_build_object('id',v_tender.project_id),'tender_id',p_tender_id,'already_processed',TRUE); END IF;
  IF v_tender.status<>'won' THEN RAISE EXCEPTION 'يمكن تحويل العطاءات الرابحة فقط إلى مشروع'; END IF;
  IF COALESCE(v_tender.estimated_value,0)<=0 THEN RAISE EXCEPTION 'قيمة المناقصة غير صالحة لإنشاء مشروع'; END IF;
  v_end:=CASE WHEN COALESCE(v_tender.project_duration_months,0)>0 THEN CURRENT_DATE+(v_tender.project_duration_months*30) ELSE NULL END;
  v_project:=create_project_atomic(p_company_id,v_tender.title,v_tender.contact_id,v_tender.estimated_value,
    CURRENT_DATE,v_end,'active',COALESCE(v_tender.description,''),COALESCE(v_tender.project_location,''),'[]'::JSONB,FALSE,p_user_id);
  UPDATE projects SET tender_id=p_tender_id WHERE id=(v_project->>'id')::UUID AND company_id=p_company_id
    RETURNING to_jsonb(projects.*) INTO v_project;
  UPDATE tenders SET project_id=(v_project->>'id')::UUID,updated_at=now() WHERE id=p_tender_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'convert_to_project','tender',p_tender_id,jsonb_build_object('project_id',v_project->>'id'));
  RETURN jsonb_build_object('project',v_project,'tender_id',p_tender_id,'already_processed',FALSE);
END;
$$;
REVOKE ALL ON FUNCTION public.convert_won_tender_to_project_atomic(UUID,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.convert_won_tender_to_project_atomic(UUID,UUID,UUID) TO service_role;

-- Tenders and their converted projects reference each other. SET NULL on
-- deletion prevents that legitimate lifecycle link from deadlocking tenant
-- reset/deletion ordering while preserving both links during normal use.
ALTER TABLE tenders DROP CONSTRAINT IF EXISTS tenders_project_id_fkey;
ALTER TABLE tenders ADD CONSTRAINT tenders_project_id_fkey FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL;
ALTER TABLE projects DROP CONSTRAINT IF EXISTS projects_tender_id_fkey;
ALTER TABLE projects ADD CONSTRAINT projects_tender_id_fkey FOREIGN KEY(tender_id) REFERENCES tenders(id) ON DELETE SET NULL;

-- Administrative subscription restrictions must be serialized. Without a
-- row lock, two concurrent reductions based on the same stale snapshot can
-- accidentally re-grant an entitlement that another administrator revoked.
CREATE OR REPLACE FUNCTION public.restrict_subscription_atomic(
  p_subscription_id UUID,
  p_admin_id UUID,
  p_status TEXT DEFAULT NULL,
  p_end_date DATE DEFAULT NULL,
  p_extra_users INTEGER DEFAULT NULL,
  p_extra_branches INTEGER DEFAULT NULL,
  p_extra_storage_gb INTEGER DEFAULT NULL,
  p_notes TEXT DEFAULT NULL
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_old subscriptions%ROWTYPE;
  v_new subscriptions%ROWTYPE;
  v_changed BOOLEAN:=FALSE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM admin_users WHERE id=p_admin_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'inactive admin'; END IF;

  SELECT * INTO v_old FROM subscriptions WHERE id=p_subscription_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الاشتراك غير موجود'; END IF;

  IF p_status IS NOT NULL THEN
    IF p_status NOT IN ('cancelled','expired') THEN
      RAISE EXCEPTION 'لا يمكن منح حالة اشتراك مدفوعة من هذا المسار';
    END IF;
    v_changed:=v_changed OR p_status IS DISTINCT FROM v_old.status;
  END IF;
  IF p_end_date IS NOT NULL THEN
    IF v_old.end_date IS NULL OR p_end_date>v_old.end_date THEN
      RAISE EXCEPTION 'تمديد الاشتراك يتطلب دفعاً معتمداً';
    END IF;
    v_changed:=v_changed OR p_end_date IS DISTINCT FROM v_old.end_date;
  END IF;
  IF p_extra_users IS NOT NULL THEN
    IF p_extra_users<0 OR p_extra_users>COALESCE(v_old.extra_users,0) THEN
      RAISE EXCEPTION 'لا يمكن زيادة المستخدمين الإضافيين من هذا المسار';
    END IF;
    v_changed:=v_changed OR p_extra_users IS DISTINCT FROM COALESCE(v_old.extra_users,0);
  END IF;
  IF p_extra_branches IS NOT NULL THEN
    IF p_extra_branches<0 OR p_extra_branches>COALESCE(v_old.extra_branches,0) THEN
      RAISE EXCEPTION 'لا يمكن زيادة الفروع الإضافية من هذا المسار';
    END IF;
    v_changed:=v_changed OR p_extra_branches IS DISTINCT FROM COALESCE(v_old.extra_branches,0);
  END IF;
  IF p_extra_storage_gb IS NOT NULL THEN
    IF p_extra_storage_gb<0 OR p_extra_storage_gb>COALESCE(v_old.extra_storage_gb,0) THEN
      RAISE EXCEPTION 'لا يمكن زيادة التخزين الإضافي من هذا المسار';
    END IF;
    v_changed:=v_changed OR p_extra_storage_gb IS DISTINCT FROM COALESCE(v_old.extra_storage_gb,0);
  END IF;
  IF NOT v_changed THEN RAISE EXCEPTION 'لا توجد تغييرات مسموحة'; END IF;

  UPDATE subscriptions SET
    status=COALESCE(p_status,status),
    auto_renew=CASE WHEN p_status='cancelled' THEN FALSE ELSE auto_renew END,
    end_date=COALESCE(p_end_date,end_date),
    extra_users=COALESCE(p_extra_users,extra_users),
    extra_branches=COALESCE(p_extra_branches,extra_branches),
    extra_storage_gb=COALESCE(p_extra_storage_gb,extra_storage_gb),
    updated_at=NOW()
  WHERE id=p_subscription_id RETURNING * INTO v_new;

  IF p_extra_users IS NOT NULL AND p_extra_users IS DISTINCT FROM COALESCE(v_old.extra_users,0) THEN
    INSERT INTO addon_grant_audit(company_id,admin_id,addon_type,quantity,months_granted,
      previous_extra_users,previous_extra_branches,new_extra_users,new_extra_branches,note)
    VALUES(v_old.company_id,p_admin_id,'extra_user',COALESCE(v_old.extra_users,0)-p_extra_users,0,
      COALESCE(v_old.extra_users,0),COALESCE(v_old.extra_branches,0),p_extra_users,COALESCE(v_new.extra_branches,0),LEFT(p_notes,2000));
  END IF;
  IF p_extra_branches IS NOT NULL AND p_extra_branches IS DISTINCT FROM COALESCE(v_old.extra_branches,0) THEN
    INSERT INTO addon_grant_audit(company_id,admin_id,addon_type,quantity,months_granted,
      previous_extra_users,previous_extra_branches,new_extra_users,new_extra_branches,note)
    VALUES(v_old.company_id,p_admin_id,'extra_branch',COALESCE(v_old.extra_branches,0)-p_extra_branches,0,
      COALESCE(v_old.extra_users,0),COALESCE(v_old.extra_branches,0),COALESCE(v_new.extra_users,0),p_extra_branches,LEFT(p_notes,2000));
  END IF;
  IF p_extra_storage_gb IS NOT NULL AND p_extra_storage_gb IS DISTINCT FROM COALESCE(v_old.extra_storage_gb,0) THEN
    INSERT INTO addon_grant_audit(company_id,admin_id,addon_type,quantity,months_granted,
      previous_extra_users,previous_extra_branches,new_extra_users,new_extra_branches,note)
    VALUES(v_old.company_id,p_admin_id,'storage_gb',COALESCE(v_old.extra_storage_gb,0)-p_extra_storage_gb,0,
      COALESCE(v_old.extra_users,0),COALESCE(v_old.extra_branches,0),COALESCE(v_new.extra_users,0),COALESCE(v_new.extra_branches,0),LEFT(p_notes,2000));
  END IF;

  INSERT INTO admin_audit_log(admin_id,action,details,target_type,target_id)
  VALUES(p_admin_id,'restrict_subscription',LEFT(jsonb_build_object(
    'before',to_jsonb(v_old),'after',to_jsonb(v_new),'notes',p_notes)::TEXT,2000),
    'subscription',p_subscription_id::TEXT);
  RETURN to_jsonb(v_new);
END;
$$;
REVOKE ALL ON FUNCTION public.restrict_subscription_atomic(UUID,UUID,TEXT,DATE,INTEGER,INTEGER,INTEGER,TEXT) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.restrict_subscription_atomic(UUID,UUID,TEXT,DATE,INTEGER,INTEGER,INTEGER,TEXT) TO service_role;

-- Central-admin status changes are serialized with their audit evidence. This
-- prevents two concurrent requests from disabling every tenant administrator
-- after each observes another active administrator.
CREATE OR REPLACE FUNCTION public.set_company_user_status_atomic(
  p_user_id UUID,p_admin_id UUID,p_is_active BOOLEAN
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old users%ROWTYPE; v_new users%ROWTYPE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM admin_users WHERE id=p_admin_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'inactive admin'; END IF;
  IF p_is_active IS NULL THEN RAISE EXCEPTION 'invalid status'; END IF;
  SELECT * INTO v_old FROM users WHERE id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المستخدم غير موجود'; END IF;
  PERFORM 1 FROM users WHERE company_id=v_old.company_id AND role='admin' ORDER BY id FOR UPDATE;
  IF NOT p_is_active AND v_old.is_active AND v_old.role='admin' AND
    (SELECT count(*) FROM users WHERE company_id=v_old.company_id AND role='admin' AND is_active=TRUE)<=1
  THEN RAISE EXCEPTION 'لا يمكن تعطيل آخر مدير نشط للشركة'; END IF;
  UPDATE users SET is_active=p_is_active,
    token_version=CASE WHEN NOT p_is_active AND COALESCE(is_active,FALSE)
      THEN COALESCE(token_version,0)+1 ELSE token_version END,
    updated_at=NOW()
  WHERE id=p_user_id RETURNING * INTO v_new;
  INSERT INTO admin_audit_log(admin_id,action,details,target_type,target_id)
  VALUES(p_admin_id,CASE WHEN p_is_active THEN 'activate_user' ELSE 'deactivate_user' END,
    LEFT(jsonb_build_object('company_id',v_old.company_id,'email',v_old.email,
      'previous_state',v_old.is_active,'new_state',v_new.is_active)::TEXT,2000),'user',p_user_id::TEXT);
  RETURN jsonb_build_object('id',v_new.id,'company_id',v_new.company_id,'is_active',v_new.is_active);
END;
$$;
REVOKE ALL ON FUNCTION public.set_company_user_status_atomic(UUID,UUID,BOOLEAN) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.set_company_user_status_atomic(UUID,UUID,BOOLEAN) TO service_role;

CREATE OR REPLACE FUNCTION public.set_company_status_atomic(
  p_company_id UUID,p_admin_id UUID,p_is_active BOOLEAN
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old companies%ROWTYPE; v_new companies%ROWTYPE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM admin_users WHERE id=p_admin_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'inactive admin'; END IF;
  IF p_is_active IS NULL THEN RAISE EXCEPTION 'invalid status'; END IF;
  SELECT * INTO v_old FROM companies WHERE id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الشركة غير موجودة'; END IF;
  UPDATE companies SET is_active=p_is_active,updated_at=NOW()
    WHERE id=p_company_id RETURNING * INTO v_new;
  INSERT INTO admin_audit_log(admin_id,action,details,target_type,target_id)
  VALUES(p_admin_id,CASE WHEN p_is_active THEN 'activate_company' ELSE 'deactivate_company' END,
    LEFT(jsonb_build_object('name',v_old.name,'previous_state',v_old.is_active,'new_state',v_new.is_active)::TEXT,2000),
    'company',p_company_id::TEXT);
  RETURN jsonb_build_object('id',v_new.id,'is_active',v_new.is_active);
END;
$$;
REVOKE ALL ON FUNCTION public.set_company_status_atomic(UUID,UUID,BOOLEAN) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.set_company_status_atomic(UUID,UUID,BOOLEAN) TO service_role;

CREATE OR REPLACE FUNCTION public.delete_unused_subscription_plan_atomic(
  p_plan_id UUID,p_admin_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_plan subscription_plans%ROWTYPE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM admin_users WHERE id=p_admin_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'inactive admin'; END IF;
  SELECT * INTO v_plan FROM subscription_plans WHERE id=p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الباقة غير موجودة'; END IF;
  PERFORM 1 FROM subscriptions WHERE plan_id=p_plan_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM subscriptions WHERE plan_id=p_plan_id) THEN
    RAISE EXCEPTION 'لا يمكن حذف باقة لها اشتراكات تاريخية؛ عطّلها بدلاً من ذلك';
  END IF;
  DELETE FROM subscription_plans WHERE id=p_plan_id;
  INSERT INTO admin_audit_log(admin_id,action,details,target_type,target_id)
  VALUES(p_admin_id,'delete_subscription_plan',LEFT(to_jsonb(v_plan)::TEXT,2000),'subscription_plan',p_plan_id::TEXT);
  RETURN jsonb_build_object('id',p_plan_id,'deleted',TRUE);
END;
$$;
REVOKE ALL ON FUNCTION public.delete_unused_subscription_plan_atomic(UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.delete_unused_subscription_plan_atomic(UUID,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.create_activation_code_batch_atomic(
  p_admin_id UUID,p_plan_code TEXT,p_duration_months INTEGER,p_company_id UUID,
  p_expires_at DATE,p_addon_type TEXT,p_addon_quantity INTEGER,p_notes TEXT,p_hashes JSONB
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_hash JSONB; v_count INTEGER;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM admin_users WHERE id=p_admin_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'inactive admin'; END IF;
  IF jsonb_typeof(p_hashes)<>'array' THEN RAISE EXCEPTION 'invalid code batch'; END IF;
  v_count:=jsonb_array_length(p_hashes);
  IF v_count<1 OR v_count>50 OR
    (SELECT count(DISTINCT value#>>'{}') FROM jsonb_array_elements(p_hashes))<>v_count
  THEN RAISE EXCEPTION 'invalid code batch'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_hashes) h
    WHERE (h#>>'{}') !~ '^[0-9a-f]{64}$') THEN RAISE EXCEPTION 'invalid code hash'; END IF;
  IF p_company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM companies WHERE id=p_company_id)
  THEN RAISE EXCEPTION 'target company not found'; END IF;
  IF p_expires_at IS NOT NULL AND p_expires_at<=CURRENT_DATE THEN RAISE EXCEPTION 'invalid expiry'; END IF;

  IF p_addon_type IS NULL THEN
    IF p_duration_months IS NULL OR p_duration_months<1 OR p_duration_months>120
      OR NOT EXISTS(SELECT 1 FROM subscription_plans WHERE code=p_plan_code AND is_active=TRUE)
    THEN RAISE EXCEPTION 'activation plan is unavailable'; END IF;
  ELSE
    IF p_addon_type NOT IN('extra_user','extra_branch','storage_gb')
      OR p_addon_quantity IS NULL OR p_addon_quantity<1 OR p_addon_quantity>10000
    THEN RAISE EXCEPTION 'invalid add-on'; END IF;
  END IF;

  FOR v_hash IN SELECT value FROM jsonb_array_elements(p_hashes) LOOP
    INSERT INTO activation_codes(code,code_hash,plan_code,duration_months,plan_duration_months,
      target_company_id,expires_at,addon_type,addon_quantity,notes,is_used,one_time)
    VALUES(NULL,v_hash#>>'{}',CASE WHEN p_addon_type IS NULL THEN p_plan_code ELSE NULL END,
      CASE WHEN p_addon_type IS NULL THEN p_duration_months ELSE NULL END,
      CASE WHEN p_addon_type IS NULL THEN p_duration_months ELSE NULL END,p_company_id,p_expires_at,
      p_addon_type,CASE WHEN p_addon_type IS NULL THEN NULL ELSE p_addon_quantity END,
      NULLIF(LEFT(BTRIM(p_notes),1000),''),FALSE,TRUE);
  END LOOP;
  INSERT INTO admin_audit_log(admin_id,action,details,target_type,target_id)
  VALUES(p_admin_id,'create_activation_codes',LEFT(jsonb_build_object('count',v_count,
    'plan_code',p_plan_code,'addon_type',p_addon_type,'target_company_id',p_company_id)::TEXT,2000),
    'activation_code_batch',NULL);
  RETURN jsonb_build_object('count',v_count);
END;
$$;
REVOKE ALL ON FUNCTION public.create_activation_code_batch_atomic(UUID,TEXT,INTEGER,UUID,DATE,TEXT,INTEGER,TEXT,JSONB) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_activation_code_batch_atomic(UUID,TEXT,INTEGER,UUID,DATE,TEXT,INTEGER,TEXT,JSONB) TO service_role;

-- Complete the subcontractor payment schema used by the API. Older schemas
-- had no source safe or explanatory note, making cash-ledger reconciliation
-- impossible.
ALTER TABLE subcontractor_payments ADD COLUMN IF NOT EXISTS bank_safe_id UUID REFERENCES banks_safes(id);
ALTER TABLE subcontractor_payments ADD COLUMN IF NOT EXISTS notes TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_subcontractor_certificate_journal
  ON subcontractor_certificates(journal_entry_id) WHERE journal_entry_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_subcontractor_payment_journal
  ON subcontractor_payments(journal_entry_id) WHERE journal_entry_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.create_subcontractor_certificate_atomic(
  p_company_id UUID,p_contract_id UUID,p_date DATE,p_certificate_number INTEGER,
  p_description TEXT,p_gross_amount NUMERIC,p_retention_rate NUMERIC,p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_contract subcontractor_contracts%ROWTYPE; v_cert subcontractor_certificates%ROWTYPE;
  v_cost UUID; v_payable UUID; v_retention_account UUID; v_retention NUMERIC; v_net NUMERIC;
  v_claimed NUMERIC; v_lines JSONB; v_journal JSONB; v_journal_id UUID;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  IF p_date IS NULL OR p_certificate_number IS NULL OR p_certificate_number<=0
    OR p_gross_amount IS NULL OR p_gross_amount<=0 OR p_gross_amount<>ROUND(p_gross_amount,2)
    OR p_retention_rate IS NULL OR p_retention_rate<0 OR p_retention_rate>1
    OR p_retention_rate<>ROUND(p_retention_rate,2) OR LENGTH(COALESCE(p_description,''))>2000
  THEN RAISE EXCEPTION 'بيانات الشهادة غير صالحة'; END IF;
  SELECT * INTO v_contract FROM subcontractor_contracts
    WHERE id=p_contract_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'العقد غير موجود'; END IF;
  IF v_contract.status<>'active' THEN RAISE EXCEPTION 'العقد غير نشط'; END IF;
  IF NOT EXISTS(SELECT 1 FROM contacts WHERE id=v_contract.contact_id AND company_id=p_company_id)
    OR (v_contract.project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects WHERE id=v_contract.project_id AND company_id=p_company_id))
  THEN RAISE EXCEPTION 'ارتباطات العقد لا تنتمي إلى الشركة'; END IF;
  PERFORM 1 FROM subcontractor_certificates WHERE contract_id=p_contract_id AND company_id=p_company_id FOR UPDATE;
  SELECT COALESCE(SUM(amount),0) INTO v_claimed FROM subcontractor_certificates
    WHERE contract_id=p_contract_id AND company_id=p_company_id AND status IN('pending','approved','paid');
  IF COALESCE(v_contract.contract_value,0)<=0 OR v_claimed+p_gross_amount>v_contract.contract_value+0.005
  THEN RAISE EXCEPTION 'قيمة الشهادة تتجاوز المتبقي من العقد'; END IF;

  SELECT id INTO v_cost FROM accounts WHERE company_id=p_company_id AND code='5100'
    AND COALESCE(is_active,TRUE)=TRUE AND COALESCE(is_header,FALSE)=FALSE FOR UPDATE;
  SELECT id INTO v_payable FROM accounts WHERE company_id=p_company_id AND code='2150'
    AND COALESCE(is_active,TRUE)=TRUE AND COALESCE(is_header,FALSE)=FALSE FOR UPDATE;
  IF v_cost IS NULL OR v_payable IS NULL THEN RAISE EXCEPTION 'حسابات تكلفة أو ذمم مقاولي الباطن غير موجودة'; END IF;
  v_retention:=ROUND(p_gross_amount*p_retention_rate,2); v_net:=p_gross_amount-v_retention;
  IF v_retention>0 THEN
    SELECT id INTO v_retention_account FROM accounts WHERE company_id=p_company_id AND code='2160'
      AND COALESCE(is_active,TRUE)=TRUE AND COALESCE(is_header,FALSE)=FALSE FOR UPDATE;
    IF v_retention_account IS NULL THEN RAISE EXCEPTION 'حساب محجوزات الضمان غير موجود'; END IF;
  END IF;

  INSERT INTO subcontractor_certificates(company_id,contract_id,number,amount,retention,net_amount,date,status,
    journal_entry_id,description,retention_amount,retention_rate)
  VALUES(p_company_id,p_contract_id,p_certificate_number,p_gross_amount,v_retention,v_net,p_date,'approved',
    NULL,NULLIF(BTRIM(p_description),''),v_retention,p_retention_rate) RETURNING * INTO v_cert;
  v_lines:=jsonb_build_array(
    jsonb_build_object('accountId',v_cost,'debit',p_gross_amount,'credit',0,'description','شهادة مقاول باطن '||p_certificate_number,'projectId',v_contract.project_id,'contactId',v_contract.contact_id),
    jsonb_build_object('accountId',v_payable,'debit',0,'credit',v_net,'description','ذمم شهادة مقاول باطن '||p_certificate_number,'projectId',v_contract.project_id,'contactId',v_contract.contact_id));
  IF v_retention>0 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
    'accountId',v_retention_account,'debit',0,'credit',v_retention,'description','محجوز ضمان شهادة '||p_certificate_number,
    'projectId',v_contract.project_id,'contactId',v_contract.contact_id)); END IF;
  v_journal:=create_journal_entry(p_company_id,p_date,'general','شهادة مقاول باطن: '||p_certificate_number,p_user_id,v_lines);
  v_journal_id:=(v_journal->>'id')::UUID;
  UPDATE journal_entries SET reference_type='subcon_certificate',reference_id=v_cert.id
    WHERE id=v_journal_id AND company_id=p_company_id;
  UPDATE subcontractor_certificates SET journal_entry_id=v_journal_id WHERE id=v_cert.id RETURNING * INTO v_cert;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','subcontractor_certificate',v_cert.id,to_jsonb(v_cert));
  RETURN to_jsonb(v_cert)||jsonb_build_object('certificate_number',v_cert.number,'gross_amount',v_cert.amount);
END;
$$;
REVOKE ALL ON FUNCTION public.create_subcontractor_certificate_atomic(UUID,UUID,DATE,INTEGER,TEXT,NUMERIC,NUMERIC,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_subcontractor_certificate_atomic(UUID,UUID,DATE,INTEGER,TEXT,NUMERIC,NUMERIC,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.create_subcontractor_payment_atomic(
  p_company_id UUID,p_contract_id UUID,p_certificate_id UUID,p_amount NUMERIC,p_date DATE,
  p_bank_safe_id UUID,p_notes TEXT,p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_contract subcontractor_contracts%ROWTYPE; v_cert subcontractor_certificates%ROWTYPE;
  v_payment subcontractor_payments%ROWTYPE; v_bank_account UUID; v_payable UUID; v_available NUMERIC;
  v_balance NUMERIC; v_lines JSONB; v_journal JSONB; v_journal_id UUID;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  IF p_date IS NULL OR p_amount IS NULL OR p_amount<=0 OR p_amount<>ROUND(p_amount,2)
    OR LENGTH(COALESCE(p_notes,''))>2000 THEN RAISE EXCEPTION 'بيانات الدفعة غير صالحة'; END IF;
  SELECT * INTO v_contract FROM subcontractor_contracts
    WHERE id=p_contract_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'العقد غير موجود'; END IF;
  IF v_contract.status='cancelled' THEN RAISE EXCEPTION 'العقد ملغى'; END IF;
  IF NOT EXISTS(SELECT 1 FROM contacts WHERE id=v_contract.contact_id AND company_id=p_company_id)
  THEN RAISE EXCEPTION 'مقاول العقد لا ينتمي إلى الشركة'; END IF;
  SELECT account_id INTO v_bank_account FROM banks_safes WHERE id=p_bank_safe_id AND company_id=p_company_id
    AND COALESCE(is_active,TRUE)=TRUE FOR UPDATE;
  IF v_bank_account IS NULL THEN RAISE EXCEPTION 'الخزينة أو البنك غير صالح'; END IF;
  PERFORM 1 FROM accounts WHERE id=v_bank_account AND company_id=p_company_id FOR UPDATE;
  SELECT id INTO v_payable FROM accounts WHERE company_id=p_company_id AND code='2150'
    AND COALESCE(is_active,TRUE)=TRUE AND COALESCE(is_header,FALSE)=FALSE FOR UPDATE;
  IF v_payable IS NULL THEN RAISE EXCEPTION 'حساب ذمم مقاولي الباطن غير موجود'; END IF;

  PERFORM 1 FROM subcontractor_certificates WHERE contract_id=p_contract_id AND company_id=p_company_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM subcontractor_payments WHERE contract_id=p_contract_id AND company_id=p_company_id ORDER BY id FOR UPDATE;
  IF p_certificate_id IS NOT NULL THEN
    SELECT * INTO v_cert FROM subcontractor_certificates WHERE id=p_certificate_id AND contract_id=p_contract_id
      AND company_id=p_company_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'الشهادة غير موجودة أو لا تخص العقد'; END IF;
    IF v_cert.status NOT IN('approved','paid') THEN RAISE EXCEPTION 'الشهادة غير معتمدة'; END IF;
    SELECT v_cert.net_amount-COALESCE(SUM(amount),0) INTO v_available FROM subcontractor_payments
      WHERE certificate_id=p_certificate_id AND company_id=p_company_id AND COALESCE(status,'paid')='paid';
  ELSE
    SELECT COALESCE(SUM(net_amount),0) INTO v_available FROM subcontractor_certificates
      WHERE contract_id=p_contract_id AND company_id=p_company_id AND status IN('approved','paid');
    v_available:=v_available-COALESCE((SELECT SUM(amount) FROM subcontractor_payments
      WHERE contract_id=p_contract_id AND company_id=p_company_id AND COALESCE(status,'paid')='paid'),0);
  END IF;
  IF v_available+0.005<p_amount THEN RAISE EXCEPTION 'قيمة الدفعة تتجاوز الرصيد المستحق'; END IF;
  v_balance:=get_account_balance(p_company_id,v_bank_account,NULL,NULL);
  IF v_balance+0.005<p_amount THEN RAISE EXCEPTION 'رصيد الخزينة أو البنك غير كاف'; END IF;

  INSERT INTO subcontractor_payments(company_id,certificate_id,contract_id,amount,date,type,journal_entry_id,
    bank_safe_id,notes,created_by,approved_at,status)
  VALUES(p_company_id,p_certificate_id,p_contract_id,p_amount,p_date,'payment',NULL,p_bank_safe_id,
    NULLIF(BTRIM(p_notes),''),p_user_id,NOW(),'paid') RETURNING * INTO v_payment;
  v_lines:=jsonb_build_array(
    jsonb_build_object('accountId',v_payable,'debit',p_amount,'credit',0,'description','دفعة مقاول باطن','projectId',v_contract.project_id,'contactId',v_contract.contact_id),
    jsonb_build_object('accountId',v_bank_account,'debit',0,'credit',p_amount,'description','صرف دفعة مقاول باطن','projectId',v_contract.project_id,'contactId',v_contract.contact_id));
  v_journal:=create_journal_entry(p_company_id,p_date,'general','دفعة مقاول باطن',p_user_id,v_lines);
  v_journal_id:=(v_journal->>'id')::UUID;
  UPDATE journal_entries SET reference_type='subcontractor_payment',reference_id=v_payment.id
    WHERE id=v_journal_id AND company_id=p_company_id;
  UPDATE subcontractor_payments SET journal_entry_id=v_journal_id WHERE id=v_payment.id RETURNING * INTO v_payment;
  IF p_certificate_id IS NOT NULL AND ABS(v_available-p_amount)<=0.005 THEN
    UPDATE subcontractor_certificates SET status='paid' WHERE id=p_certificate_id AND company_id=p_company_id;
  END IF;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','subcontractor_payment',v_payment.id,to_jsonb(v_payment));
  RETURN to_jsonb(v_payment);
END;
$$;
REVOKE ALL ON FUNCTION public.create_subcontractor_payment_atomic(UUID,UUID,UUID,NUMERIC,DATE,UUID,TEXT,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_subcontractor_payment_atomic(UUID,UUID,UUID,NUMERIC,DATE,UUID,TEXT,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.reverse_journal_entry_atomic(
  p_company_id UUID,p_journal_entry_id UUID,p_reverse_date DATE,p_description TEXT,
  p_reference_type TEXT,p_reference_id UUID,p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_source journal_entries%ROWTYPE; v_existing UUID; v_lines JSONB; v_journal JSONB; v_reversal UUID;
BEGIN
  IF p_reverse_date IS NULL OR NULLIF(BTRIM(p_description),'') IS NULL OR LENGTH(p_description)>2000
  THEN RAISE EXCEPTION 'بيانات القيد العكسي غير صالحة'; END IF;
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('fiscal-ledger:'||p_company_id::TEXT,0));
  SELECT * INTO v_source FROM journal_entries WHERE id=p_journal_entry_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'القيد الأصلي غير موجود'; END IF;
  IF v_source.reversed_by IS NOT NULL THEN
    RETURN jsonb_build_object('id',v_source.reversed_by,'source_id',v_source.id,'already_processed',TRUE);
  END IF;
  SELECT id INTO v_existing FROM journal_entries WHERE company_id=p_company_id AND reversal_of=p_journal_entry_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    UPDATE journal_entries SET reversed_by=v_existing WHERE id=p_journal_entry_id;
    RETURN jsonb_build_object('id',v_existing,'source_id',v_source.id,'already_processed',TRUE);
  END IF;
  SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'debit',credit,'credit',debit,
    'description','عكس: '||COALESCE(description,''),'projectId',project_id,'contactId',contact_id) ORDER BY id)
    INTO v_lines FROM journal_lines WHERE journal_entry_id=p_journal_entry_id AND company_id=p_company_id;
  IF v_lines IS NULL OR jsonb_array_length(v_lines)<2 THEN RAISE EXCEPTION 'القيد الأصلي لا يحتوي على سطور مكتملة'; END IF;
  v_journal:=create_journal_entry(p_company_id,p_reverse_date,'reversing',BTRIM(p_description),p_user_id,v_lines);
  v_reversal:=(v_journal->>'id')::UUID;
  UPDATE journal_entries SET reference_type=NULLIF(BTRIM(p_reference_type),''),reference_id=p_reference_id,
    reversal_of=p_journal_entry_id WHERE id=v_reversal AND company_id=p_company_id;
  UPDATE journal_entries SET reversed_by=v_reversal WHERE id=p_journal_entry_id AND company_id=p_company_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'reverse','journal_entry',p_journal_entry_id,
    to_jsonb(v_source),jsonb_build_object('reversal_id',v_reversal,'reverse_date',p_reverse_date));
  RETURN jsonb_build_object('id',v_reversal,'number',v_journal->'number','source_id',v_source.id,'already_processed',FALSE);
END;
$$;
REVOKE ALL ON FUNCTION public.reverse_journal_entry_atomic(UUID,UUID,DATE,TEXT,TEXT,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reverse_journal_entry_atomic(UUID,UUID,DATE,TEXT,TEXT,UUID,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.close_fiscal_year_atomic(
  p_company_id UUID,p_fiscal_year_id UUID,p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_year fiscal_years%ROWTYPE; v_account RECORD; v_retained UUID; v_lines JSONB:='[]'::JSONB;
  v_total_revenue NUMERIC:=0; v_total_expenses NUMERIC:=0; v_net NUMERIC:=0;
  v_journal JSONB; v_journal_id UUID; v_warnings JSONB:='[]'::JSONB;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('fiscal-ledger:'||p_company_id::TEXT,0));
  SELECT * INTO v_year FROM fiscal_years WHERE id=p_fiscal_year_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'السنة المالية غير موجودة'; END IF;
  IF v_year.status='closed' THEN RETURN to_jsonb(v_year)||jsonb_build_object('already_processed',TRUE); END IF;
  IF EXISTS(SELECT 1 FROM fiscal_years WHERE company_id=p_company_id AND status='open' AND start_date<v_year.start_date)
  THEN RAISE EXCEPTION 'يجب إقفال السنوات المالية الأقدم أولاً'; END IF;
  IF EXISTS(SELECT 1 FROM custodies WHERE company_id=p_company_id AND status='open')
  THEN RAISE EXCEPTION 'لا يمكن إقفال السنة والعهد مفتوحة'; END IF;
  IF EXISTS(SELECT 1 FROM projects WHERE company_id=p_company_id AND status='active')
  THEN v_warnings:=jsonb_build_array('هناك مشاريع نشطة'); END IF;
  SELECT id INTO v_retained FROM accounts WHERE company_id=p_company_id AND code='3200'
    AND COALESCE(is_active,TRUE)=TRUE AND COALESCE(is_header,FALSE)=FALSE FOR UPDATE;
  IF v_retained IS NULL THEN RAISE EXCEPTION 'حساب الأرباح المحتجزة غير موجود'; END IF;

  FOR v_account IN
    SELECT a.id,a.name,a.type,ROUND(COALESCE(b.balance,0),2) AS balance
    FROM accounts a LEFT JOIN (
      SELECT jl.account_id,SUM(jl.debit-jl.credit) AS balance
      FROM journal_lines jl JOIN journal_entries je
        ON je.id=jl.journal_entry_id AND je.company_id=jl.company_id
      WHERE je.company_id=p_company_id AND je.date BETWEEN v_year.start_date AND v_year.end_date
        AND je.type<>'closing'
        AND NOT(COALESCE(je.reference_type,'')='fiscal_year_reopen' AND je.reference_id=p_fiscal_year_id)
      GROUP BY jl.account_id
    ) b ON b.account_id=a.id
    WHERE a.company_id=p_company_id AND a.type IN('revenue','expense') AND COALESCE(a.is_active,TRUE)=TRUE
    ORDER BY a.code
  LOOP
    IF ABS(v_account.balance)<=0.005 THEN CONTINUE; END IF;
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('accountId',v_account.id,
      'debit',CASE WHEN v_account.balance<0 THEN ABS(v_account.balance) ELSE 0 END,
      'credit',CASE WHEN v_account.balance>0 THEN v_account.balance ELSE 0 END,
      'description','إقفال '||CASE WHEN v_account.type='revenue' THEN 'إيراد ' ELSE 'مصروف ' END||v_account.name));
    IF v_account.type='revenue' THEN v_total_revenue:=v_total_revenue-v_account.balance;
    ELSE v_total_expenses:=v_total_expenses+v_account.balance; END IF;
  END LOOP;
  v_total_revenue:=ROUND(v_total_revenue,2); v_total_expenses:=ROUND(v_total_expenses,2);
  v_net:=ROUND(v_total_revenue-v_total_expenses,2);
  IF jsonb_array_length(v_lines)>0 THEN
    IF v_net>0.005 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'accountId',v_retained,'debit',0,'credit',v_net,'description','نقل صافي الربح إلى الأرباح المحتجزة'));
    ELSIF v_net< -0.005 THEN v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'accountId',v_retained,'debit',ABS(v_net),'credit',0,'description','نقل صافي الخسارة إلى الأرباح المحتجزة'));
    END IF;
    v_journal:=create_journal_entry(p_company_id,v_year.end_date,'closing',
      'قيد إقفال السنة المالية '||COALESCE(v_year.name,''),p_user_id,v_lines);
    v_journal_id:=(v_journal->>'id')::UUID;
    UPDATE journal_entries SET reference_type='fiscal_year_closing',reference_id=p_fiscal_year_id
      WHERE id=v_journal_id AND company_id=p_company_id;
  END IF;
  UPDATE fiscal_years SET status='closed',closed_at=NOW(),closed_by=p_user_id,closing_date=CURRENT_DATE,
    closing_entries=CASE WHEN v_journal_id IS NULL THEN '[]'::JSONB ELSE jsonb_build_array(v_journal_id) END
    WHERE id=p_fiscal_year_id RETURNING * INTO v_year;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'close','fiscal_year',p_fiscal_year_id,jsonb_build_object(
    'closing_journal_id',v_journal_id,'total_revenue',v_total_revenue,'total_expenses',v_total_expenses,'net_income',v_net));
  RETURN to_jsonb(v_year)||jsonb_build_object('closing_journal_id',v_journal_id,'totalRevenue',v_total_revenue,
    'totalExpenses',v_total_expenses,'netIncome',v_net,'warnings',v_warnings,'already_processed',FALSE);
END;
$$;
REVOKE ALL ON FUNCTION public.close_fiscal_year_atomic(UUID,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.close_fiscal_year_atomic(UUID,UUID,UUID) TO service_role;

CREATE OR REPLACE FUNCTION public.reopen_fiscal_year_atomic(
  p_company_id UUID,p_fiscal_year_id UUID,p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_year fiscal_years%ROWTYPE; v_closing RECORD; v_reverse JSONB; v_count INTEGER:=0;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('fiscal-ledger:'||p_company_id::TEXT,0));
  SELECT * INTO v_year FROM fiscal_years WHERE id=p_fiscal_year_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'السنة المالية غير موجودة'; END IF;
  IF v_year.status<>'closed' THEN RAISE EXCEPTION 'السنة المالية غير مقفلة'; END IF;
  IF EXISTS(SELECT 1 FROM fiscal_years WHERE company_id=p_company_id AND status='closed' AND start_date>v_year.start_date)
  THEN RAISE EXCEPTION 'لا يمكن إعادة فتح السنة قبل السنوات الأحدث'; END IF;
  UPDATE fiscal_years SET status='open',closed_at=NULL,closed_by=NULL,closing_date=NULL
    WHERE id=p_fiscal_year_id;
  FOR v_closing IN SELECT id,number FROM journal_entries WHERE company_id=p_company_id AND type='closing'
    AND date BETWEEN v_year.start_date AND v_year.end_date ORDER BY date,id FOR UPDATE
  LOOP
    v_reverse:=reverse_journal_entry_atomic(p_company_id,v_closing.id,CURRENT_DATE,
      'عكس قيد الإقفال رقم '||v_closing.number||' عند إعادة فتح السنة '||COALESCE(v_year.name,''),
      'fiscal_year_reopen',p_fiscal_year_id,p_user_id);
    v_count:=v_count+1;
  END LOOP;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'reopen','fiscal_year',p_fiscal_year_id,to_jsonb(v_year),
    jsonb_build_object('reversed_closing_entries',v_count));
  SELECT * INTO v_year FROM fiscal_years WHERE id=p_fiscal_year_id;
  RETURN to_jsonb(v_year)||jsonb_build_object('reversedClosingEntries',v_count);
END;
$$;
REVOKE ALL ON FUNCTION public.reopen_fiscal_year_atomic(UUID,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reopen_fiscal_year_atomic(UUID,UUID,UUID) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 051-atomic-admin-global-configuration.sql
-- ----------------------------------------------------------------------------

-- ============================================================
-- 051 - Atomic administration of global configuration
--
-- Global settings, advertisements, payment methods and support-ticket
-- decisions are security-sensitive writes.  Keep each mutation and its
-- admin audit record in one transaction, and re-check the trusted admin
-- inside SECURITY DEFINER functions (the API uses the service role).
-- ============================================================

BEGIN;

-- Align the database enums with the values exposed by the administration UI.
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN
    SELECT c.conname
    FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum = ANY(c.conkey)
    WHERE n.nspname = 'public' AND t.relname = 'advertisements'
      AND c.contype = 'c' AND a.attname IN ('type', 'display_mode')
  LOOP
    EXECUTE 'ALTER TABLE public.advertisements DROP CONSTRAINT IF EXISTS ' || quote_ident(r.conname);
  END LOOP;
END $$;

UPDATE advertisements SET type='announcement'
WHERE type IS NULL OR type NOT IN ('announcement','banner','promotion','upgrade','alert','info','feature','premium');
UPDATE advertisements SET display_mode='banner'
WHERE display_mode IS NULL OR display_mode NOT IN ('top_bar','banner','popup','modal','inline');
ALTER TABLE advertisements ALTER COLUMN display_mode SET DEFAULT 'banner';

ALTER TABLE advertisements
  ADD CONSTRAINT advertisements_type_check
    CHECK (type IN ('announcement','banner','promotion','upgrade','alert','info','feature','premium')),
  ADD CONSTRAINT advertisements_display_mode_check
    CHECK (display_mode IN ('top_bar','banner','popup','modal','inline'));

CREATE OR REPLACE FUNCTION public.assert_active_admin(p_admin_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_admin_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM admin_users WHERE id = p_admin_id AND is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'inactive admin';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_upsert_app_settings(
  p_admin_id UUID,
  p_updates JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_key TEXT;
  v_value JSONB;
  v_text TEXT;
  v_count INT := 0;
BEGIN
  PERFORM assert_active_admin(p_admin_id);
  IF p_updates IS NULL OR jsonb_typeof(p_updates) <> 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(p_updates)) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'invalid settings payload';
  END IF;

  FOR v_key, v_value IN SELECT key, value FROM jsonb_each(p_updates)
  LOOP
    IF v_key !~ '^[a-z][a-z0-9_]{1,63}$'
       OR jsonb_typeof(v_value) NOT IN ('string','number','boolean') THEN
      RAISE EXCEPTION 'invalid setting key or value';
    END IF;
    v_text := CASE WHEN jsonb_typeof(v_value) = 'string' THEN v_value #>> '{}' ELSE v_value::TEXT END;
    IF length(v_text) > 5000 THEN RAISE EXCEPTION 'setting value too long'; END IF;

    INSERT INTO app_settings(key, value, category, updated_by, updated_at)
    VALUES(v_key, v_text, 'custom', p_admin_id, now())
    ON CONFLICT (key) DO UPDATE
      SET value = EXCLUDED.value, updated_by = p_admin_id, updated_at = now();
    v_count := v_count + 1;
  END LOOP;

  INSERT INTO admin_audit_log(admin_id, action, details, target_type, target_id)
  VALUES(p_admin_id, 'update_app_settings',
    format('updated %s keys: %s', v_count, array_to_string(ARRAY(SELECT jsonb_object_keys(p_updates)), ',')),
    'app_settings', 'bulk');
  RETURN jsonb_build_object('updated', v_count);
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_update_app_setting(
  p_admin_id UUID,
  p_key TEXT,
  p_patch JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_row app_settings%ROWTYPE;
BEGIN
  PERFORM assert_active_admin(p_admin_id);
  IF p_key IS NULL OR p_key !~ '^[a-z][a-z0-9_]{1,63}$'
     OR p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(p_patch)) = 0
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_patch) k WHERE k NOT IN ('value','category','description'))
     OR EXISTS (SELECT 1 FROM jsonb_each(p_patch) item WHERE jsonb_typeof(item.value) <> 'string') THEN
    RAISE EXCEPTION 'invalid setting patch';
  END IF;
  IF p_patch ? 'value' AND length(COALESCE(p_patch->>'value','')) > 5000 THEN RAISE EXCEPTION 'setting value too long'; END IF;
  IF p_patch ? 'category' AND (length(COALESCE(p_patch->>'category','')) > 50 OR COALESCE(p_patch->>'category','') !~ '^[a-z][a-z0-9_-]*$') THEN
    RAISE EXCEPTION 'invalid setting category';
  END IF;
  IF p_patch ? 'description' AND length(COALESCE(p_patch->>'description','')) > 500 THEN RAISE EXCEPTION 'setting description too long'; END IF;

  UPDATE app_settings
  SET value = CASE WHEN p_patch ? 'value' THEN COALESCE(p_patch->>'value','') ELSE value END,
      category = CASE WHEN p_patch ? 'category' THEN p_patch->>'category' ELSE category END,
      description = CASE WHEN p_patch ? 'description' THEN p_patch->>'description' ELSE description END,
      updated_by = p_admin_id,
      updated_at = now()
  WHERE key = p_key
  RETURNING * INTO v_row;
  IF NOT FOUND THEN RETURN jsonb_build_object('not_found', TRUE); END IF;

  INSERT INTO admin_audit_log(admin_id, action, details, target_type, target_id)
  VALUES(p_admin_id, 'update_app_setting', 'updated fields: ' || array_to_string(ARRAY(SELECT jsonb_object_keys(p_patch)), ','), 'app_setting', p_key);
  RETURN to_jsonb(v_row);
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_delete_app_setting(
  p_admin_id UUID,
  p_key TEXT
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_value TEXT;
BEGIN
  PERFORM assert_active_admin(p_admin_id);
  IF p_key IS NULL OR p_key !~ '^[a-z][a-z0-9_]{1,63}$' THEN RAISE EXCEPTION 'invalid setting key'; END IF;
  IF p_key = ANY(ARRAY[
    'app_name','app_name_en','app_version','developer_name','support_email','support_phone',
    'support_whatsapp','support_telegram','support_website','payment_info','payment_bank_name',
    'payment_iban','payment_stc_pay','footer_text','currency_default','locale_default',
    'trial_days','storage_quota_mb'
  ]) THEN
    RETURN jsonb_build_object('protected', TRUE);
  END IF;

  DELETE FROM app_settings WHERE key = p_key RETURNING value INTO v_value;
  IF NOT FOUND THEN RETURN jsonb_build_object('not_found', TRUE); END IF;
  INSERT INTO admin_audit_log(admin_id, action, details, target_type, target_id)
  VALUES(p_admin_id, 'delete_app_setting', 'deleted custom setting', 'app_setting', p_key);
  RETURN jsonb_build_object('deleted', TRUE);
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_manage_advertisement(
  p_admin_id UUID,
  p_action TEXT,
  p_ad_id UUID DEFAULT NULL,
  p_payload JSONB DEFAULT '{}'::JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_ad advertisements%ROWTYPE;
BEGIN
  PERFORM assert_active_admin(p_admin_id);
  IF p_action NOT IN ('create','update','delete') OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'invalid advertisement action';
  END IF;

  IF p_action = 'create' THEN
    IF length(trim(COALESCE(p_payload->>'title',''))) NOT BETWEEN 1 AND 300
       OR length(trim(COALESCE(p_payload->>'body',''))) NOT BETWEEN 1 AND 5000
       OR COALESCE(p_payload->>'type','announcement') NOT IN ('announcement','banner','promotion','upgrade','alert','info','feature','premium')
       OR COALESCE(p_payload->>'display_mode','top_bar') NOT IN ('top_bar','banner','popup','modal','inline')
       OR COALESCE((p_payload->>'priority')::INT,0) NOT BETWEEN -1000 AND 1000
       OR length(COALESCE(p_payload->>'link_text','')) > 200
       OR (NULLIF(p_payload->>'link_url','') IS NOT NULL AND (length(p_payload->>'link_url') > 2000 OR p_payload->>'link_url' !~* '^https?://')) THEN
      RAISE EXCEPTION 'invalid advertisement payload';
    END IF;
    INSERT INTO advertisements(title, body, type, display_mode, priority, link_url, link_text, is_active, expires_at, show_until)
    VALUES(
      trim(p_payload->>'title'), trim(p_payload->>'body'), COALESCE(p_payload->>'type','announcement'),
      COALESCE(p_payload->>'display_mode','top_bar'), COALESCE((p_payload->>'priority')::INT,0),
      NULLIF(p_payload->>'link_url',''), NULLIF(p_payload->>'link_text',''),
      COALESCE((p_payload->>'is_active')::BOOLEAN,TRUE),
      NULLIF(p_payload->>'expires_at','')::TIMESTAMPTZ, NULLIF(p_payload->>'expires_at','')::TIMESTAMPTZ
    ) RETURNING * INTO v_ad;
  ELSE
    IF p_ad_id IS NULL THEN RAISE EXCEPTION 'advertisement id required'; END IF;
    SELECT * INTO v_ad FROM advertisements WHERE id = p_ad_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('not_found', TRUE); END IF;

    IF p_action = 'delete' THEN
      DELETE FROM advertisements WHERE id = p_ad_id;
      INSERT INTO admin_audit_log(admin_id, action, details, target_type, target_id)
      VALUES(p_admin_id, 'delete_advertisement', left(v_ad.title,300), 'advertisement', p_ad_id::TEXT);
      RETURN jsonb_build_object('deleted', TRUE);
    END IF;

    IF p_payload ? 'title' AND length(trim(COALESCE(p_payload->>'title',''))) NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'invalid advertisement title'; END IF;
    IF p_payload ? 'body' AND length(trim(COALESCE(p_payload->>'body',''))) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'invalid advertisement body'; END IF;
    IF p_payload ? 'type' AND p_payload->>'type' NOT IN ('announcement','banner','promotion','upgrade','alert','info','feature','premium') THEN RAISE EXCEPTION 'invalid advertisement type'; END IF;
    IF p_payload ? 'display_mode' AND p_payload->>'display_mode' NOT IN ('top_bar','banner','popup','modal','inline') THEN RAISE EXCEPTION 'invalid advertisement display mode'; END IF;
    IF p_payload ? 'priority' AND (p_payload->>'priority')::INT NOT BETWEEN -1000 AND 1000 THEN RAISE EXCEPTION 'invalid advertisement priority'; END IF;
    IF p_payload ? 'link_text' AND length(COALESCE(p_payload->>'link_text','')) > 200 THEN RAISE EXCEPTION 'invalid advertisement link text'; END IF;
    IF p_payload ? 'link_url' AND NULLIF(p_payload->>'link_url','') IS NOT NULL
       AND (length(p_payload->>'link_url') > 2000 OR p_payload->>'link_url' !~* '^https?://') THEN RAISE EXCEPTION 'invalid advertisement link'; END IF;

    UPDATE advertisements SET
      title = CASE WHEN p_payload ? 'title' THEN trim(p_payload->>'title') ELSE title END,
      body = CASE WHEN p_payload ? 'body' THEN trim(p_payload->>'body') ELSE body END,
      type = CASE WHEN p_payload ? 'type' THEN p_payload->>'type' ELSE type END,
      display_mode = CASE WHEN p_payload ? 'display_mode' THEN p_payload->>'display_mode' ELSE display_mode END,
      priority = CASE WHEN p_payload ? 'priority' THEN (p_payload->>'priority')::INT ELSE priority END,
      link_url = CASE WHEN p_payload ? 'link_url' THEN NULLIF(p_payload->>'link_url','') ELSE link_url END,
      link_text = CASE WHEN p_payload ? 'link_text' THEN NULLIF(p_payload->>'link_text','') ELSE link_text END,
      is_active = CASE WHEN p_payload ? 'is_active' THEN (p_payload->>'is_active')::BOOLEAN ELSE is_active END,
      expires_at = CASE WHEN p_payload ? 'expires_at' THEN NULLIF(p_payload->>'expires_at','')::TIMESTAMPTZ ELSE expires_at END,
      show_until = CASE WHEN p_payload ? 'expires_at' THEN NULLIF(p_payload->>'expires_at','')::TIMESTAMPTZ ELSE show_until END,
      updated_at = now()
    WHERE id = p_ad_id RETURNING * INTO v_ad;
  END IF;

  INSERT INTO admin_audit_log(admin_id, action, details, target_type, target_id)
  VALUES(p_admin_id, p_action || '_advertisement', left(v_ad.title,300), 'advertisement', v_ad.id::TEXT);
  RETURN to_jsonb(v_ad);
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_manage_payment_method(
  p_admin_id UUID,
  p_action TEXT,
  p_method_id UUID DEFAULT NULL,
  p_payload JSONB DEFAULT '{}'::JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_method payment_methods%ROWTYPE;
BEGIN
  PERFORM assert_active_admin(p_admin_id);
  IF p_action NOT IN ('create','update','deactivate') OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'invalid payment method action';
  END IF;

  IF p_action = 'create' THEN
    IF COALESCE(p_payload->>'code','') !~ '^[a-z0-9][a-z0-9_-]{1,49}$'
       OR length(trim(COALESCE(p_payload->>'name_ar',''))) NOT BETWEEN 1 AND 120
       OR length(COALESCE(p_payload->>'name_en','')) > 120
       OR length(COALESCE(p_payload->>'description','')) > 500
       OR length(COALESCE(p_payload->>'account_number','')) > 200
       OR length(COALESCE(p_payload->>'account_name','')) > 200
       OR length(COALESCE(p_payload->>'instructions','')) > 2000
       OR COALESCE((p_payload->>'sort_order')::INT,0) NOT BETWEEN 0 AND 10000 THEN
      RAISE EXCEPTION 'invalid payment method payload';
    END IF;
    INSERT INTO payment_methods(code,name_ar,name_en,description,account_number,account_name,instructions,is_active,sort_order)
    VALUES(
      p_payload->>'code', trim(p_payload->>'name_ar'), NULLIF(p_payload->>'name_en',''),
      NULLIF(p_payload->>'description',''), NULLIF(p_payload->>'account_number',''),
      NULLIF(p_payload->>'account_name',''), NULLIF(p_payload->>'instructions',''),
      COALESCE((p_payload->>'is_active')::BOOLEAN,TRUE), COALESCE((p_payload->>'sort_order')::INT,0)
    ) RETURNING * INTO v_method;
  ELSE
    IF p_method_id IS NULL THEN RAISE EXCEPTION 'payment method id required'; END IF;
    SELECT * INTO v_method FROM payment_methods WHERE id = p_method_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('not_found', TRUE); END IF;
    IF p_action = 'deactivate' THEN
      UPDATE payment_methods SET is_active=FALSE, updated_at=now() WHERE id=p_method_id RETURNING * INTO v_method;
    ELSE
      IF p_payload ? 'name_ar' AND length(trim(COALESCE(p_payload->>'name_ar',''))) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'invalid payment method name'; END IF;
      IF length(COALESCE(p_payload->>'name_en','')) > 120
         OR length(COALESCE(p_payload->>'description','')) > 500
         OR length(COALESCE(p_payload->>'account_number','')) > 200
         OR length(COALESCE(p_payload->>'account_name','')) > 200
         OR length(COALESCE(p_payload->>'instructions','')) > 2000
         OR (p_payload ? 'sort_order' AND (p_payload->>'sort_order')::INT NOT BETWEEN 0 AND 10000) THEN
        RAISE EXCEPTION 'invalid payment method patch';
      END IF;
      UPDATE payment_methods SET
        name_ar = CASE WHEN p_payload ? 'name_ar' THEN trim(p_payload->>'name_ar') ELSE name_ar END,
        name_en = CASE WHEN p_payload ? 'name_en' THEN NULLIF(p_payload->>'name_en','') ELSE name_en END,
        description = CASE WHEN p_payload ? 'description' THEN NULLIF(p_payload->>'description','') ELSE description END,
        account_number = CASE WHEN p_payload ? 'account_number' THEN NULLIF(p_payload->>'account_number','') ELSE account_number END,
        account_name = CASE WHEN p_payload ? 'account_name' THEN NULLIF(p_payload->>'account_name','') ELSE account_name END,
        instructions = CASE WHEN p_payload ? 'instructions' THEN NULLIF(p_payload->>'instructions','') ELSE instructions END,
        is_active = CASE WHEN p_payload ? 'is_active' THEN (p_payload->>'is_active')::BOOLEAN ELSE is_active END,
        sort_order = CASE WHEN p_payload ? 'sort_order' THEN (p_payload->>'sort_order')::INT ELSE sort_order END,
        updated_at = now()
      WHERE id=p_method_id RETURNING * INTO v_method;
    END IF;
  END IF;

  INSERT INTO admin_audit_log(admin_id,action,details,target_type,target_id)
  VALUES(p_admin_id,p_action || '_payment_method',format('code=%s name=%s',v_method.code,v_method.name_ar),'payment_method',v_method.id::TEXT);
  RETURN to_jsonb(v_method) || CASE WHEN p_action='deactivate' THEN jsonb_build_object('deactivated',TRUE) ELSE '{}'::JSONB END;
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_update_support_ticket(
  p_admin_id UUID,
  p_ticket_id UUID,
  p_status TEXT DEFAULT NULL,
  p_admin_notes TEXT DEFAULT NULL,
  p_notes_set BOOLEAN DEFAULT FALSE
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_ticket support_tickets%ROWTYPE; v_label TEXT;
BEGIN
  PERFORM assert_active_admin(p_admin_id);
  IF p_ticket_id IS NULL OR (p_status IS NOT NULL AND p_status NOT IN ('open','in_progress','resolved','closed'))
     OR length(COALESCE(p_admin_notes,'')) > 2000 THEN
    RAISE EXCEPTION 'invalid support update';
  END IF;
  IF p_status IS NULL AND NOT p_notes_set THEN RAISE EXCEPTION 'empty support update'; END IF;

  SELECT * INTO v_ticket FROM support_tickets WHERE id=p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('not_found',TRUE); END IF;
  UPDATE support_tickets SET
    status=COALESCE(p_status,status),
    admin_notes=CASE WHEN p_notes_set THEN p_admin_notes ELSE admin_notes END,
    updated_at=now()
  WHERE id=p_ticket_id RETURNING * INTO v_ticket;

  v_label := CASE v_ticket.status WHEN 'open' THEN 'مفتوحة' WHEN 'in_progress' THEN 'قيد المعالجة' WHEN 'resolved' THEN 'تم الحل' ELSE 'مغلقة' END;
  IF (p_status IS NOT NULL OR p_notes_set) AND v_ticket.user_id IS NOT NULL THEN
    INSERT INTO company_messages(company_id,user_id,subject,body,type,status)
    VALUES(v_ticket.company_id,v_ticket.user_id,'تحديث للتذكرة: ' || v_ticket.subject,
      'تم تحديث حالة تذكرة الدعم الخاصة بك إلى: ' || v_label || '.' ||
      CASE WHEN p_notes_set AND COALESCE(p_admin_notes,'')<>'' THEN E'\nرد الإدارة: ' || p_admin_notes ELSE '' END,
      'support','open');
  END IF;
  INSERT INTO admin_audit_log(admin_id,action,details,target_type,target_id)
  VALUES(p_admin_id,'update_support_ticket',format('company=%s status=%s',v_ticket.company_id,v_ticket.status),'support_ticket',v_ticket.id::TEXT);
  RETURN jsonb_build_object('id',v_ticket.id,'status',v_ticket.status,'company_id',v_ticket.company_id);
END;
$$;

REVOKE ALL ON FUNCTION public.assert_active_admin(UUID) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_upsert_app_settings(UUID,JSONB) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_update_app_setting(UUID,TEXT,JSONB) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_delete_app_setting(UUID,TEXT) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_manage_advertisement(UUID,TEXT,UUID,JSONB) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_manage_payment_method(UUID,TEXT,UUID,JSONB) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_update_support_ticket(UUID,UUID,TEXT,TEXT,BOOLEAN) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_upsert_app_settings(UUID,JSONB) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_update_app_setting(UUID,TEXT,JSONB) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_delete_app_setting(UUID,TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_manage_advertisement(UUID,TEXT,UUID,JSONB) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_manage_payment_method(UUID,TEXT,UUID,JSONB) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_update_support_ticket(UUID,UUID,TEXT,TEXT,BOOLEAN) TO service_role;

COMMIT;

