  RENAME TO respond_approval_request_v50_internal;
ALTER FUNCTION public.respond_voucher_disbursement_approval(UUID,UUID,TEXT,UUID,TEXT,TEXT)
  RENAME TO respond_voucher_disbursement_approval_v49_internal;
ALTER FUNCTION public.respond_voucher_receipt_approval(UUID,UUID,TEXT,UUID,TEXT,TEXT)
  RENAME TO respond_voucher_receipt_approval_v49_internal;
ALTER FUNCTION public.reset_company_business_data(UUID,UUID,TEXT)
  RENAME TO reset_company_business_data_v56_internal;

CREATE OR REPLACE FUNCTION public.assert_communication_actor(p_company_id UUID,p_user_id UUID,p_admin_only BOOLEAN DEFAULT FALSE)
RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE;
  IF NOT FOUND OR (p_admin_only AND v_role<>'admin') THEN RAISE EXCEPTION 'المستخدم غير مخول'; END IF;
  RETURN v_role;
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_send_company_message(p_admin_id UUID,p_company_id UUID,p_subject TEXT,p_body TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  RETURN admin_send_company_message_v52_internal(p_admin_id,p_company_id,p_subject,p_body);
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_update_complaint(
  p_admin_id UUID,p_complaint_id UUID,p_status TEXT,p_reply TEXT,p_reply_set BOOLEAN
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_company UUID; v_found BOOLEAN;
BEGIN
  SELECT company_id,TRUE INTO v_company,v_found FROM complaints WHERE id=p_complaint_id;
  IF NOT COALESCE(v_found,FALSE) THEN RETURN jsonb_build_object('not_found',TRUE); END IF;
  PERFORM set_config('app.complaint_write_scope',COALESCE(v_company::TEXT,'public'),TRUE);
  RETURN admin_update_complaint_v52_internal(p_admin_id,p_complaint_id,p_status,p_reply,p_reply_set);
END;
$$;

CREATE OR REPLACE FUNCTION public.reset_company_business_data(p_company_id UUID,p_user_id UUID,p_code_hash TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,TRUE);
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  RETURN reset_company_business_data_v56_internal(p_company_id,p_user_id,p_code_hash);
END;
$$;

CREATE OR REPLACE FUNCTION public.send_company_message_atomic(
  p_company_id UUID,p_user_id UUID,p_subject TEXT,p_body TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row messages%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,FALSE);
  IF LENGTH(BTRIM(COALESCE(p_subject,''))) NOT BETWEEN 1 AND 200
    OR LENGTH(BTRIM(COALESCE(p_body,''))) NOT BETWEEN 1 AND 5000
  THEN RAISE EXCEPTION 'بيانات الرسالة غير صالحة'; END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO messages(company_id,sender_id,subject,body,direction,is_read)
  VALUES(p_company_id,p_user_id,BTRIM(p_subject),BTRIM(p_body),'company_to_admin',FALSE) RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'send','message',v_row.id,jsonb_build_object('direction',v_row.direction,'subject',v_row.subject));
  RETURN jsonb_build_object('id',v_row.id,'created_at',v_row.created_at);
END;
$$;

CREATE OR REPLACE FUNCTION public.mark_company_message_read_atomic(
  p_company_id UUID,p_user_id UUID,p_message_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old messages%ROWTYPE; v_new messages%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,FALSE);
  SELECT * INTO v_old FROM messages WHERE id=p_message_id AND company_id=p_company_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الرسالة غير موجودة'; END IF;
  IF v_old.direction<>'admin_to_company' THEN RAISE EXCEPTION 'لا يمكن تغيير حالة رسالة صادرة'; END IF;
  IF v_old.is_read THEN RETURN jsonb_build_object('id',p_message_id,'is_read',TRUE,'already_processed',TRUE); END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  UPDATE messages SET is_read=TRUE,read_at=COALESCE(read_at,NOW()) WHERE id=p_message_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'read','message',p_message_id,jsonb_build_object('is_read',FALSE),jsonb_build_object('is_read',TRUE));
  RETURN jsonb_build_object('id',p_message_id,'is_read',TRUE,'already_processed',FALSE);
END;
$$;

CREATE OR REPLACE FUNCTION public.archive_company_message_atomic(
  p_company_id UUID,p_user_id UUID,p_message_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old messages%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,FALSE);
  SELECT * INTO v_old FROM messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الرسالة غير موجودة'; END IF;
  IF v_old.deleted_at IS NOT NULL THEN RETURN jsonb_build_object('id',p_message_id,'archived',TRUE,'already_processed',TRUE); END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  UPDATE messages SET deleted_at=NOW() WHERE id=p_message_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'archive','message',p_message_id,to_jsonb(v_old),jsonb_build_object('deleted_at',NOW()));
  RETURN jsonb_build_object('id',p_message_id,'archived',TRUE,'already_processed',FALSE);
END;
$$;

CREATE OR REPLACE FUNCTION public.create_complaint_atomic(
  p_company_id UUID,p_user_id UUID,p_type TEXT,p_subject TEXT,p_body TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row complaints%ROWTYPE; v_scope TEXT:=COALESCE(p_company_id::TEXT,'public');
BEGIN
  IF (p_company_id IS NULL)<>(p_user_id IS NULL) THEN RAISE EXCEPTION 'هوية مقدم الشكوى غير صالحة'; END IF;
  IF p_company_id IS NOT NULL THEN PERFORM assert_communication_actor(p_company_id,p_user_id,FALSE); END IF;
  IF p_type NOT IN('complaint','suggestion')
    OR LENGTH(BTRIM(COALESCE(p_subject,''))) NOT BETWEEN 1 AND 200
    OR LENGTH(BTRIM(COALESCE(p_body,''))) NOT BETWEEN 1 AND 5000
  THEN RAISE EXCEPTION 'بيانات الشكوى غير صالحة'; END IF;
  PERFORM set_config('app.complaint_write_scope',v_scope,TRUE);
  INSERT INTO complaints(company_id,user_id,type,subject,body,status)
  VALUES(p_company_id,p_user_id,p_type,BTRIM(p_subject),BTRIM(p_body),'pending') RETURNING * INTO v_row;
  IF p_company_id IS NOT NULL THEN
    INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
    VALUES(p_company_id,p_user_id,'create','complaint',v_row.id,jsonb_build_object('type',p_type,'subject',v_row.subject));
  END IF;
  RETURN jsonb_build_object('id',v_row.id,'type',v_row.type,'subject',v_row.subject,'body',v_row.body,
    'status',v_row.status,'created_at',v_row.created_at);
END;
$$;

CREATE OR REPLACE FUNCTION public.update_company_complaint_atomic(
  p_company_id UUID,p_user_id UUID,p_complaint_id UUID,p_patch JSONB
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old complaints%ROWTYPE; v_row complaints%ROWTYPE; v_role TEXT;
BEGIN
  v_role:=assert_communication_actor(p_company_id,p_user_id,FALSE);
  IF p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' OR p_patch='{}'::JSONB
  THEN RAISE EXCEPTION 'بيانات تحديث الشكوى غير صالحة'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_patch) key WHERE key NOT IN('subject','body','status'))
    OR (p_patch?'subject' AND (jsonb_typeof(p_patch->'subject')<>'string'
      OR LENGTH(BTRIM(p_patch->>'subject')) NOT BETWEEN 1 AND 200))
    OR (p_patch?'body' AND (jsonb_typeof(p_patch->'body')<>'string'
      OR LENGTH(BTRIM(p_patch->>'body')) NOT BETWEEN 1 AND 5000))
    OR (p_patch?'status' AND (jsonb_typeof(p_patch->'status')<>'string' OR p_patch->>'status'<>'closed'))
  THEN RAISE EXCEPTION 'بيانات تحديث الشكوى غير صالحة'; END IF;
  SELECT * INTO v_old FROM complaints
  WHERE id=p_complaint_id AND company_id=p_company_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR (v_old.user_id IS DISTINCT FROM p_user_id AND v_role<>'admin')
  THEN RAISE EXCEPTION 'الشكوى غير موجودة'; END IF;
  IF (p_patch?'subject' OR p_patch?'body') AND v_old.status<>'pending'
  THEN RAISE EXCEPTION 'لا يمكن تعديل شكوى قيد المعالجة'; END IF;
  PERFORM set_config('app.complaint_write_scope',p_company_id::TEXT,TRUE);
  UPDATE complaints SET
    subject=CASE WHEN p_patch?'subject' THEN BTRIM(p_patch->>'subject') ELSE subject END,
    body=CASE WHEN p_patch?'body' THEN BTRIM(p_patch->>'body') ELSE body END,
    status=CASE WHEN p_patch?'status' THEN 'closed' ELSE status END,updated_at=NOW()
  WHERE id=p_complaint_id RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'update','complaint',p_complaint_id,to_jsonb(v_old),to_jsonb(v_row));
  RETURN to_jsonb(v_row)-'deleted_at';
END;
$$;

CREATE OR REPLACE FUNCTION public.archive_company_complaint_atomic(
  p_company_id UUID,p_user_id UUID,p_complaint_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old complaints%ROWTYPE; v_role TEXT;
BEGIN
  v_role:=assert_communication_actor(p_company_id,p_user_id,FALSE);
  SELECT * INTO v_old FROM complaints WHERE id=p_complaint_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND OR (v_old.user_id IS DISTINCT FROM p_user_id AND v_role<>'admin')
  THEN RAISE EXCEPTION 'الشكوى غير موجودة'; END IF;
  IF v_old.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('id',p_complaint_id,'archived',TRUE,'already_processed',TRUE);
  END IF;
  PERFORM set_config('app.complaint_write_scope',p_company_id::TEXT,TRUE);
  UPDATE complaints SET deleted_at=NOW(),updated_at=NOW() WHERE id=p_complaint_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'archive','complaint',p_complaint_id,to_jsonb(v_old),jsonb_build_object('deleted_at',NOW()));
  RETURN jsonb_build_object('id',p_complaint_id,'archived',TRUE,'already_processed',FALSE);
END;
$$;

CREATE OR REPLACE FUNCTION public.create_approval_request_atomic(
  p_company_id UUID,p_entity_type TEXT,p_entity_id UUID,p_description TEXT,p_requester_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_amount NUMERIC:=0; v_role TEXT; v_approver UUID; v_request approval_requests%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_requester_id,FALSE);
  IF p_entity_type NOT IN('journal_entry','purchase_invoice','payroll','cash_transaction')
    OR LENGTH(COALESCE(p_description,''))>2000 THEN RAISE EXCEPTION 'نوع طلب الاعتماد غير مدعوم'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::TEXT||':approval:'||p_entity_type||':'||p_entity_id::TEXT,0));
  IF p_entity_type='journal_entry' THEN
    PERFORM 1 FROM journal_entries WHERE id=p_entity_id AND company_id=p_company_id
      AND deleted_at IS NULL AND reversed_by IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'العنصر المطلوب اعتماده غير موجود'; END IF;
    SELECT COALESCE(SUM(debit),0) INTO v_amount FROM journal_lines WHERE journal_entry_id=p_entity_id AND company_id=p_company_id;
    v_role:='manager';
  ELSIF p_entity_type='purchase_invoice' THEN
    SELECT total INTO v_amount FROM purchase_invoices WHERE id=p_entity_id AND company_id=p_company_id AND status<>'cancelled' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'العنصر المطلوب اعتماده غير موجود'; END IF;
    v_role:='manager';
  ELSIF p_entity_type='payroll' THEN
    PERFORM 1 FROM salary_sheets WHERE id=p_entity_id AND company_id=p_company_id AND status='draft' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'كشف الرواتب غير موجود أو غير قابل للاعتماد'; END IF;
    SELECT COALESCE(SUM(net_pay),0) INTO v_amount FROM salary_items WHERE sheet_id=p_entity_id AND company_id=p_company_id;
    v_role:='admin';
  ELSE
    SELECT amount INTO v_amount FROM cash_transactions WHERE id=p_entity_id AND company_id=p_company_id AND status<>'cancelled' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'العنصر المطلوب اعتماده غير موجود'; END IF;
    v_role:=CASE WHEN v_amount>50000 THEN 'admin' ELSE 'manager' END;
  END IF;
  SELECT id INTO v_approver FROM users WHERE company_id=p_company_id AND role=v_role AND is_active=TRUE AND id<>p_requester_id
    ORDER BY created_at,id LIMIT 1;
  IF v_approver IS NULL AND v_role<>'admin' THEN
    SELECT id INTO v_approver FROM users WHERE company_id=p_company_id AND role='admin' AND is_active=TRUE AND id<>p_requester_id
      ORDER BY created_at,id LIMIT 1;
  END IF;
  IF v_approver IS NULL THEN RAISE EXCEPTION 'لا يوجد معتمد مستقل لهذا الطلب'; END IF;
  IF EXISTS(SELECT 1 FROM approval_requests WHERE company_id=p_company_id AND entity_type=p_entity_type
    AND entity_id=p_entity_id AND status IN('pending','processing')) THEN RAISE EXCEPTION 'يوجد طلب اعتماد قائم'; END IF;
  IF EXISTS(SELECT 1 FROM approval_requests WHERE company_id=p_company_id AND entity_type=p_entity_type
    AND entity_id=p_entity_id AND status='approved') THEN RAISE EXCEPTION 'سبق اعتماد هذا العنصر'; END IF;
  IF p_entity_type='journal_entry' THEN
    UPDATE journal_entries SET status='pending' WHERE id=p_entity_id AND company_id=p_company_id;
  ELSIF p_entity_type='payroll' THEN
    UPDATE salary_sheets SET status='pending' WHERE id=p_entity_id AND company_id=p_company_id;
  ELSIF p_entity_type='purchase_invoice' THEN
    UPDATE purchase_invoices SET approval_status='pending' WHERE id=p_entity_id AND company_id=p_company_id;
  ELSE
    UPDATE cash_transactions SET approval_status='pending' WHERE id=p_entity_id AND company_id=p_company_id;
  END IF;
  INSERT INTO approval_requests(company_id,entity_type,entity_id,transaction_type,transaction_id,amount,description,message,
    requester_id,approver_id,status)
  VALUES(p_company_id,p_entity_type,p_entity_id,p_entity_type,p_entity_id::TEXT,ROUND(v_amount,2),NULLIF(BTRIM(p_description),''),
    NULLIF(BTRIM(p_description),''),p_requester_id,v_approver,'pending') RETURNING * INTO v_request;
  INSERT INTO notifications(company_id,user_id,type,title,message,entity_type,entity_id)
  VALUES(p_company_id,v_approver,'approval_request','طلب اعتماد جديد',
    LEFT('طلب اعتماد '||p_entity_type||' بمبلغ '||ROUND(v_amount,2)::TEXT,1000),'approval_request',v_request.id);
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_requester_id,'create','approval_request',v_request.id,to_jsonb(v_request));
  RETURN to_jsonb(v_request);
END;
$$;

CREATE OR REPLACE FUNCTION public.respond_voucher_disbursement_approval(
  p_company_id UUID,p_approval_id UUID,p_action TEXT,p_approver_user_id UUID,p_approver_chat_id TEXT,p_comments TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_request approval_requests%ROWTYPE;
BEGIN
  IF p_approver_user_id IS NULL THEN RAISE EXCEPTION 'هوية مستخدم المعتمد الموثوقة مطلوبة'; END IF;
  SELECT * INTO v_request FROM approval_requests
  WHERE id=p_approval_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'طلب الاعتماد غير موجود'; END IF;
  RETURN respond_voucher_disbursement_approval_v49_internal(
    p_company_id,p_approval_id,p_action,p_approver_user_id,p_approver_chat_id,p_comments
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.respond_voucher_receipt_approval(
  p_company_id UUID,p_approval_id UUID,p_action TEXT,p_approver_user_id UUID,p_approver_chat_id TEXT,p_comments TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_request approval_requests%ROWTYPE;
BEGIN
  IF p_approver_user_id IS NULL THEN RAISE EXCEPTION 'هوية مستخدم المعتمد الموثوقة مطلوبة'; END IF;
  SELECT * INTO v_request FROM approval_requests
  WHERE id=p_approval_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'طلب الاعتماد غير موجود'; END IF;
  RETURN respond_voucher_receipt_approval_v49_internal(
    p_company_id,p_approval_id,p_action,p_approver_user_id,p_approver_chat_id,p_comments
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.respond_approval_request_atomic(
  p_company_id UUID,p_approval_id UUID,p_action TEXT,p_approver_user_id UUID,p_comments TEXT DEFAULT ''
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_request approval_requests%ROWTYPE; v_type TEXT; v_entity UUID; v_result JSONB; v_status TEXT;
BEGIN
  SELECT * INTO v_request FROM approval_requests
  WHERE id=p_approval_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'طلب الاعتماد غير موجود'; END IF;
  v_type:=COALESCE(v_request.entity_type,v_request.transaction_type);
  BEGIN v_entity:=COALESCE(v_request.entity_id,v_request.transaction_id::UUID);
  EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'معرف العنصر غير صالح'; END;
  v_result:=respond_approval_request_v50_internal(
    p_company_id,p_approval_id,p_action,p_approver_user_id,p_comments
  );
  v_status:=v_result->>'status';
  IF COALESCE((v_result->>'replayed')::BOOLEAN,FALSE) THEN
    RETURN v_result||jsonb_build_object('entity_approval_status',v_status);
  END IF;
  IF v_type='journal_entry' AND v_status='rejected' THEN
    PERFORM post_journal_reversal(p_company_id,v_entity,'approval_rejection',p_approval_id,
      'عكس قيد مرفوض في دورة الاعتماد',p_approver_user_id);
    UPDATE journal_entries SET status='rejected' WHERE id=v_entity AND company_id=p_company_id;
  ELSIF v_type='payroll' AND v_status='rejected' THEN
    UPDATE salary_sheets SET status='rejected' WHERE id=v_entity AND company_id=p_company_id;
  ELSIF v_type='purchase_invoice' THEN
    IF v_status='rejected' THEN
      PERFORM cancel_purchase_invoice_atomic(p_company_id,v_entity,'رفض عبر دورة الاعتماد',p_approver_user_id);
    END IF;
    UPDATE purchase_invoices SET approval_status=v_status WHERE id=v_entity AND company_id=p_company_id;
  ELSIF v_type='cash_transaction' THEN
    IF v_status='rejected' THEN
      PERFORM cancel_cash_transaction(p_company_id,v_entity,p_approver_user_id);
    END IF;
    UPDATE cash_transactions SET approval_status=v_status WHERE id=v_entity AND company_id=p_company_id;
  END IF;
  RETURN v_result||jsonb_build_object('entity_approval_status',v_status);
END;
$$;

CREATE OR REPLACE FUNCTION public.respond_approval_by_telegram_atomic(
  p_approval_id UUID,p_action TEXT,p_chat_id TEXT,p_comments TEXT DEFAULT ''
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_request approval_requests%ROWTYPE; v_actor UUID; v_type TEXT; v_result JSONB;
BEGIN
  IF p_action NOT IN('approve','reject') OR LENGTH(COALESCE(p_comments,''))>2000 OR NULLIF(p_chat_id,'') IS NULL
  THEN RAISE EXCEPTION 'قرار الاعتماد غير صالح'; END IF;
  SELECT * INTO v_request FROM approval_requests WHERE id=p_approval_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'طلب الاعتماد غير موجود'; END IF;
  SELECT configured_by INTO v_actor FROM company_telegram_configs
    WHERE company_id=v_request.company_id AND is_enabled=TRUE AND approvals_enabled=TRUE AND chat_id=p_chat_id FOR UPDATE;
  IF v_actor IS NULL OR NOT EXISTS(SELECT 1 FROM users WHERE id=v_actor AND company_id=v_request.company_id AND is_active=TRUE AND role='admin')
  THEN RAISE EXCEPTION 'إعدادات تيليجرام تحتاج إلى إعادة حفظ بواسطة مدير نشط'; END IF;
  v_type:=COALESCE(v_request.entity_type,v_request.transaction_type);
  IF v_type='voucher_disbursement' THEN
    v_result:=respond_voucher_disbursement_approval(v_request.company_id,p_approval_id,p_action,v_actor,p_chat_id,p_comments);
  ELSIF v_type='voucher_receipt' THEN
    v_result:=respond_voucher_receipt_approval(v_request.company_id,p_approval_id,p_action,v_actor,p_chat_id,p_comments);
  ELSE
    v_result:=respond_approval_request_atomic(v_request.company_id,p_approval_id,p_action,v_actor,p_comments)
      ||jsonb_build_object('approver_chat_id',p_chat_id);
    UPDATE approval_requests SET approver_chat_id=p_chat_id WHERE id=p_approval_id;
  END IF;
  RETURN v_result||jsonb_build_object('company_id',v_request.company_id,'requester_id',v_request.requester_id,'entity_type',v_type);
END;
$$;

CREATE OR REPLACE FUNCTION public.respond_legacy_approval_by_telegram_atomic(
  p_action TEXT,p_transaction_type TEXT,p_transaction_id UUID,p_chat_id TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_id UUID;
BEGIN
  SELECT ar.id INTO v_id FROM approval_requests ar JOIN company_telegram_configs c ON c.company_id=ar.company_id
  WHERE c.chat_id=p_chat_id AND c.is_enabled=TRUE AND c.approvals_enabled=TRUE
    AND COALESCE(ar.entity_type,ar.transaction_type)=p_transaction_type
    AND COALESCE(ar.entity_id::TEXT,ar.transaction_id)=p_transaction_id::TEXT
    AND ar.status IN('pending','processing')
  ORDER BY ar.created_at DESC LIMIT 1;
  IF v_id IS NULL THEN RAISE EXCEPTION 'طلب الاعتماد غير موجود'; END IF;
  RETURN respond_approval_by_telegram_atomic(v_id,p_action,p_chat_id,'');
END;
$$;

CREATE OR REPLACE FUNCTION public.save_telegram_config_atomic(
  p_company_id UUID,p_user_id UUID,p_payload JSONB
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_chat TEXT; v_threshold NUMERIC; v_row company_telegram_configs%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,TRUE);
  IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN(
    'chat_id','is_enabled','notify_invoices','notify_cash_transactions','notify_user_logins','approvals_enabled','approval_threshold'))
  THEN RAISE EXCEPTION 'إعدادات تيليجرام غير صالحة'; END IF;
  BEGIN v_threshold:=COALESCE((p_payload->>'approval_threshold')::NUMERIC,0);
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'حد الموافقة غير صالح'; END;
  v_chat:=BTRIM(COALESCE(p_payload->>'chat_id',''));
  IF (v_chat<>'' AND v_chat!~'^-?[0-9]{1,20}$') OR v_threshold<0 OR v_threshold<>ROUND(v_threshold,2)
    OR (COALESCE((p_payload->>'is_enabled')::BOOLEAN,FALSE) OR COALESCE((p_payload->>'approvals_enabled')::BOOLEAN,FALSE)) AND v_chat=''
  THEN RAISE EXCEPTION 'إعدادات تيليجرام غير صالحة'; END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO company_telegram_configs(company_id,chat_id,is_enabled,notify_invoices,notify_cash_transactions,
    notify_user_logins,approvals_enabled,approval_threshold,configured_by,updated_at)
  VALUES(p_company_id,NULLIF(v_chat,''),COALESCE((p_payload->>'is_enabled')::BOOLEAN,FALSE),
    COALESCE((p_payload->>'notify_invoices')::BOOLEAN,FALSE),COALESCE((p_payload->>'notify_cash_transactions')::BOOLEAN,FALSE),
    COALESCE((p_payload->>'notify_user_logins')::BOOLEAN,FALSE),COALESCE((p_payload->>'approvals_enabled')::BOOLEAN,FALSE),
    v_threshold,p_user_id,NOW())
  ON CONFLICT(company_id) DO UPDATE SET chat_id=EXCLUDED.chat_id,is_enabled=EXCLUDED.is_enabled,
    notify_invoices=EXCLUDED.notify_invoices,notify_cash_transactions=EXCLUDED.notify_cash_transactions,
    notify_user_logins=EXCLUDED.notify_user_logins,approvals_enabled=EXCLUDED.approvals_enabled,
    approval_threshold=EXCLUDED.approval_threshold,configured_by=EXCLUDED.configured_by,updated_at=NOW()
  RETURNING * INTO v_row;
  INSERT INTO security_audit_log(company_id,user_id,action,details)
  VALUES(p_company_id,p_user_id,'telegram_config_updated',jsonb_build_object('is_enabled',v_row.is_enabled,'approvals_enabled',v_row.approvals_enabled));
  RETURN to_jsonb(v_row)-'reset_session_data';
END;
$$;

CREATE OR REPLACE FUNCTION public.create_telegram_test_run_atomic(p_company_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_config company_telegram_configs%ROWTYPE; v_run telegram_test_runs%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,TRUE);
  SELECT * INTO v_config FROM company_telegram_configs WHERE company_id=p_company_id AND is_enabled=TRUE AND NULLIF(chat_id,'') IS NOT NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'إعدادات تيليجرام غير مفعلة'; END IF;
  IF v_config.configured_by IS NULL OR NOT EXISTS(
    SELECT 1 FROM users WHERE id=v_config.configured_by AND company_id=p_company_id AND is_active=TRUE AND role='admin'
  ) THEN RAISE EXCEPTION 'إعدادات تيليجرام تحتاج إلى إعادة حفظ بواسطة مدير نشط'; END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  UPDATE telegram_test_runs SET status='expired',updated_at=NOW()
  WHERE company_id=p_company_id AND status='pending' AND created_at<NOW()-INTERVAL '2 minutes';
  IF EXISTS(SELECT 1 FROM telegram_test_runs WHERE company_id=p_company_id AND status='pending')
  THEN RAISE EXCEPTION 'يوجد فحص تيليجرام قيد التنفيذ'; END IF;
  INSERT INTO telegram_test_runs(company_id,status,created_by) VALUES(p_company_id,'pending',p_user_id) RETURNING * INTO v_run;
  INSERT INTO security_audit_log(company_id,user_id,action,details)
  VALUES(p_company_id,p_user_id,'telegram_test_started',jsonb_build_object('test_run_id',v_run.id));
  RETURN jsonb_build_object('id',v_run.id,'chat_id',v_config.chat_id,'status',v_run.status);
END;
$$;

CREATE OR REPLACE FUNCTION public.finish_telegram_test_run_atomic(p_test_run_id UUID,p_chat_id TEXT,p_action TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_run telegram_test_runs%ROWTYPE; v_actor UUID;
BEGIN
  IF p_action NOT IN('accept','reject') THEN RAISE EXCEPTION 'إجراء الفحص غير صالح'; END IF;
  SELECT * INTO v_run FROM telegram_test_runs WHERE id=p_test_run_id FOR UPDATE;
  IF NOT FOUND OR v_run.status<>'pending' THEN RAISE EXCEPTION 'انتهى الفحص أو تمت معالجته'; END IF;
  SELECT configured_by INTO v_actor FROM company_telegram_configs
  WHERE company_id=v_run.company_id AND is_enabled=TRUE AND chat_id=p_chat_id FOR UPDATE;
  IF v_actor IS NULL OR NOT EXISTS(
    SELECT 1 FROM users WHERE id=v_actor AND company_id=v_run.company_id AND is_active=TRUE AND role='admin'
  ) THEN RAISE EXCEPTION 'حساب تيليجرام غير مخول'; END IF;
  PERFORM set_config('app.communication_write_company',v_run.company_id::TEXT,TRUE);
  UPDATE telegram_test_runs SET status=CASE WHEN p_action='accept' THEN 'accepted' ELSE 'rejected' END,updated_at=NOW()
  WHERE id=p_test_run_id RETURNING * INTO v_run;
  INSERT INTO security_audit_log(company_id,user_id,action,details)
  VALUES(v_run.company_id,v_actor,'telegram_test_finished',jsonb_build_object('test_run_id',v_run.id,'status',v_run.status));
  RETURN to_jsonb(v_run);
END;
$$;

CREATE OR REPLACE FUNCTION public.expire_telegram_test_run_atomic(p_company_id UUID,p_test_run_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_run telegram_test_runs%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,TRUE);
  SELECT * INTO v_run FROM telegram_test_runs WHERE id=p_test_run_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الفحص غير موجود'; END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  UPDATE telegram_test_runs SET status='expired',updated_at=NOW() WHERE id=p_test_run_id AND status='pending' RETURNING * INTO v_run;
  RETURN COALESCE(to_jsonb(v_run),jsonb_build_object('id',p_test_run_id,'already_processed',TRUE));
END;
$$;

CREATE OR REPLACE FUNCTION public.start_telegram_reset_session_atomic(p_company_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_config company_telegram_configs%ROWTYPE; v_step TEXT; v_live BOOLEAN:=FALSE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,TRUE);
  SELECT * INTO v_config FROM company_telegram_configs
  WHERE company_id=p_company_id AND is_enabled=TRUE AND NULLIF(chat_id,'') IS NOT NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'إعدادات تيليجرام غير مفعلة'; END IF;
  IF v_config.configured_by IS NULL OR NOT EXISTS(
    SELECT 1 FROM users WHERE id=v_config.configured_by AND company_id=p_company_id AND is_active=TRUE AND role='admin'
  ) THEN RAISE EXCEPTION 'إعدادات تيليجرام تحتاج إلى إعادة حفظ بواسطة مدير نشط'; END IF;
  IF v_config.reset_session_data IS NOT NULL THEN
    v_step:=v_config.reset_session_data->>'step';
    BEGIN
      v_live:=(v_step='pending_telegram_approval' AND (v_config.reset_session_data->>'requested_at')::TIMESTAMPTZ>NOW()-INTERVAL '10 minutes')
        OR (v_step='approved_and_code_sent' AND (v_config.reset_session_data->>'expires_at')::TIMESTAMPTZ>NOW());
    EXCEPTION WHEN OTHERS THEN v_live:=FALSE; END;
    IF v_live THEN RAISE EXCEPTION 'يوجد طلب تصفير قائم'; END IF;
  END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  UPDATE company_telegram_configs SET reset_session_data=jsonb_build_object(
    'step','pending_telegram_approval','requested_at',NOW(),'requester_id',p_user_id),updated_at=NOW()
  WHERE company_id=p_company_id;
  INSERT INTO security_audit_log(company_id,user_id,action,details)
  VALUES(p_company_id,p_user_id,'telegram_reset_requested',jsonb_build_object('requested_at',NOW()));
  RETURN jsonb_build_object('company_id',p_company_id,'chat_id',v_config.chat_id,'step','pending_telegram_approval');
END;
$$;

CREATE OR REPLACE FUNCTION public.approve_telegram_reset_session_atomic(
  p_chat_id TEXT,p_code_hash TEXT,p_expires_at TIMESTAMPTZ
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_config company_telegram_configs%ROWTYPE; v_session JSONB; v_actor UUID; v_requester UUID; v_requested_at TIMESTAMPTZ;
BEGIN
  IF NULLIF(BTRIM(p_chat_id),'') IS NULL OR p_code_hash!~'^[0-9a-f]{64}$'
    OR p_expires_at<=NOW() OR p_expires_at>NOW()+INTERVAL '10 minutes'
  THEN RAISE EXCEPTION 'بيانات الرمز غير صالحة'; END IF;
  SELECT * INTO v_config FROM company_telegram_configs
  WHERE is_enabled=TRUE AND chat_id=p_chat_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'حساب تيليجرام غير مخول'; END IF;
  v_session:=v_config.reset_session_data; v_actor:=v_config.configured_by;
  IF v_actor IS NULL OR NOT EXISTS(
    SELECT 1 FROM users WHERE id=v_actor AND company_id=v_config.company_id AND is_active=TRUE AND role='admin'
  ) THEN RAISE EXCEPTION 'إعدادات تيليجرام تحتاج إلى إعادة حفظ بواسطة مدير نشط'; END IF;
  BEGIN
    v_requester:=(v_session->>'requester_id')::UUID;
    v_requested_at:=(v_session->>'requested_at')::TIMESTAMPTZ;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'طلب التصفير منتهٍ أو غير صالح'; END;
  IF v_session IS NULL OR v_session->>'step'<>'pending_telegram_approval'
    OR v_requested_at<NOW()-INTERVAL '10 minutes'
    OR NOT EXISTS(SELECT 1 FROM users WHERE id=v_requester AND company_id=v_config.company_id AND is_active=TRUE AND role='admin')
  THEN RAISE EXCEPTION 'طلب التصفير منتهٍ أو غير صالح'; END IF;
  PERFORM set_config('app.communication_write_company',v_config.company_id::TEXT,TRUE);
  UPDATE company_telegram_configs SET reset_session_data=jsonb_build_object(
    'step','approved_and_code_sent','code_hash',p_code_hash,'attempts',0,'requester_id',v_requester,
    'expires_at',p_expires_at,'approved_by_chat_id',p_chat_id),updated_at=NOW()
  WHERE company_id=v_config.company_id;
  INSERT INTO security_audit_log(company_id,user_id,action,details)
  VALUES(v_config.company_id,v_actor,'telegram_reset_approved',jsonb_build_object('requester_id',v_requester));
  RETURN jsonb_build_object('company_id',v_config.company_id,'requester_id',v_requester,'status','approved');
END;
$$;

CREATE OR REPLACE FUNCTION public.reject_telegram_reset_session_atomic(p_chat_id TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_config company_telegram_configs%ROWTYPE; v_actor UUID;
BEGIN
  SELECT * INTO v_config FROM company_telegram_configs
  WHERE is_enabled=TRUE AND chat_id=p_chat_id FOR UPDATE;
  IF NOT FOUND OR v_config.reset_session_data IS NULL
    OR v_config.reset_session_data->>'step'<>'pending_telegram_approval'
  THEN RAISE EXCEPTION 'لا يوجد طلب صالح'; END IF;
  v_actor:=v_config.configured_by;
  IF v_actor IS NULL OR NOT EXISTS(
    SELECT 1 FROM users WHERE id=v_actor AND company_id=v_config.company_id AND is_active=TRUE AND role='admin'
  ) THEN RAISE EXCEPTION 'إعدادات تيليجرام تحتاج إلى إعادة حفظ بواسطة مدير نشط'; END IF;
  PERFORM set_config('app.communication_write_company',v_config.company_id::TEXT,TRUE);
  UPDATE company_telegram_configs SET reset_session_data=NULL,updated_at=NOW() WHERE company_id=v_config.company_id;
  INSERT INTO security_audit_log(company_id,user_id,action,details)
  VALUES(v_config.company_id,v_actor,'telegram_reset_rejected',jsonb_build_object('date',NOW()));
  RETURN jsonb_build_object('company_id',v_config.company_id,'status','rejected');
END;
$$;

CREATE OR REPLACE FUNCTION public.cancel_telegram_reset_session_atomic(
  p_company_id UUID,p_requester_id UUID,p_reason TEXT DEFAULT 'cancelled_by_requester'
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_session JSONB;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_requester_id,TRUE);
  IF LENGTH(COALESCE(p_reason,'')) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'سبب الإلغاء غير صالح'; END IF;
  SELECT reset_session_data INTO v_session FROM company_telegram_configs WHERE company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'إعدادات تيليجرام غير موجودة'; END IF;
  IF v_session IS NOT NULL AND COALESCE(v_session->>'requester_id','')<>p_requester_id::TEXT
  THEN RAISE EXCEPTION 'لا يمكنك إلغاء طلب مستخدم آخر'; END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  UPDATE company_telegram_configs SET reset_session_data=NULL,updated_at=NOW() WHERE company_id=p_company_id;
  INSERT INTO security_audit_log(company_id,user_id,action,details)
  VALUES(p_company_id,p_requester_id,'telegram_reset_cancelled',jsonb_build_object('reason',p_reason));
  RETURN jsonb_build_object('company_id',p_company_id,'cancelled',TRUE);
END;
$$;

CREATE OR REPLACE FUNCTION public.upsert_push_subscription_atomic(
  p_company_id UUID,p_user_id UUID,p_endpoint TEXT,p_p256dh TEXT,p_auth TEXT,p_user_agent TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row push_subscriptions%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,FALSE);
  IF p_endpoint NOT LIKE 'https://%' OR LENGTH(p_endpoint)>4096 OR LENGTH(COALESCE(p_p256dh,'')) NOT BETWEEN 1 AND 2048
    OR LENGTH(COALESCE(p_auth,'')) NOT BETWEEN 1 AND 1024 OR LENGTH(COALESCE(p_user_agent,''))>1000
  THEN RAISE EXCEPTION 'اشتراك الإشعارات غير صالح'; END IF;
  SELECT * INTO v_row FROM push_subscriptions WHERE endpoint=p_endpoint FOR UPDATE;
  IF FOUND AND (v_row.company_id<>p_company_id OR v_row.user_id<>p_user_id) THEN RAISE EXCEPTION 'اشتراك الإشعارات غير صالح'; END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO push_subscriptions(user_id,company_id,endpoint,p256dh_key,auth_key,user_agent,is_active)
  VALUES(p_user_id,p_company_id,p_endpoint,p_p256dh,p_auth,NULLIF(p_user_agent,''),TRUE)
  ON CONFLICT(endpoint) DO UPDATE SET p256dh_key=EXCLUDED.p256dh_key,auth_key=EXCLUDED.auth_key,
    user_agent=EXCLUDED.user_agent,is_active=TRUE,updated_at=NOW() RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'subscribe','push_subscription',v_row.id,jsonb_build_object('is_active',TRUE));
  RETURN jsonb_build_object('id',v_row.id,'is_active',v_row.is_active);
END;
$$;

CREATE OR REPLACE FUNCTION public.deactivate_push_subscription_atomic(
  p_company_id UUID,p_user_id UUID,p_endpoint TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row push_subscriptions%ROWTYPE;
BEGIN
  PERFORM assert_communication_actor(p_company_id,p_user_id,FALSE);
  SELECT * INTO v_row FROM push_subscriptions WHERE endpoint=p_endpoint AND company_id=p_company_id AND user_id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الاشتراك غير موجود'; END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  UPDATE push_subscriptions SET is_active=FALSE,updated_at=NOW() WHERE id=v_row.id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'unsubscribe','push_subscription',v_row.id,jsonb_build_object('is_active',v_row.is_active),jsonb_build_object('is_active',FALSE));
  RETURN jsonb_build_object('id',v_row.id,'unsubscribed',TRUE);
END;
$$;

CREATE OR REPLACE FUNCTION public.queue_push_notifications_atomic(
  p_company_id UUID,p_user_id UUID,p_payload JSONB
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_role TEXT; v_target UUID; v_target_role TEXT; v_user RECORD; v_sub RECORD; v_action JSONB; v_notification UUID; v_users INTEGER:=0; v_queued INTEGER:=0;
BEGIN
  v_role:=assert_communication_actor(p_company_id,p_user_id,FALSE);
  IF v_role NOT IN('admin','manager') THEN RAISE EXCEPTION 'المستخدم غير مخول'; END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN(
    'title','message','url','target_user_id','target_role','tag','actions'))
    OR LENGTH(BTRIM(COALESCE(p_payload->>'title',''))) NOT BETWEEN 1 AND 200
    OR LENGTH(BTRIM(COALESCE(p_payload->>'message',''))) NOT BETWEEN 1 AND 2000
    OR LEFT(COALESCE(p_payload->>'url','/dashboard'),1)<>'/' OR LEFT(COALESCE(p_payload->>'url','/dashboard'),2)='//'
    OR LENGTH(COALESCE(p_payload->>'url',''))>2000 OR LENGTH(COALESCE(p_payload->>'tag',''))>200
    OR (p_payload?'target_user_id' AND p_payload?'target_role')
  THEN RAISE EXCEPTION 'بيانات الإشعار غير صالحة'; END IF;
  IF p_payload?'actions' THEN
    IF jsonb_typeof(p_payload->'actions')<>'array' OR jsonb_array_length(p_payload->'actions')>5
    THEN RAISE EXCEPTION 'إجراءات الإشعار غير صالحة'; END IF;
    FOR v_action IN SELECT value FROM jsonb_array_elements(p_payload->'actions') LOOP
      IF jsonb_typeof(v_action)<>'object' THEN RAISE EXCEPTION 'إجراءات الإشعار غير صالحة'; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_object_keys(v_action) key WHERE key NOT IN('action','title','icon'))
        OR LENGTH(BTRIM(COALESCE(v_action->>'action',''))) NOT BETWEEN 1 AND 80
        OR LENGTH(BTRIM(COALESCE(v_action->>'title',''))) NOT BETWEEN 1 AND 120
        OR LENGTH(COALESCE(v_action->>'icon',''))>500
      THEN RAISE EXCEPTION 'إجراءات الإشعار غير صالحة'; END IF;
    END LOOP;
  END IF;
  BEGIN v_target:=NULLIF(p_payload->>'target_user_id','')::UUID;
  EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'المستخدم المستهدف غير صالح'; END;
  v_target_role:=NULLIF(p_payload->>'target_role','');
  IF v_target_role IS NOT NULL AND v_target_role NOT IN('admin','manager','accountant','supervisor') THEN RAISE EXCEPTION 'الدور المستهدف غير صالح'; END IF;
  IF v_target IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=v_target AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم المستهدف غير موجود'; END IF;
  PERFORM set_config('app.communication_write_company',p_company_id::TEXT,TRUE);
  FOR v_user IN SELECT id FROM users WHERE company_id=p_company_id AND is_active=TRUE
    AND (v_target IS NULL OR id=v_target) AND (v_target_role IS NULL OR role=v_target_role)
  LOOP
    v_users:=v_users+1;
    INSERT INTO notifications(company_id,user_id,type,title,message,link,entity_type)
    VALUES(p_company_id,v_user.id,'push',BTRIM(p_payload->>'title'),BTRIM(p_payload->>'message'),
      COALESCE(NULLIF(p_payload->>'url',''),'/dashboard'),'push_notification') RETURNING id INTO v_notification;
    FOR v_sub IN SELECT id FROM push_subscriptions WHERE company_id=p_company_id AND user_id=v_user.id AND is_active=TRUE FOR UPDATE
    LOOP
      INSERT INTO push_notification_log(company_id,subscription_id,user_id,title,body,url,tag,actions,status)
      VALUES(p_company_id,v_sub.id,v_user.id,BTRIM(p_payload->>'title'),BTRIM(p_payload->>'message'),
        COALESCE(NULLIF(p_payload->>'url',''),'/dashboard'),NULLIF(p_payload->>'tag',''),
        CASE WHEN p_payload?'actions' THEN (p_payload->'actions')::TEXT ELSE NULL END,'queued');
      v_queued:=v_queued+1;
    END LOOP;
  END LOOP;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,new_values)
  VALUES(p_company_id,p_user_id,'queue','push_notification',jsonb_build_object('users',v_users,'subscriptions',v_queued));
  RETURN jsonb_build_object('users',v_users,'queued',v_queued);
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_communication_writes()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_company UUID:=CASE WHEN TG_OP='DELETE' THEN OLD.company_id ELSE NEW.company_id END;
BEGIN
  IF current_setting('app.business_data_reset',TRUE)=v_company::TEXT THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF current_setting('app.communication_write_company',TRUE) IS DISTINCT FROM v_company::TEXT THEN RAISE EXCEPTION 'communication records require audited functions'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'communication tenant cannot change'; END IF;
  IF TG_TABLE_NAME='messages' THEN
    IF NEW.company_id IS NULL OR LENGTH(BTRIM(NEW.subject)) NOT BETWEEN 1 AND 200 OR LENGTH(BTRIM(NEW.body)) NOT BETWEEN 1 AND 5000
    THEN RAISE EXCEPTION 'invalid message'; END IF;
  ELSIF TG_TABLE_NAME='company_telegram_configs' THEN
    IF NEW.configured_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.configured_by AND company_id=NEW.company_id AND is_active=TRUE)
      OR NEW.approval_threshold<0 THEN RAISE EXCEPTION 'invalid telegram config'; END IF;
  ELSIF TG_TABLE_NAME='telegram_test_runs' THEN
    IF NEW.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND company_id=NEW.company_id)
    THEN RAISE EXCEPTION 'invalid telegram test'; END IF;
  ELSIF TG_TABLE_NAME='push_subscriptions' THEN
    IF NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.user_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'invalid push subscription'; END IF;
  ELSE
    IF (NEW.subscription_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM push_subscriptions WHERE id=NEW.subscription_id AND company_id=NEW.company_id AND user_id=NEW.user_id))
      OR (NEW.user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.user_id AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid push log'; END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_complaint_writes()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_company UUID:=CASE WHEN TG_OP='DELETE' THEN OLD.company_id ELSE NEW.company_id END;
  v_scope TEXT:=COALESCE(v_company::TEXT,'public');
BEGIN
  IF v_company IS NOT NULL AND current_setting('app.business_data_reset',TRUE)=v_company::TEXT
  THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF current_setting('app.complaint_write_scope',TRUE) IS DISTINCT FROM v_scope
  THEN RAISE EXCEPTION 'complaint records require audited functions'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id
  THEN RAISE EXCEPTION 'complaint tenant cannot change'; END IF;
  IF NEW.company_id IS NULL AND NEW.user_id IS NOT NULL THEN RAISE EXCEPTION 'invalid public complaint'; END IF;
  IF NEW.company_id IS NOT NULL AND (NEW.user_id IS NULL OR NOT EXISTS(
    SELECT 1 FROM users WHERE id=NEW.user_id AND company_id=NEW.company_id
  )) THEN RAISE EXCEPTION 'invalid complaint actor'; END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_guard_complaint_writes ON complaints;
CREATE TRIGGER trg_guard_complaint_writes BEFORE INSERT OR UPDATE OR DELETE ON complaints FOR EACH ROW EXECUTE FUNCTION guard_complaint_writes();
DROP TRIGGER IF EXISTS trg_guard_message_writes ON messages;
CREATE TRIGGER trg_guard_message_writes BEFORE INSERT OR UPDATE OR DELETE ON messages FOR EACH ROW EXECUTE FUNCTION guard_communication_writes();
DROP TRIGGER IF EXISTS trg_guard_telegram_config_writes ON company_telegram_configs;
CREATE TRIGGER trg_guard_telegram_config_writes BEFORE INSERT OR UPDATE OR DELETE ON company_telegram_configs FOR EACH ROW EXECUTE FUNCTION guard_communication_writes();
DROP TRIGGER IF EXISTS trg_guard_telegram_test_writes ON telegram_test_runs;
CREATE TRIGGER trg_guard_telegram_test_writes BEFORE INSERT OR UPDATE OR DELETE ON telegram_test_runs FOR EACH ROW EXECUTE FUNCTION guard_communication_writes();
DROP TRIGGER IF EXISTS trg_guard_push_subscription_writes ON push_subscriptions;
CREATE TRIGGER trg_guard_push_subscription_writes BEFORE INSERT OR UPDATE OR DELETE ON push_subscriptions FOR EACH ROW EXECUTE FUNCTION guard_communication_writes();
DROP TRIGGER IF EXISTS trg_guard_push_log_writes ON push_notification_log;
CREATE TRIGGER trg_guard_push_log_writes BEFORE INSERT OR UPDATE OR DELETE ON push_notification_log FOR EACH ROW EXECUTE FUNCTION guard_communication_writes();

REVOKE ALL ON FUNCTION public.admin_send_company_message_v52_internal(UUID,UUID,TEXT,TEXT) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.admin_update_complaint_v52_internal(UUID,UUID,TEXT,TEXT,BOOLEAN) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.respond_approval_request_v50_internal(UUID,UUID,TEXT,UUID,TEXT) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.respond_voucher_disbursement_approval_v49_internal(UUID,UUID,TEXT,UUID,TEXT,TEXT) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.respond_voucher_receipt_approval_v49_internal(UUID,UUID,TEXT,UUID,TEXT,TEXT) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.reset_company_business_data_v56_internal(UUID,UUID,TEXT) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.assert_communication_actor(UUID,UUID,BOOLEAN) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.guard_communication_writes() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.guard_complaint_writes() FROM PUBLIC,anon,authenticated;

DO $$ DECLARE sig REGPROCEDURE; BEGIN
  FOREACH sig IN ARRAY ARRAY[
    'admin_send_company_message(uuid,uuid,text,text)'::REGPROCEDURE,
    'admin_update_complaint(uuid,uuid,text,text,boolean)'::REGPROCEDURE,
    'reset_company_business_data(uuid,uuid,text)'::REGPROCEDURE,
    'send_company_message_atomic(uuid,uuid,text,text)'::REGPROCEDURE,
    'mark_company_message_read_atomic(uuid,uuid,uuid)'::REGPROCEDURE,
    'archive_company_message_atomic(uuid,uuid,uuid)'::REGPROCEDURE,
    'create_complaint_atomic(uuid,uuid,text,text,text)'::REGPROCEDURE,
    'update_company_complaint_atomic(uuid,uuid,uuid,jsonb)'::REGPROCEDURE,
    'archive_company_complaint_atomic(uuid,uuid,uuid)'::REGPROCEDURE,
    'create_approval_request_atomic(uuid,text,uuid,text,uuid)'::REGPROCEDURE,
    'respond_voucher_disbursement_approval(uuid,uuid,text,uuid,text,text)'::REGPROCEDURE,
    'respond_voucher_receipt_approval(uuid,uuid,text,uuid,text,text)'::REGPROCEDURE,
    'respond_approval_request_atomic(uuid,uuid,text,uuid,text)'::REGPROCEDURE,
    'respond_approval_by_telegram_atomic(uuid,text,text,text)'::REGPROCEDURE,
    'respond_legacy_approval_by_telegram_atomic(text,text,uuid,text)'::REGPROCEDURE,
    'save_telegram_config_atomic(uuid,uuid,jsonb)'::REGPROCEDURE,
    'create_telegram_test_run_atomic(uuid,uuid)'::REGPROCEDURE,
    'finish_telegram_test_run_atomic(uuid,text,text)'::REGPROCEDURE,
    'expire_telegram_test_run_atomic(uuid,uuid,uuid)'::REGPROCEDURE,
    'start_telegram_reset_session_atomic(uuid,uuid)'::REGPROCEDURE,
    'approve_telegram_reset_session_atomic(text,text,timestamptz)'::REGPROCEDURE,
    'reject_telegram_reset_session_atomic(text)'::REGPROCEDURE,
    'cancel_telegram_reset_session_atomic(uuid,uuid,text)'::REGPROCEDURE,
    'upsert_push_subscription_atomic(uuid,uuid,text,text,text,text)'::REGPROCEDURE,
    'deactivate_push_subscription_atomic(uuid,uuid,text)'::REGPROCEDURE,
    'queue_push_notifications_atomic(uuid,uuid,jsonb)'::REGPROCEDURE
  ] LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated',sig);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',sig);
  END LOOP;
END $$;

COMMIT;

-- ----------------------------------------------------------------------------
-- BEGIN 060-relationship-contract-tender-guards.sql
-- ----------------------------------------------------------------------------

-- Migration 060: atomic CRM, contracts, tenders, bonds, Gantt and reminder lifecycles
BEGIN;

CREATE OR REPLACE FUNCTION public.assert_relationship_actor(p_company_id UUID,p_user_id UUID)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF p_company_id IS NULL OR p_user_id IS NULL OR NOT EXISTS(
    SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE
  ) THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
END;
$$;
CREATE OR REPLACE FUNCTION public.assert_relationship_payload(p_payload JSONB,p_allowed TEXT[])
RETURNS VOID LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR EXISTS(
    SELECT 1 FROM jsonb_object_keys(p_payload) key WHERE NOT (key=ANY(p_allowed))
  ) THEN RAISE EXCEPTION 'بيانات العملية غير صالحة'; END IF;
END;
$$;

-- CRM -----------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_crm_contact_atomic(p_company_id UUID,p_payload JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row crm_contacts%ROWTYPE; v_assignee UUID; v_value NUMERIC; v_name TEXT; v_type TEXT; v_stage TEXT; v_source TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_payload,ARRAY['name','type','email','phone','company_name','source','pipeline_stage','estimated_value','description','assigned_to']);
  v_name:=BTRIM(COALESCE(p_payload->>'name','')); v_type:=COALESCE(p_payload->>'type','');
  v_stage:=COALESCE(p_payload->>'pipeline_stage','new'); v_source:=COALESCE(p_payload->>'source','other');
  BEGIN
    v_assignee:=COALESCE(NULLIF(p_payload->>'assigned_to','')::UUID,p_user_id);
    v_value:=NULLIF(p_payload->>'estimated_value','')::NUMERIC;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات العميل المحتمل غير صالحة'; END;
  IF v_name='' OR LENGTH(v_name)>200 OR v_type NOT IN('lead','opportunity','customer')
    OR v_stage NOT IN('new','contacted','qualified','proposal','negotiation','won','lost')
    OR v_source NOT IN('website','referral','cold_call','tender','social','other')
    OR (v_value IS NOT NULL AND (v_value<0 OR v_value<>ROUND(v_value,2)))
    OR LENGTH(COALESCE(p_payload->>'email',''))>254 OR LENGTH(COALESCE(p_payload->>'phone',''))>50
    OR LENGTH(COALESCE(p_payload->>'company_name',''))>200 OR LENGTH(COALESCE(p_payload->>'description',''))>4000
    OR NOT EXISTS(SELECT 1 FROM users WHERE id=v_assignee AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'بيانات العميل المحتمل غير صالحة'; END IF;
  IF v_stage='won' THEN v_type:='customer'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO crm_contacts(company_id,name,type,email,phone,company_name,source,pipeline_stage,estimated_value,description,assigned_to,created_by)
  VALUES(p_company_id,v_name,v_type,NULLIF(BTRIM(p_payload->>'email'),''),NULLIF(BTRIM(p_payload->>'phone'),''),
    NULLIF(BTRIM(p_payload->>'company_name'),''),v_source,v_stage,v_value,NULLIF(BTRIM(p_payload->>'description'),''),v_assignee,p_user_id)
  RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','crm_contact',v_row.id,to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

CREATE OR REPLACE FUNCTION public.update_crm_contact_atomic(p_company_id UUID,p_contact_id UUID,p_patch JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old crm_contacts%ROWTYPE; v_new crm_contacts%ROWTYPE; v_assignee UUID; v_value NUMERIC; v_stage TEXT; v_type TEXT; v_source TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_patch,ARRAY['name','type','email','phone','company_name','source','pipeline_stage','estimated_value','description','assigned_to']);
  IF p_patch='{}'::JSONB THEN RAISE EXCEPTION 'لا توجد بيانات للتحديث'; END IF;
  SELECT * INTO v_old FROM crm_contacts WHERE id=p_contact_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'العميل المحتمل غير موجود'; END IF;
  BEGIN
    v_assignee:=CASE WHEN p_patch?'assigned_to' THEN NULLIF(p_patch->>'assigned_to','')::UUID ELSE v_old.assigned_to END;
    v_value:=CASE WHEN p_patch?'estimated_value' THEN NULLIF(p_patch->>'estimated_value','')::NUMERIC ELSE v_old.estimated_value END;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات العميل المحتمل غير صالحة'; END;
  v_stage:=CASE WHEN p_patch?'pipeline_stage' THEN p_patch->>'pipeline_stage' ELSE v_old.pipeline_stage END;
  v_type:=CASE WHEN p_patch?'type' THEN p_patch->>'type' ELSE v_old.type END;
  v_source:=CASE WHEN p_patch?'source' THEN p_patch->>'source' ELSE v_old.source END;
  IF p_patch?'pipeline_stage' AND v_stage IS DISTINCT FROM v_old.pipeline_stage AND NOT (
    (v_old.pipeline_stage='new' AND v_stage IN('contacted','lost')) OR
    (v_old.pipeline_stage='contacted' AND v_stage IN('qualified','lost')) OR
    (v_old.pipeline_stage='qualified' AND v_stage IN('proposal','lost')) OR
    (v_old.pipeline_stage='proposal' AND v_stage IN('negotiation','won','lost')) OR
    (v_old.pipeline_stage='negotiation' AND v_stage IN('won','lost'))
  ) THEN RAISE EXCEPTION 'انتقال مرحلة العميل غير صالح'; END IF;
  IF (p_patch?'name' AND (NULLIF(BTRIM(p_patch->>'name'),'') IS NULL OR LENGTH(p_patch->>'name')>200))
    OR v_type NOT IN('lead','opportunity','customer') OR v_source NOT IN('website','referral','cold_call','tender','social','other')
    OR (v_value IS NOT NULL AND (v_value<0 OR v_value<>ROUND(v_value,2)))
    OR LENGTH(COALESCE(p_patch->>'email',''))>254 OR LENGTH(COALESCE(p_patch->>'phone',''))>50
    OR LENGTH(COALESCE(p_patch->>'company_name',''))>200 OR LENGTH(COALESCE(p_patch->>'description',''))>4000
    OR v_assignee IS NULL OR NOT EXISTS(SELECT 1 FROM users WHERE id=v_assignee AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'بيانات العميل المحتمل غير صالحة'; END IF;
  IF v_stage='won' THEN v_type:='customer'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE crm_contacts SET
    name=CASE WHEN p_patch?'name' THEN BTRIM(p_patch->>'name') ELSE name END,
    type=v_type,email=CASE WHEN p_patch?'email' THEN NULLIF(BTRIM(p_patch->>'email'),'') ELSE email END,
    phone=CASE WHEN p_patch?'phone' THEN NULLIF(BTRIM(p_patch->>'phone'),'') ELSE phone END,
    company_name=CASE WHEN p_patch?'company_name' THEN NULLIF(BTRIM(p_patch->>'company_name'),'') ELSE company_name END,
    source=v_source,pipeline_stage=v_stage,estimated_value=v_value,
    description=CASE WHEN p_patch?'description' THEN NULLIF(BTRIM(p_patch->>'description'),'') ELSE description END,
    assigned_to=v_assignee,updated_at=NOW()
  WHERE id=p_contact_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'update','crm_contact',p_contact_id,to_jsonb(v_old),to_jsonb(v_new));
  RETURN to_jsonb(v_new);
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_crm_contact_atomic(p_company_id UUID,p_contact_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old crm_contacts%ROWTYPE;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  SELECT * INTO v_old FROM crm_contacts WHERE id=p_contact_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'العميل المحتمل غير موجود'; END IF;
  IF v_old.pipeline_stage='won' OR v_old.type='customer' THEN RAISE EXCEPTION 'لا يمكن حذف سجل علاقة ناجحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  DELETE FROM crm_contacts WHERE id=p_contact_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values)
  VALUES(p_company_id,p_user_id,'delete','crm_contact',p_contact_id,to_jsonb(v_old));
  RETURN jsonb_build_object('id',p_contact_id,'deleted',TRUE);
END;
$$;

CREATE OR REPLACE FUNCTION public.create_crm_followup_atomic(p_company_id UUID,p_contact_id UUID,p_payload JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row crm_followups%ROWTYPE; v_type TEXT; v_when TIMESTAMPTZ;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_payload,ARRAY['type','scheduled_at','notes']);
  v_type:=COALESCE(p_payload->>'type','call');
  PERFORM 1 FROM crm_contacts WHERE id=p_contact_id AND company_id=p_company_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'العميل المحتمل غير موجود'; END IF;
  BEGIN v_when:=(p_payload->>'scheduled_at')::TIMESTAMPTZ;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN RAISE EXCEPTION 'تاريخ المتابعة غير صالح'; END;
  IF v_type NOT IN('call','meeting','email','visit') OR v_when IS NULL OR LENGTH(COALESCE(p_payload->>'notes',''))>2000
  THEN RAISE EXCEPTION 'بيانات المتابعة غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO crm_followups(crm_contact_id,company_id,type,scheduled_at,notes,status,created_by)
  VALUES(p_contact_id,p_company_id,v_type,v_when,NULLIF(BTRIM(p_payload->>'notes'),''),'scheduled',p_user_id) RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','crm_followup',v_row.id,to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

-- Contracts -----------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_contract_atomic(p_company_id UUID,p_payload JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row contracts%ROWTYPE; v_project UUID; v_contact UUID; v_start DATE; v_end DATE; v_value NUMERIC; v_type TEXT; v_status TEXT; v_title TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_payload,ARRAY['title','type','project_id','contact_id','start_date','end_date','value','description','status']);
  v_title:=BTRIM(COALESCE(p_payload->>'title','')); v_type:=COALESCE(p_payload->>'type','general'); v_status:=COALESCE(p_payload->>'status','active');
  BEGIN
    v_project:=NULLIF(p_payload->>'project_id','')::UUID; v_contact:=NULLIF(p_payload->>'contact_id','')::UUID;
    v_start:=(p_payload->>'start_date')::DATE; v_end:=(p_payload->>'end_date')::DATE; v_value:=COALESCE((p_payload->>'value')::NUMERIC,0);
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات العقد غير صالحة'; END;
  IF v_title='' OR LENGTH(v_title)>200 OR v_type NOT IN('general','client','subcontractor','supplier','employee','lease','insurance','bond')
    OR v_status NOT IN('draft','active') OR v_start IS NULL OR v_end IS NULL OR v_end<v_start OR v_value<0 OR v_value<>ROUND(v_value,2)
    OR LENGTH(COALESCE(p_payload->>'description',''))>4000
    OR (v_project IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects WHERE id=v_project AND company_id=p_company_id))
    OR (v_contact IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=v_contact AND company_id=p_company_id))
  THEN RAISE EXCEPTION 'بيانات العقد غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO contracts(company_id,title,type,project_id,contact_id,start_date,end_date,value,description,status,created_by)
  VALUES(p_company_id,v_title,v_type,v_project,v_contact,v_start,v_end,v_value,NULLIF(BTRIM(p_payload->>'description'),''),v_status,p_user_id)
  RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','contract',v_row.id,to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

CREATE OR REPLACE FUNCTION public.update_contract_atomic(p_company_id UUID,p_contract_id UUID,p_patch JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old contracts%ROWTYPE; v_new contracts%ROWTYPE; v_project UUID; v_contact UUID; v_start DATE; v_end DATE; v_value NUMERIC; v_type TEXT; v_status TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_patch,ARRAY['title','type','project_id','contact_id','start_date','end_date','value','description','status']);
  IF p_patch='{}'::JSONB THEN RAISE EXCEPTION 'لا توجد بيانات للتحديث'; END IF;
  SELECT * INTO v_old FROM contracts WHERE id=p_contract_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'العقد غير موجود'; END IF;
  IF v_old.status IN('completed','terminated') OR (v_old.status='expired' AND NOT (p_patch?'status' AND p_patch->>'status'='terminated'))
  THEN RAISE EXCEPTION 'لا يمكن تعديل عقد منتهي'; END IF;
  IF v_old.status<>'draft' AND EXISTS(SELECT 1 FROM jsonb_object_keys(p_patch) key WHERE key NOT IN('status','description','end_date'))
  THEN RAISE EXCEPTION 'لا يمكن تعديل شروط عقد بعد تفعيله'; END IF;
  BEGIN
    v_project:=CASE WHEN p_patch?'project_id' THEN NULLIF(p_patch->>'project_id','')::UUID ELSE v_old.project_id END;
    v_contact:=CASE WHEN p_patch?'contact_id' THEN NULLIF(p_patch->>'contact_id','')::UUID ELSE v_old.contact_id END;
    v_start:=CASE WHEN p_patch?'start_date' THEN (p_patch->>'start_date')::DATE ELSE v_old.start_date END;
    v_end:=CASE WHEN p_patch?'end_date' THEN (p_patch->>'end_date')::DATE ELSE v_old.end_date END;
    v_value:=CASE WHEN p_patch?'value' THEN (p_patch->>'value')::NUMERIC ELSE v_old.value END;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات العقد غير صالحة'; END;
  v_type:=CASE WHEN p_patch?'type' THEN p_patch->>'type' ELSE v_old.type END;
  v_status:=CASE WHEN p_patch?'status' THEN p_patch->>'status' ELSE v_old.status END;
  IF p_patch?'status' AND v_status IS DISTINCT FROM v_old.status AND NOT (
    (v_old.status='draft' AND v_status IN('active','terminated')) OR
    (v_old.status='active' AND v_status IN('completed','expired','terminated')) OR
    (v_old.status='expired' AND v_status='terminated')
  ) THEN RAISE EXCEPTION 'انتقال حالة العقد غير صالح'; END IF;
  IF (p_patch?'title' AND (NULLIF(BTRIM(p_patch->>'title'),'') IS NULL OR LENGTH(p_patch->>'title')>200))
    OR v_type NOT IN('general','client','subcontractor','supplier','employee','lease','insurance','bond')
    OR v_start IS NULL OR v_end IS NULL OR v_end<v_start OR v_value<0 OR v_value<>ROUND(v_value,2)
    OR LENGTH(COALESCE(p_patch->>'description',''))>4000
    OR (v_project IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects WHERE id=v_project AND company_id=p_company_id))
    OR (v_contact IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=v_contact AND company_id=p_company_id))
  THEN RAISE EXCEPTION 'بيانات العقد غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE contracts SET
    title=CASE WHEN p_patch?'title' THEN BTRIM(p_patch->>'title') ELSE title END,type=v_type,project_id=v_project,contact_id=v_contact,
    start_date=v_start,end_date=v_end,value=v_value,
    description=CASE WHEN p_patch?'description' THEN NULLIF(BTRIM(p_patch->>'description'),'') ELSE description END,
    status=v_status,updated_at=NOW() WHERE id=p_contract_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'update','contract',p_contract_id,to_jsonb(v_old),to_jsonb(v_new));
  RETURN to_jsonb(v_new);
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_draft_contract_atomic(p_company_id UUID,p_contract_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old contracts%ROWTYPE; v_paths JSONB;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  SELECT * INTO v_old FROM contracts WHERE id=p_contract_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'العقد غير موجود'; END IF;
  IF v_old.status<>'draft' THEN RAISE EXCEPTION 'لا يمكن حذف عقد دخل دورة العمل'; END IF;
  SELECT COALESCE(jsonb_agg(SUBSTRING(file_data FROM LENGTH('storage:contract-documents/')+1)) FILTER(
    WHERE file_data LIKE 'storage:contract-documents/'||p_company_id::TEXT||'/'||p_contract_id::TEXT||'/%'
  ),'[]'::JSONB) INTO v_paths FROM contract_documents WHERE contract_id=p_contract_id AND company_id=p_company_id;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  DELETE FROM contracts WHERE id=p_contract_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values)
  VALUES(p_company_id,p_user_id,'delete','contract',p_contract_id,to_jsonb(v_old));
  RETURN jsonb_build_object('id',p_contract_id,'deleted',TRUE,'storage_paths',v_paths);
END;
$$;

CREATE OR REPLACE FUNCTION public.create_contract_document_atomic(
  p_company_id UUID,p_contract_id UUID,p_filename TEXT,p_content_type TEXT,p_storage_reference TEXT,p_file_size INT,p_description TEXT,p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row contract_documents%ROWTYPE;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM 1 FROM companies WHERE id=p_company_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM contracts WHERE id=p_contract_id AND company_id=p_company_id)
    OR NULLIF(BTRIM(p_filename),'') IS NULL OR LENGTH(p_filename)>255
    OR p_content_type NOT IN('image/jpeg','image/png','application/pdf') OR p_file_size<=0 OR p_file_size>10485760
    OR LENGTH(COALESCE(p_description,''))>1000 OR p_storage_reference NOT LIKE 'storage:contract-documents/'||p_company_id::TEXT||'/'||p_contract_id::TEXT||'/%'
    OR p_storage_reference LIKE '%..%'
  THEN RAISE EXCEPTION 'بيانات مستند العقد غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO contract_documents(contract_id,company_id,filename,content_type,file_data,file_size,description,uploaded_by)
  VALUES(p_contract_id,p_company_id,BTRIM(p_filename),p_content_type,p_storage_reference,p_file_size,NULLIF(BTRIM(p_description),''),p_user_id)
  RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'upload','contract_document',v_row.id,to_jsonb(v_row)-'file_data');
  RETURN to_jsonb(v_row)-'file_data';
END;
$$;

-- Tenders -------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_tender_atomic(p_company_id UUID,p_payload JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row tenders%ROWTYPE; v_contact UUID; v_value NUMERIC; v_bond NUMERIC; v_duration INT; v_probability INT; v_deadline DATE; v_opening DATE; v_status TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_payload,ARRAY['title','client_name','contact_id','reference_number','description','estimated_value','bid_bond_amount','submission_deadline','opening_date','project_location','project_duration_months','status','win_probability','notes']);
  v_status:=COALESCE(p_payload->>'status','draft');
  BEGIN
    v_contact:=NULLIF(p_payload->>'contact_id','')::UUID; v_value:=NULLIF(p_payload->>'estimated_value','')::NUMERIC;
    v_bond:=NULLIF(p_payload->>'bid_bond_amount','')::NUMERIC; v_duration:=NULLIF(p_payload->>'project_duration_months','')::INT;
    v_probability:=NULLIF(p_payload->>'win_probability','')::INT; v_deadline:=NULLIF(p_payload->>'submission_deadline','')::DATE;
    v_opening:=NULLIF(p_payload->>'opening_date','')::DATE;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات المناقصة غير صالحة'; END;
  IF NULLIF(BTRIM(p_payload->>'title'),'') IS NULL OR LENGTH(p_payload->>'title')>200
    OR NULLIF(BTRIM(p_payload->>'client_name'),'') IS NULL OR LENGTH(p_payload->>'client_name')>200 OR v_status NOT IN('draft','preparing')
    OR (v_value IS NOT NULL AND (v_value<0 OR v_value<>ROUND(v_value,2))) OR (v_bond IS NOT NULL AND (v_bond<0 OR v_bond<>ROUND(v_bond,2)))
    OR (v_duration IS NOT NULL AND (v_duration<0 OR v_duration>1200)) OR (v_probability IS NOT NULL AND (v_probability<0 OR v_probability>100))
    OR (v_deadline IS NOT NULL AND v_opening IS NOT NULL AND v_opening<v_deadline)
    OR (v_contact IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=v_contact AND company_id=p_company_id))
    OR LENGTH(COALESCE(p_payload->>'reference_number',''))>120 OR LENGTH(COALESCE(p_payload->>'description',''))>4000
    OR LENGTH(COALESCE(p_payload->>'project_location',''))>500 OR LENGTH(COALESCE(p_payload->>'notes',''))>2000
  THEN RAISE EXCEPTION 'بيانات المناقصة غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO tenders(company_id,title,client_name,contact_id,reference_number,description,estimated_value,bid_bond_amount,
    submission_deadline,opening_date,project_location,project_duration_months,status,win_probability,notes,created_by)
  VALUES(p_company_id,BTRIM(p_payload->>'title'),BTRIM(p_payload->>'client_name'),v_contact,NULLIF(BTRIM(p_payload->>'reference_number'),''),
    NULLIF(BTRIM(p_payload->>'description'),''),v_value,v_bond,v_deadline,v_opening,NULLIF(BTRIM(p_payload->>'project_location'),''),v_duration,
    v_status,v_probability,NULLIF(BTRIM(p_payload->>'notes'),''),p_user_id) RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','tender',v_row.id,to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

CREATE OR REPLACE FUNCTION public.update_tender_atomic(p_company_id UUID,p_tender_id UUID,p_patch JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old tenders%ROWTYPE; v_new tenders%ROWTYPE; v_contact UUID; v_value NUMERIC; v_bond NUMERIC; v_duration INT; v_probability INT; v_deadline DATE; v_opening DATE;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_patch,ARRAY['title','client_name','contact_id','reference_number','description','estimated_value','bid_bond_amount','submission_deadline','opening_date','project_location','project_duration_months','win_probability','notes']);
  IF p_patch='{}'::JSONB THEN RAISE EXCEPTION 'لا توجد بيانات للتحديث'; END IF;
  SELECT * INTO v_old FROM tenders WHERE id=p_tender_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المناقصة غير موجودة'; END IF;
  IF v_old.status NOT IN('draft','preparing') THEN RAISE EXCEPTION 'لا يمكن تعديل مناقصة بعد تقديمها'; END IF;
  BEGIN
    v_contact:=CASE WHEN p_patch?'contact_id' THEN NULLIF(p_patch->>'contact_id','')::UUID ELSE v_old.contact_id END;
    v_value:=CASE WHEN p_patch?'estimated_value' THEN NULLIF(p_patch->>'estimated_value','')::NUMERIC ELSE v_old.estimated_value END;
    v_bond:=CASE WHEN p_patch?'bid_bond_amount' THEN NULLIF(p_patch->>'bid_bond_amount','')::NUMERIC ELSE v_old.bid_bond_amount END;
    v_duration:=CASE WHEN p_patch?'project_duration_months' THEN NULLIF(p_patch->>'project_duration_months','')::INT ELSE v_old.project_duration_months END;
    v_probability:=CASE WHEN p_patch?'win_probability' THEN NULLIF(p_patch->>'win_probability','')::INT ELSE v_old.win_probability END;
    v_deadline:=CASE WHEN p_patch?'submission_deadline' THEN NULLIF(p_patch->>'submission_deadline','')::DATE ELSE v_old.submission_deadline END;
    v_opening:=CASE WHEN p_patch?'opening_date' THEN NULLIF(p_patch->>'opening_date','')::DATE ELSE v_old.opening_date END;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات المناقصة غير صالحة'; END;
  IF (p_patch?'title' AND (NULLIF(BTRIM(p_patch->>'title'),'') IS NULL OR LENGTH(p_patch->>'title')>200))
    OR (p_patch?'client_name' AND (NULLIF(BTRIM(p_patch->>'client_name'),'') IS NULL OR LENGTH(p_patch->>'client_name')>200))
    OR (v_value IS NOT NULL AND (v_value<0 OR v_value<>ROUND(v_value,2))) OR (v_bond IS NOT NULL AND (v_bond<0 OR v_bond<>ROUND(v_bond,2)))
    OR (v_duration IS NOT NULL AND (v_duration<0 OR v_duration>1200)) OR (v_probability IS NOT NULL AND (v_probability<0 OR v_probability>100))
    OR (v_deadline IS NOT NULL AND v_opening IS NOT NULL AND v_opening<v_deadline)
    OR (v_contact IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=v_contact AND company_id=p_company_id))
    OR LENGTH(COALESCE(p_patch->>'reference_number',''))>120 OR LENGTH(COALESCE(p_patch->>'description',''))>4000
    OR LENGTH(COALESCE(p_patch->>'project_location',''))>500 OR LENGTH(COALESCE(p_patch->>'notes',''))>2000
  THEN RAISE EXCEPTION 'بيانات المناقصة غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE tenders SET
    title=CASE WHEN p_patch?'title' THEN BTRIM(p_patch->>'title') ELSE title END,
    client_name=CASE WHEN p_patch?'client_name' THEN BTRIM(p_patch->>'client_name') ELSE client_name END,
    contact_id=v_contact,reference_number=CASE WHEN p_patch?'reference_number' THEN NULLIF(BTRIM(p_patch->>'reference_number'),'') ELSE reference_number END,
    description=CASE WHEN p_patch?'description' THEN NULLIF(BTRIM(p_patch->>'description'),'') ELSE description END,
    estimated_value=v_value,bid_bond_amount=v_bond,submission_deadline=v_deadline,opening_date=v_opening,
    project_location=CASE WHEN p_patch?'project_location' THEN NULLIF(BTRIM(p_patch->>'project_location'),'') ELSE project_location END,
    project_duration_months=v_duration,win_probability=v_probability,
    notes=CASE WHEN p_patch?'notes' THEN NULLIF(BTRIM(p_patch->>'notes'),'') ELSE notes END,updated_at=NOW()
  WHERE id=p_tender_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'update','tender',p_tender_id,to_jsonb(v_old),to_jsonb(v_new));
  RETURN to_jsonb(v_new);
END;
$$;

CREATE OR REPLACE FUNCTION public.transition_tender_atomic(p_company_id UUID,p_tender_id UUID,p_status TEXT,p_notes TEXT,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old tenders%ROWTYPE; v_new tenders%ROWTYPE;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  SELECT * INTO v_old FROM tenders WHERE id=p_tender_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المناقصة غير موجودة'; END IF;
  IF v_old.status=p_status THEN RETURN to_jsonb(v_old)||jsonb_build_object('already_processed',TRUE); END IF;
  IF NOT ((v_old.status='draft' AND p_status IN('preparing','submitted','cancelled')) OR
    (v_old.status='preparing' AND p_status IN('submitted','cancelled')) OR
    (v_old.status='submitted' AND p_status IN('won','lost','cancelled')))
  THEN RAISE EXCEPTION 'انتقال حالة المناقصة غير صالح'; END IF;
  IF p_status='won' AND COALESCE(v_old.estimated_value,0)<=0 THEN RAISE EXCEPTION 'قيمة المناقصة الرابحة غير صالحة'; END IF;
  IF LENGTH(COALESCE(p_notes,''))>2000 THEN RAISE EXCEPTION 'الملاحظات طويلة جداً'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE tenders SET status=p_status,notes=COALESCE(NULLIF(BTRIM(p_notes),''),notes),updated_at=NOW() WHERE id=p_tender_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'transition','tender',p_tender_id,to_jsonb(v_old),to_jsonb(v_new));
  RETURN to_jsonb(v_new)||jsonb_build_object('already_processed',FALSE);
END;
$$;

CREATE OR REPLACE FUNCTION public.create_tender_cost_item_atomic(p_company_id UUID,p_tender_id UUID,p_payload JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_tender tenders%ROWTYPE; v_row tender_cost_items%ROWTYPE; v_amount NUMERIC; v_category TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_payload,ARRAY['category','description','amount','notes']);
  SELECT * INTO v_tender FROM tenders WHERE id=p_tender_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المناقصة غير موجودة'; END IF;
  IF v_tender.status NOT IN('draft','preparing') THEN RAISE EXCEPTION 'لا يمكن تعديل تكاليف مناقصة بعد تقديمها'; END IF;
  v_category:=COALESCE(p_payload->>'category','');
  BEGIN v_amount:=(p_payload->>'amount')::NUMERIC;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات بند التكلفة غير صالحة'; END;
  IF v_category NOT IN('materials','labor','equipment','subcontractor','overhead','other') OR v_amount<=0 OR v_amount<>ROUND(v_amount,2)
    OR LENGTH(COALESCE(p_payload->>'description',''))>1000 OR LENGTH(COALESCE(p_payload->>'notes',''))>2000
  THEN RAISE EXCEPTION 'بيانات بند التكلفة غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO tender_cost_items(tender_id,company_id,category,description,amount,notes,created_by)
  VALUES(p_tender_id,p_company_id,v_category,NULLIF(BTRIM(p_payload->>'description'),''),v_amount,NULLIF(BTRIM(p_payload->>'notes'),''),p_user_id)
  RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','tender_cost_item',v_row.id,to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_draft_tender_atomic(p_company_id UUID,p_tender_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_tender tenders%ROWTYPE;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  SELECT * INTO v_tender FROM tenders WHERE id=p_tender_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المناقصة غير موجودة'; END IF;
  IF v_tender.status<>'draft' OR v_tender.project_id IS NOT NULL THEN RAISE EXCEPTION 'لا يمكن حذف مناقصة دخلت دورة العمل'; END IF;
  IF EXISTS(SELECT 1 FROM bonds WHERE tender_id=p_tender_id AND company_id=p_company_id) THEN RAISE EXCEPTION 'لا يمكن حذف مناقصة مرتبطة بضمان'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  DELETE FROM tenders WHERE id=p_tender_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values)
  VALUES(p_company_id,p_user_id,'delete','tender',p_tender_id,to_jsonb(v_tender));
  RETURN jsonb_build_object('id',p_tender_id,'deleted',TRUE);
END;
$$;

CREATE OR REPLACE FUNCTION public.convert_won_tender_to_project_atomic(p_company_id UUID,p_tender_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_tender tenders%ROWTYPE; v_project JSONB; v_end DATE;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  SELECT * INTO v_tender FROM tenders WHERE id=p_tender_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المناقصة غير موجودة'; END IF;
  IF v_tender.project_id IS NOT NULL THEN RETURN jsonb_build_object('project',jsonb_build_object('id',v_tender.project_id),'tender_id',p_tender_id,'already_processed',TRUE); END IF;
  IF v_tender.status<>'won' THEN RAISE EXCEPTION 'يمكن تحويل العطاءات الرابحة فقط إلى مشروع'; END IF;
  IF COALESCE(v_tender.estimated_value,0)<=0 THEN RAISE EXCEPTION 'قيمة المناقصة غير صالحة لإنشاء مشروع'; END IF;
  v_end:=CASE WHEN COALESCE(v_tender.project_duration_months,0)>0 THEN CURRENT_DATE+(v_tender.project_duration_months*30) ELSE NULL END;
  v_project:=create_project_atomic(p_company_id,v_tender.title,v_tender.contact_id,v_tender.estimated_value,
    CURRENT_DATE,v_end,'active',COALESCE(v_tender.description,''),COALESCE(v_tender.project_location,''),'[]'::JSONB,FALSE,p_user_id);
  UPDATE projects SET tender_id=p_tender_id WHERE id=(v_project->>'id')::UUID AND company_id=p_company_id RETURNING to_jsonb(projects.*) INTO v_project;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE tenders SET project_id=(v_project->>'id')::UUID,updated_at=NOW() WHERE id=p_tender_id;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'convert_to_project','tender',p_tender_id,jsonb_build_object('project_id',v_project->>'id'));
  RETURN jsonb_build_object('project',v_project,'tender_id',p_tender_id,'already_processed',FALSE);
END;
$$;

-- Bonds ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_bond_atomic(p_company_id UUID,p_payload JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row bonds%ROWTYPE; v_project UUID; v_tender UUID; v_contact UUID; v_bank UUID; v_amount NUMERIC; v_issue DATE; v_expiry DATE; v_type TEXT; v_currency TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_payload,ARRAY['title','type','amount','currency','issue_date','expiry_date','issuing_bank','bank_safe_id','beneficiary_name','project_id','tender_id','contact_id','reference_number','notes']);
  v_type:=COALESCE(p_payload->>'type',''); v_currency:=COALESCE(p_payload->>'currency','SAR');
  BEGIN
    v_project:=NULLIF(p_payload->>'project_id','')::UUID; v_tender:=NULLIF(p_payload->>'tender_id','')::UUID;
    v_contact:=NULLIF(p_payload->>'contact_id','')::UUID; v_bank:=NULLIF(p_payload->>'bank_safe_id','')::UUID;
    v_amount:=(p_payload->>'amount')::NUMERIC; v_issue:=(p_payload->>'issue_date')::DATE; v_expiry:=(p_payload->>'expiry_date')::DATE;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات الضمان غير صالحة'; END;
  IF NULLIF(BTRIM(p_payload->>'title'),'') IS NULL OR LENGTH(p_payload->>'title')>200
    OR v_type NOT IN('bid_bond','performance_bond','advance_payment','retention','warranty','insurance','other')
    OR v_currency !~ '^[A-Z]{3}$' OR v_amount<=0 OR v_amount<>ROUND(v_amount,2) OR v_issue IS NULL OR v_expiry IS NULL OR v_expiry<v_issue
    OR (v_project IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects WHERE id=v_project AND company_id=p_company_id))
    OR (v_tender IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tenders WHERE id=v_tender AND company_id=p_company_id))
    OR (v_contact IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=v_contact AND company_id=p_company_id))
    OR (v_bank IS NOT NULL AND NOT EXISTS(SELECT 1 FROM banks_safes WHERE id=v_bank AND company_id=p_company_id))
    OR LENGTH(COALESCE(p_payload->>'issuing_bank',''))>200 OR LENGTH(COALESCE(p_payload->>'beneficiary_name',''))>200
    OR LENGTH(COALESCE(p_payload->>'reference_number',''))>120 OR LENGTH(COALESCE(p_payload->>'notes',''))>2000
  THEN RAISE EXCEPTION 'بيانات الضمان غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO bonds(company_id,title,type,amount,currency,issue_date,expiry_date,issuing_bank,bank_safe_id,beneficiary_name,
    project_id,tender_id,contact_id,reference_number,status,notes,created_by)
  VALUES(p_company_id,BTRIM(p_payload->>'title'),v_type,v_amount,v_currency,v_issue,v_expiry,NULLIF(BTRIM(p_payload->>'issuing_bank'),''),v_bank,
    NULLIF(BTRIM(p_payload->>'beneficiary_name'),''),v_project,v_tender,v_contact,NULLIF(BTRIM(p_payload->>'reference_number'),''),'active',
    NULLIF(BTRIM(p_payload->>'notes'),''),p_user_id) RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','bond',v_row.id,to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

CREATE OR REPLACE FUNCTION public.update_bond_atomic(p_company_id UUID,p_bond_id UUID,p_patch JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old bonds%ROWTYPE; v_new bonds%ROWTYPE; v_amount NUMERIC; v_expiry DATE;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_patch,ARRAY['title','amount','expiry_date','notes','beneficiary_name']);
  IF p_patch='{}'::JSONB THEN RAISE EXCEPTION 'لا توجد بيانات للتحديث'; END IF;
  SELECT * INTO v_old FROM bonds WHERE id=p_bond_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الضمان غير موجود'; END IF;
  IF v_old.status<>'active' THEN RAISE EXCEPTION 'لا يمكن تعديل ضمان غير نشط'; END IF;
  BEGIN
    v_amount:=CASE WHEN p_patch?'amount' THEN (p_patch->>'amount')::NUMERIC ELSE v_old.amount END;
    v_expiry:=CASE WHEN p_patch?'expiry_date' THEN (p_patch->>'expiry_date')::DATE ELSE v_old.expiry_date END;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات الضمان غير صالحة'; END;
  IF (p_patch?'title' AND (NULLIF(BTRIM(p_patch->>'title'),'') IS NULL OR LENGTH(p_patch->>'title')>200))
    OR v_amount<=0 OR v_amount<>ROUND(v_amount,2) OR v_expiry<v_old.issue_date
    OR LENGTH(COALESCE(p_patch->>'notes',''))>2000 OR LENGTH(COALESCE(p_patch->>'beneficiary_name',''))>200
  THEN RAISE EXCEPTION 'بيانات الضمان غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE bonds SET title=CASE WHEN p_patch?'title' THEN BTRIM(p_patch->>'title') ELSE title END,amount=v_amount,expiry_date=v_expiry,
    notes=CASE WHEN p_patch?'notes' THEN NULLIF(BTRIM(p_patch->>'notes'),'') ELSE notes END,
    beneficiary_name=CASE WHEN p_patch?'beneficiary_name' THEN NULLIF(BTRIM(p_patch->>'beneficiary_name'),'') ELSE beneficiary_name END,
    updated_at=NOW() WHERE id=p_bond_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'update','bond',p_bond_id,to_jsonb(v_old),to_jsonb(v_new));
  RETURN to_jsonb(v_new);
END;
$$;

CREATE OR REPLACE FUNCTION public.transition_bond_atomic(p_company_id UUID,p_bond_id UUID,p_action TEXT,p_notes TEXT,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old bonds%ROWTYPE; v_new bonds%ROWTYPE; v_status TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  IF p_action NOT IN('release','cancel') OR LENGTH(COALESCE(p_notes,''))>2000 THEN RAISE EXCEPTION 'عملية الضمان غير صالحة'; END IF;
  v_status:=CASE WHEN p_action='release' THEN 'released' ELSE 'cancelled' END;
  SELECT * INTO v_old FROM bonds WHERE id=p_bond_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الضمان غير موجود'; END IF;
  IF v_old.status=v_status THEN RETURN to_jsonb(v_old)||jsonb_build_object('already_processed',TRUE); END IF;
  IF v_old.status<>'active' THEN RAISE EXCEPTION 'لا يمكن تغيير حالة ضمان غير نشط'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE bonds SET status=v_status,released_at=CASE WHEN p_action='release' THEN NOW() ELSE released_at END,
    notes=COALESCE(NULLIF(BTRIM(p_notes),''),notes),updated_at=NOW() WHERE id=p_bond_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,p_action,'bond',p_bond_id,to_jsonb(v_old),to_jsonb(v_new));
  RETURN to_jsonb(v_new)||jsonb_build_object('already_processed',FALSE);
END;
$$;

CREATE OR REPLACE FUNCTION public.get_bond_summary(p_company_id UUID)
RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT jsonb_build_object(
    'total',COUNT(*),
    'active',COUNT(*) FILTER(WHERE status='active'),
    'expiringSoon',COUNT(*) FILTER(WHERE status='active' AND expiry_date>=CURRENT_DATE AND expiry_date<CURRENT_DATE+30),
    'expired',COUNT(*) FILTER(WHERE expiry_date<CURRENT_DATE),
    'totalValue',COALESCE(SUM(amount),0)
  ) FROM bonds WHERE company_id=p_company_id
$$;

-- Gantt tasks ----------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_project_task_atomic(p_company_id UUID,p_payload JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row project_tasks%ROWTYPE; v_project UUID; v_parent UUID; v_assignee UUID; v_start DATE; v_end DATE; v_progress NUMERIC; v_est NUMERIC; v_actual NUMERIC; v_status TEXT; v_priority TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_payload,ARRAY['project_id','name','description','start_date','end_date','progress','status','priority','parent_task_id','assigned_to','estimated_hours','actual_hours']);
  v_status:=COALESCE(p_payload->>'status','not_started'); v_priority:=COALESCE(p_payload->>'priority','medium');
  BEGIN
    v_project:=(p_payload->>'project_id')::UUID; v_parent:=NULLIF(p_payload->>'parent_task_id','')::UUID; v_assignee:=NULLIF(p_payload->>'assigned_to','')::UUID;
    v_start:=(p_payload->>'start_date')::DATE; v_end:=(p_payload->>'end_date')::DATE; v_progress:=COALESCE((p_payload->>'progress')::NUMERIC,0);
    v_est:=NULLIF(p_payload->>'estimated_hours','')::NUMERIC; v_actual:=NULLIF(p_payload->>'actual_hours','')::NUMERIC;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات المهمة غير صالحة'; END;
  IF v_status='completed' THEN v_progress:=100;
  ELSIF v_progress=100 THEN v_status:='completed';
  ELSIF v_progress>0 AND v_status NOT IN('blocked','on_hold') THEN v_status:='in_progress'; END IF;
  IF NULLIF(BTRIM(p_payload->>'name'),'') IS NULL OR LENGTH(p_payload->>'name')>200 OR v_start IS NULL OR v_end IS NULL OR v_end<v_start
    OR v_progress<0 OR v_progress>100 OR v_status NOT IN('not_started','in_progress','completed','blocked','on_hold')
    OR v_priority NOT IN('low','medium','high','critical') OR (v_est IS NOT NULL AND (v_est<0 OR v_est<>ROUND(v_est,2)))
    OR (v_actual IS NOT NULL AND (v_actual<0 OR v_actual<>ROUND(v_actual,2))) OR LENGTH(COALESCE(p_payload->>'description',''))>4000
    OR NOT EXISTS(SELECT 1 FROM projects WHERE id=v_project AND company_id=p_company_id)
    OR (v_parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM project_tasks WHERE id=v_parent AND project_id=v_project AND company_id=p_company_id))
    OR (v_assignee IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=v_assignee AND company_id=p_company_id AND is_active=TRUE))
  THEN RAISE EXCEPTION 'بيانات المهمة غير صالحة'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO project_tasks(company_id,project_id,name,description,start_date,end_date,progress,status,priority,parent_task_id,assigned_to,estimated_hours,actual_hours,created_by)
  VALUES(p_company_id,v_project,BTRIM(p_payload->>'name'),NULLIF(BTRIM(p_payload->>'description'),''),v_start,v_end,v_progress,v_status,v_priority,v_parent,v_assignee,v_est,v_actual,p_user_id)
  RETURNING * INTO v_row;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','project_task',v_row.id,to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

CREATE OR REPLACE FUNCTION public.update_project_task_atomic(p_company_id UUID,p_task_id UUID,p_patch JSONB,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old project_tasks%ROWTYPE; v_new project_tasks%ROWTYPE; v_parent UUID; v_assignee UUID; v_start DATE; v_end DATE; v_progress NUMERIC; v_est NUMERIC; v_actual NUMERIC; v_status TEXT; v_priority TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  PERFORM assert_relationship_payload(p_patch,ARRAY['name','description','start_date','end_date','progress','status','priority','parent_task_id','assigned_to','estimated_hours','actual_hours']);
  IF p_patch='{}'::JSONB THEN RAISE EXCEPTION 'لا توجد بيانات للتحديث'; END IF;
  SELECT * INTO v_old FROM project_tasks WHERE id=p_task_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المهمة غير موجودة'; END IF;
  BEGIN
    v_parent:=CASE WHEN p_patch?'parent_task_id' THEN NULLIF(p_patch->>'parent_task_id','')::UUID ELSE v_old.parent_task_id END;
    v_assignee:=CASE WHEN p_patch?'assigned_to' THEN NULLIF(p_patch->>'assigned_to','')::UUID ELSE v_old.assigned_to END;
    v_start:=CASE WHEN p_patch?'start_date' THEN (p_patch->>'start_date')::DATE ELSE v_old.start_date END;
    v_end:=CASE WHEN p_patch?'end_date' THEN (p_patch->>'end_date')::DATE ELSE v_old.end_date END;
    v_progress:=CASE WHEN p_patch?'progress' THEN (p_patch->>'progress')::NUMERIC ELSE v_old.progress END;
    v_est:=CASE WHEN p_patch?'estimated_hours' THEN NULLIF(p_patch->>'estimated_hours','')::NUMERIC ELSE v_old.estimated_hours END;
    v_actual:=CASE WHEN p_patch?'actual_hours' THEN NULLIF(p_patch->>'actual_hours','')::NUMERIC ELSE v_old.actual_hours END;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'بيانات المهمة غير صالحة'; END;
  v_status:=CASE WHEN p_patch?'status' THEN p_patch->>'status' ELSE v_old.status END;
  v_priority:=CASE WHEN p_patch?'priority' THEN p_patch->>'priority' ELSE v_old.priority END;
  IF p_patch?'status' AND v_status='completed' THEN v_progress:=100;
  ELSIF p_patch?'status' AND v_status='not_started' THEN v_progress:=0;
  ELSIF p_patch?'progress' THEN
    IF v_progress=100 THEN v_status:='completed'; ELSIF v_progress>0 THEN v_status:='in_progress'; ELSIF v_status IN('completed','in_progress') THEN v_status:='not_started'; END IF;
  END IF;
  IF (p_patch?'name' AND (NULLIF(BTRIM(p_patch->>'name'),'') IS NULL OR LENGTH(p_patch->>'name')>200))
    OR v_start IS NULL OR v_end IS NULL OR v_end<v_start OR v_progress<0 OR v_progress>100
    OR v_status NOT IN('not_started','in_progress','completed','blocked','on_hold') OR v_priority NOT IN('low','medium','high','critical')
    OR (v_est IS NOT NULL AND (v_est<0 OR v_est<>ROUND(v_est,2))) OR (v_actual IS NOT NULL AND (v_actual<0 OR v_actual<>ROUND(v_actual,2)))
    OR LENGTH(COALESCE(p_patch->>'description',''))>4000
    OR v_parent=p_task_id OR (v_parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM project_tasks WHERE id=v_parent AND project_id=v_old.project_id AND company_id=p_company_id))
    OR (v_assignee IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=v_assignee AND company_id=p_company_id AND is_active=TRUE))
  THEN RAISE EXCEPTION 'بيانات المهمة غير صالحة'; END IF;
  IF v_parent IS NOT NULL AND EXISTS(
    WITH RECURSIVE ancestors AS (
      SELECT id,parent_task_id FROM project_tasks WHERE id=v_parent AND company_id=p_company_id AND project_id=v_old.project_id
      UNION ALL SELECT p.id,p.parent_task_id FROM project_tasks p JOIN ancestors a ON p.id=a.parent_task_id
        WHERE p.company_id=p_company_id AND p.project_id=v_old.project_id
    ) SELECT 1 FROM ancestors WHERE id=p_task_id
  ) THEN RAISE EXCEPTION 'لا يمكن إنشاء دورة في تبعيات المهام'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE project_tasks SET name=CASE WHEN p_patch?'name' THEN BTRIM(p_patch->>'name') ELSE name END,
    description=CASE WHEN p_patch?'description' THEN NULLIF(BTRIM(p_patch->>'description'),'') ELSE description END,
    start_date=v_start,end_date=v_end,progress=v_progress,status=v_status,priority=v_priority,parent_task_id=v_parent,assigned_to=v_assignee,
    estimated_hours=v_est,actual_hours=v_actual,updated_at=NOW() WHERE id=p_task_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'update','project_task',p_task_id,to_jsonb(v_old),to_jsonb(v_new));
  RETURN to_jsonb(v_new);
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_unstarted_project_task_atomic(p_company_id UUID,p_task_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_task project_tasks%ROWTYPE; v_count INT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  SELECT * INTO v_task FROM project_tasks WHERE id=p_task_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المهمة غير موجودة'; END IF;
  PERFORM 1 FROM project_tasks WHERE company_id=p_company_id AND project_id=v_task.project_id FOR UPDATE;
  IF EXISTS(WITH RECURSIVE tree AS (
    SELECT id,progress FROM project_tasks WHERE id=p_task_id AND company_id=p_company_id
    UNION ALL SELECT child.id,child.progress FROM project_tasks child JOIN tree parent ON child.parent_task_id=parent.id
      WHERE child.company_id=p_company_id AND child.project_id=v_task.project_id
  ) SELECT 1 FROM tree WHERE COALESCE(progress,0)>0) THEN RAISE EXCEPTION 'لا يمكن حذف مهمة أو مهمة فرعية بدأ تنفيذها'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  WITH RECURSIVE tree AS (
    SELECT id FROM project_tasks WHERE id=p_task_id AND company_id=p_company_id
    UNION ALL SELECT child.id FROM project_tasks child JOIN tree parent ON child.parent_task_id=parent.id
      WHERE child.company_id=p_company_id AND child.project_id=v_task.project_id
  ) DELETE FROM project_tasks WHERE id IN(SELECT id FROM tree) AND company_id=p_company_id;
  GET DIAGNOSTICS v_count=ROW_COUNT;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values)
  VALUES(p_company_id,p_user_id,'delete','project_task',p_task_id,to_jsonb(v_task));
  RETURN jsonb_build_object('id',p_task_id,'deleted',TRUE,'deleted_tasks',v_count);
END;
$$;

-- Invoice reminders reserve an auditable attempt before any external send. ---
CREATE OR REPLACE FUNCTION public.begin_invoice_reminder_attempt_atomic(p_company_id UUID,p_invoice_id UUID,p_user_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_invoice invoices%ROWTYPE; v_contact contacts%ROWTYPE; v_company TEXT; v_log reminder_log%ROWTYPE; v_channel TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  SELECT * INTO v_invoice FROM invoices WHERE id=p_invoice_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الفاتورة غير موجودة'; END IF;
  IF v_invoice.status<>'unpaid' OR v_invoice.due_date>=CURRENT_DATE THEN RAISE EXCEPTION 'الفاتورة غير متأخرة وغير قابلة للتذكير'; END IF;
  SELECT * INTO v_contact FROM contacts WHERE id=v_invoice.contact_id AND company_id=p_company_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'بيانات عميل الفاتورة غير صالحة'; END IF;
  v_channel:=CASE WHEN NULLIF(BTRIM(v_contact.phone),'') IS NOT NULL THEN 'whatsapp' WHEN NULLIF(BTRIM(v_contact.email),'') IS NOT NULL THEN 'email' ELSE NULL END;
  IF v_channel IS NULL THEN RAISE EXCEPTION 'لا توجد بيانات تواصل للعميل'; END IF;
  IF EXISTS(SELECT 1 FROM reminder_log WHERE company_id=p_company_id AND invoice_id=p_invoice_id
    AND status IN('pending','sent') AND sent_at>=CURRENT_DATE)
  THEN RAISE EXCEPTION 'تم إنشاء تذكير لهذه الفاتورة اليوم'; END IF;
  SELECT name INTO v_company FROM companies WHERE id=p_company_id;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO reminder_log(company_id,invoice_id,customer_name,channel,status,sent_by,sent_at)
  VALUES(p_company_id,p_invoice_id,v_contact.name,v_channel,'pending',p_user_id,NOW()) RETURNING * INTO v_log;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'begin','invoice_reminder',v_log.id,jsonb_build_object('invoice_id',p_invoice_id,'channel',v_channel));
  RETURN jsonb_build_object('reminder_id',v_log.id,'invoice_id',v_invoice.id,'invoice_number',v_invoice.number,'amount',v_invoice.total,
    'due_date',v_invoice.due_date,'customer_name',v_contact.name,'phone',v_contact.phone,'email',v_contact.email,
    'company_name',COALESCE(v_company,'شركتنا'),'channel',v_channel);
END;
$$;

CREATE OR REPLACE FUNCTION public.finish_invoice_reminder_attempt_atomic(
  p_company_id UUID,p_reminder_id UUID,p_user_id UUID,p_sent BOOLEAN,p_message_url TEXT,p_error TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_old reminder_log%ROWTYPE; v_new reminder_log%ROWTYPE; v_status TEXT;
BEGIN
  PERFORM assert_relationship_actor(p_company_id,p_user_id);
  IF p_sent IS NULL OR LENGTH(COALESCE(p_message_url,''))>4000 OR LENGTH(COALESCE(p_error,''))>2000 THEN RAISE EXCEPTION 'نتيجة التذكير غير صالحة'; END IF;
  v_status:=CASE WHEN p_sent THEN 'sent' ELSE 'failed' END;
  SELECT * INTO v_old FROM reminder_log WHERE id=p_reminder_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'محاولة التذكير غير موجودة'; END IF;
  IF v_old.status=v_status THEN RETURN to_jsonb(v_old)||jsonb_build_object('already_processed',TRUE); END IF;
  IF v_old.status<>'pending' THEN RAISE EXCEPTION 'تم إنهاء محاولة التذكير مسبقاً'; END IF;
  PERFORM set_config('app.relationship_write_company',p_company_id::TEXT,TRUE);
  UPDATE reminder_log SET status=v_status,message_url=NULLIF(p_message_url,''),error=NULLIF(p_error,'') WHERE id=p_reminder_id RETURNING * INTO v_new;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,old_values,new_values)
  VALUES(p_company_id,p_user_id,'finish','invoice_reminder',p_reminder_id,to_jsonb(v_old),to_jsonb(v_new));
  RETURN to_jsonb(v_new)||jsonb_build_object('already_processed',FALSE);
END;
$$;

-- Refuse to install write guards over legacy cross-tenant links: silently
-- preserving a poisoned relation would still leak embedded parent data.
DO $$
BEGIN
  IF EXISTS(SELECT 1 FROM crm_contacts c JOIN users u ON u.id=c.assigned_to WHERE u.company_id<>c.company_id)
    OR EXISTS(SELECT 1 FROM crm_contacts c JOIN users u ON u.id=c.created_by WHERE u.company_id<>c.company_id)
    OR EXISTS(SELECT 1 FROM crm_followups f JOIN crm_contacts c ON c.id=f.crm_contact_id WHERE c.company_id<>f.company_id)
    OR EXISTS(SELECT 1 FROM crm_followups f JOIN users u ON u.id=f.created_by WHERE u.company_id<>f.company_id)
    OR EXISTS(SELECT 1 FROM contracts c JOIN projects p ON p.id=c.project_id WHERE p.company_id<>c.company_id)
    OR EXISTS(SELECT 1 FROM contracts c JOIN contacts p ON p.id=c.contact_id WHERE p.company_id<>c.company_id)
    OR EXISTS(SELECT 1 FROM contracts c JOIN users u ON u.id=c.created_by WHERE u.company_id<>c.company_id)
    OR EXISTS(SELECT 1 FROM contract_documents d JOIN contracts c ON c.id=d.contract_id WHERE c.company_id<>d.company_id)
    OR EXISTS(SELECT 1 FROM contract_documents d JOIN users u ON u.id=d.uploaded_by WHERE u.company_id<>d.company_id)
    OR EXISTS(SELECT 1 FROM tenders t JOIN contacts c ON c.id=t.contact_id WHERE c.company_id<>t.company_id)
    OR EXISTS(SELECT 1 FROM tenders t JOIN projects p ON p.id=t.project_id WHERE p.company_id<>t.company_id)
    OR EXISTS(SELECT 1 FROM tenders t JOIN users u ON u.id=t.created_by WHERE u.company_id<>t.company_id)
    OR EXISTS(SELECT 1 FROM tender_cost_items i JOIN tenders t ON t.id=i.tender_id WHERE t.company_id<>i.company_id)
    OR EXISTS(SELECT 1 FROM tender_cost_items i JOIN users u ON u.id=i.created_by WHERE u.company_id<>i.company_id)
    OR EXISTS(SELECT 1 FROM bonds b JOIN projects p ON p.id=b.project_id WHERE p.company_id<>b.company_id)
    OR EXISTS(SELECT 1 FROM bonds b JOIN tenders t ON t.id=b.tender_id WHERE t.company_id<>b.company_id)
    OR EXISTS(SELECT 1 FROM bonds b JOIN contacts c ON c.id=b.contact_id WHERE c.company_id<>b.company_id)
    OR EXISTS(SELECT 1 FROM bonds b JOIN banks_safes s ON s.id=b.bank_safe_id WHERE s.company_id<>b.company_id)
    OR EXISTS(SELECT 1 FROM bonds b JOIN users u ON u.id=b.created_by WHERE u.company_id<>b.company_id)
    OR EXISTS(SELECT 1 FROM project_tasks t JOIN projects p ON p.id=t.project_id WHERE p.company_id<>t.company_id)
    OR EXISTS(SELECT 1 FROM project_tasks t JOIN project_tasks p ON p.id=t.parent_task_id WHERE p.company_id<>t.company_id OR p.project_id<>t.project_id)
    OR EXISTS(SELECT 1 FROM project_tasks t JOIN users u ON u.id=t.assigned_to WHERE u.company_id<>t.company_id)
    OR EXISTS(SELECT 1 FROM project_tasks t JOIN users u ON u.id=t.created_by WHERE u.company_id<>t.company_id)
    OR EXISTS(SELECT 1 FROM reminder_log r JOIN invoices i ON i.id=r.invoice_id WHERE i.company_id<>r.company_id)
    OR EXISTS(SELECT 1 FROM reminder_log r JOIN users u ON u.id=r.sent_by WHERE u.company_id<>r.company_id)
  THEN RAISE EXCEPTION 'cross-tenant CRM/contract/tender relation detected'; END IF;
END $$;

-- Last-line service-role write guards validate tenant-linked foreign keys even
-- when a caller bypasses application checks. All normal writes must use RPCs.
CREATE OR REPLACE FUNCTION public.guard_relationship_writes()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_company UUID:=CASE WHEN TG_OP='DELETE' THEN OLD.company_id ELSE NEW.company_id END;
BEGIN
  IF current_setting('app.business_data_reset',TRUE)=v_company::TEXT THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF current_setting('app.relationship_write_company',TRUE) IS DISTINCT FROM v_company::TEXT THEN RAISE EXCEPTION 'relationship records require lifecycle functions'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'relationship tenant cannot change'; END IF;
  IF TG_TABLE_NAME='crm_contacts' THEN
    IF NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.assigned_to AND company_id=NEW.company_id AND is_active=TRUE)
      OR (NEW.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid CRM tenant link'; END IF;
  ELSIF TG_TABLE_NAME='crm_followups' THEN
    IF NOT EXISTS(SELECT 1 FROM crm_contacts WHERE id=NEW.crm_contact_id AND company_id=NEW.company_id)
      OR (NEW.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid CRM follow-up tenant link'; END IF;
  ELSIF TG_TABLE_NAME='contracts' THEN
    IF (NEW.project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND company_id=NEW.company_id))
      OR (NEW.contact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=NEW.contact_id AND company_id=NEW.company_id))
      OR (NEW.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid contract tenant link'; END IF;
  ELSIF TG_TABLE_NAME='contract_documents' THEN
    IF NOT EXISTS(SELECT 1 FROM contracts WHERE id=NEW.contract_id AND company_id=NEW.company_id)
      OR (NEW.uploaded_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.uploaded_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid contract document tenant link'; END IF;
  ELSIF TG_TABLE_NAME='tenders' THEN
    IF (NEW.contact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=NEW.contact_id AND company_id=NEW.company_id))
      OR (NEW.project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND company_id=NEW.company_id))
      OR (NEW.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid tender tenant link'; END IF;
  ELSIF TG_TABLE_NAME='tender_cost_items' THEN
    IF NOT EXISTS(SELECT 1 FROM tenders WHERE id=NEW.tender_id AND company_id=NEW.company_id)
      OR (NEW.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid tender cost tenant link'; END IF;
  ELSIF TG_TABLE_NAME='bonds' THEN
    IF (NEW.project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND company_id=NEW.company_id))
      OR (NEW.tender_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tenders WHERE id=NEW.tender_id AND company_id=NEW.company_id))
      OR (NEW.contact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=NEW.contact_id AND company_id=NEW.company_id))
      OR (NEW.bank_safe_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM banks_safes WHERE id=NEW.bank_safe_id AND company_id=NEW.company_id))
      OR (NEW.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid bond tenant link'; END IF;
  ELSIF TG_TABLE_NAME='project_tasks' THEN
    IF NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND company_id=NEW.company_id)
      OR (NEW.parent_task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM project_tasks WHERE id=NEW.parent_task_id AND company_id=NEW.company_id AND project_id=NEW.project_id))
      OR (NEW.assigned_to IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.assigned_to AND company_id=NEW.company_id AND is_active=TRUE))
      OR (NEW.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid project task tenant link'; END IF;
  ELSIF TG_TABLE_NAME='reminder_log' THEN
    IF (NEW.invoice_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM invoices WHERE id=NEW.invoice_id AND company_id=NEW.company_id))
      OR (NEW.sent_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.sent_by AND company_id=NEW.company_id))
    THEN RAISE EXCEPTION 'invalid reminder tenant link'; END IF;
  END IF;
  RETURN NEW;
END;
$$;

DO $$ DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['crm_contacts','crm_followups','contracts','contract_documents','tenders','tender_cost_items','bonds','project_tasks','reminder_log'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS trg_guard_relationship_writes ON %I',t);
    EXECUTE format('CREATE TRIGGER trg_guard_relationship_writes BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION guard_relationship_writes()',t);
  END LOOP;
END $$;

REVOKE ALL ON FUNCTION public.assert_relationship_actor(UUID,UUID) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.assert_relationship_payload(JSONB,TEXT[]) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.guard_relationship_writes() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE signature TEXT;
BEGIN
  FOREACH signature IN ARRAY ARRAY[
    'create_crm_contact_atomic(UUID,JSONB,UUID)','update_crm_contact_atomic(UUID,UUID,JSONB,UUID)','delete_crm_contact_atomic(UUID,UUID,UUID)',
    'create_crm_followup_atomic(UUID,UUID,JSONB,UUID)','create_contract_atomic(UUID,JSONB,UUID)','update_contract_atomic(UUID,UUID,JSONB,UUID)',
    'delete_draft_contract_atomic(UUID,UUID,UUID)','create_contract_document_atomic(UUID,UUID,TEXT,TEXT,TEXT,INTEGER,TEXT,UUID)',
    'create_tender_atomic(UUID,JSONB,UUID)','update_tender_atomic(UUID,UUID,JSONB,UUID)','transition_tender_atomic(UUID,UUID,TEXT,TEXT,UUID)',
    'create_tender_cost_item_atomic(UUID,UUID,JSONB,UUID)','delete_draft_tender_atomic(UUID,UUID,UUID)','convert_won_tender_to_project_atomic(UUID,UUID,UUID)',
    'create_bond_atomic(UUID,JSONB,UUID)','update_bond_atomic(UUID,UUID,JSONB,UUID)','transition_bond_atomic(UUID,UUID,TEXT,TEXT,UUID)','get_bond_summary(UUID)',
    'create_project_task_atomic(UUID,JSONB,UUID)','update_project_task_atomic(UUID,UUID,JSONB,UUID)','delete_unstarted_project_task_atomic(UUID,UUID,UUID)',
    'begin_invoice_reminder_attempt_atomic(UUID,UUID,UUID)','finish_invoice_reminder_attempt_atomic(UUID,UUID,UUID,BOOLEAN,TEXT,TEXT)'
  ] LOOP
    EXECUTE 'REVOKE ALL ON FUNCTION public.'||signature||' FROM PUBLIC,anon,authenticated';
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.'||signature||' TO service_role';
  END LOOP;
END $$;

COMMIT;

-- ----------------------------------------------------------------------------
-- BEGIN 061-posted-ledger-reporting-and-budgets.sql
-- ----------------------------------------------------------------------------

-- 061 - Posted-ledger reporting, historical account visibility, and atomic budgets.
-- A journal awaiting approval is not reportable. A source that has already been
-- reversed remains reportable together with its posted reversal so the pair nets
-- to zero even when the approval lifecycle marks the source as rejected.

CREATE OR REPLACE FUNCTION public.get_financial_summary(
  p_company_id UUID, p_from DATE DEFAULT NULL, p_to DATE DEFAULT NULL
) RETURNS JSONB LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT jsonb_build_object(
    'revenue',COALESCE(sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END),0),
    'expenses',COALESCE(sum(CASE WHEN a.type='expense' THEN jl.debit-jl.credit ELSE 0 END),0),
    'accountsReceivable',COALESCE(sum(CASE WHEN a.code='1130' OR a.code LIKE '1130-%' THEN jl.debit-jl.credit ELSE 0 END),0),
    'accountsPayable',COALESCE(sum(CASE WHEN a.code='2110' OR a.code LIKE '2110-%' THEN jl.credit-jl.debit ELSE 0 END),0),
    'cashBalance',COALESCE(sum(CASE WHEN EXISTS(
      SELECT 1 FROM banks_safes bs WHERE bs.company_id=p_company_id AND bs.account_id=a.id
    ) THEN jl.debit-jl.credit ELSE 0 END),0)
  )
  FROM journal_lines jl
  JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
  WHERE jl.company_id=p_company_id
    AND (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to);
$$;

CREATE OR REPLACE FUNCTION public.get_account_balance(
  p_company_id UUID,p_account_id UUID,p_journal_type TEXT DEFAULT NULL,p_as_of DATE DEFAULT NULL
) RETURNS NUMERIC LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT COALESCE(sum(jl.debit-jl.credit),0)
  FROM journal_lines jl
  JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
  WHERE jl.company_id=p_company_id AND jl.account_id=p_account_id
    AND (p_journal_type IS NULL OR je.type=p_journal_type) AND (p_as_of IS NULL OR je.date<=p_as_of);
$$;

CREATE OR REPLACE FUNCTION public.get_account_opening_balance(
  p_company_id UUID,p_account_id UUID,p_before DATE,
  p_cost_center_id UUID DEFAULT NULL,p_branch_id UUID DEFAULT NULL
) RETURNS NUMERIC LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT COALESCE(sum(CASE WHEN a.type IN('asset','expense') THEN jl.debit-jl.credit ELSE jl.credit-jl.debit END),0)
  FROM journal_lines jl
  JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
  WHERE jl.company_id=p_company_id AND jl.account_id=p_account_id AND je.date<p_before
    AND (p_cost_center_id IS NULL OR jl.cost_center_id=p_cost_center_id)
    AND (p_branch_id IS NULL OR jl.branch_id=p_branch_id);
$$;

CREATE OR REPLACE FUNCTION public.get_general_ledger(
  p_company_id UUID,p_account_id UUID DEFAULT NULL,p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL,
  p_cost_center_id UUID DEFAULT NULL,p_branch_id UUID DEFAULT NULL,
  p_limit INTEGER DEFAULT 100,p_offset INTEGER DEFAULT 0
) RETURNS TABLE(
  line_id UUID,entry_date DATE,entry_number INTEGER,entry_description TEXT,
  reference_type TEXT,reference_id UUID,account_id UUID,account_code TEXT,
  account_name TEXT,debit NUMERIC,credit NUMERIC,line_description TEXT,
  cost_center_id UUID,branch_id UUID,opening_balance NUMERIC,
  running_balance NUMERIC,total_debit NUMERIC,total_credit NUMERIC,total_count BIGINT
) LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  WITH opening AS (
    SELECT COALESCE(sum(CASE WHEN a.type IN('asset','expense') THEN jl.debit-jl.credit ELSE jl.credit-jl.debit END),0) balance
    FROM journal_lines jl
    JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
      AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
    WHERE jl.company_id=p_company_id AND p_account_id IS NOT NULL AND jl.account_id=p_account_id
      AND p_from IS NOT NULL AND je.date<p_from
      AND (p_cost_center_id IS NULL OR jl.cost_center_id=p_cost_center_id)
      AND (p_branch_id IS NULL OR jl.branch_id=p_branch_id)
  ), base AS (
    SELECT jl.id line_id,je.date entry_date,je.number entry_number,je.description entry_description,
      je.reference_type,je.reference_id,jl.account_id,jl.account_code,COALESCE(a.name,jl.account_name) account_name,
      jl.debit,jl.credit,jl.description line_description,jl.cost_center_id,jl.branch_id,
      CASE WHEN p_account_id IS NULL OR a.type IN('asset','expense') THEN jl.debit-jl.credit ELSE jl.credit-jl.debit END movement
    FROM journal_lines jl
    JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
      AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
    WHERE jl.company_id=p_company_id AND (p_account_id IS NULL OR jl.account_id=p_account_id)
      AND (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)
      AND (p_cost_center_id IS NULL OR jl.cost_center_id=p_cost_center_id)
      AND (p_branch_id IS NULL OR jl.branch_id=p_branch_id)
  ), calculated AS (
    SELECT b.*,(SELECT balance FROM opening)+sum(movement) OVER(ORDER BY entry_date,entry_number,line_id) running,
      sum(debit) OVER() all_debit,sum(credit) OVER() all_credit,count(*) OVER() all_count
    FROM base b
  )
  SELECT line_id,entry_date,entry_number,entry_description,reference_type,reference_id,
    account_id,account_code,account_name,debit,credit,line_description,cost_center_id,branch_id,
    (SELECT balance FROM opening),running,all_debit,all_credit,all_count
  FROM calculated ORDER BY entry_date,entry_number,line_id
  LIMIT LEAST(GREATEST(p_limit,1),500) OFFSET GREATEST(p_offset,0);
$$;

CREATE OR REPLACE FUNCTION public.get_trial_balance_rows(p_company_id UUID,p_as_of DATE)
RETURNS TABLE(account_id UUID,account_code TEXT,account_name TEXT,account_type TEXT,debit NUMERIC,credit NUMERIC)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT a.id,a.code,a.name,a.type,
    COALESCE(sum(CASE WHEN je.id IS NOT NULL THEN jl.debit ELSE 0 END),0),
    COALESCE(sum(CASE WHEN je.id IS NOT NULL THEN jl.credit ELSE 0 END),0)
  FROM accounts a
  LEFT JOIN journal_lines jl ON jl.account_id=a.id AND jl.company_id=p_company_id
  LEFT JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    AND (p_as_of IS NULL OR je.date<=p_as_of)
  WHERE a.company_id=p_company_id
  GROUP BY a.id,a.code,a.name,a.type ORDER BY a.code;
$$;

CREATE OR REPLACE FUNCTION public.get_financial_statement_rows(
  p_company_id UUID,p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL
) RETURNS TABLE(
  account_id UUID,account_code TEXT,account_name TEXT,account_type TEXT,
  opening_debit NUMERIC,opening_credit NUMERIC,period_debit NUMERIC,period_credit NUMERIC,
  cumulative_debit NUMERIC,cumulative_credit NUMERIC
) LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT a.id,a.code,a.name,a.type,
    COALESCE(sum(jl.debit) FILTER(WHERE je.id IS NOT NULL AND p_from IS NOT NULL AND je.date<p_from),0),
    COALESCE(sum(jl.credit) FILTER(WHERE je.id IS NOT NULL AND p_from IS NOT NULL AND je.date<p_from),0),
    COALESCE(sum(jl.debit) FILTER(WHERE je.id IS NOT NULL AND (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)),0),
    COALESCE(sum(jl.credit) FILTER(WHERE je.id IS NOT NULL AND (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)),0),
    COALESCE(sum(jl.debit) FILTER(WHERE je.id IS NOT NULL AND (p_to IS NULL OR je.date<=p_to)),0),
    COALESCE(sum(jl.credit) FILTER(WHERE je.id IS NOT NULL AND (p_to IS NULL OR je.date<=p_to)),0)
  FROM accounts a
  LEFT JOIN journal_lines jl ON jl.account_id=a.id AND jl.company_id=p_company_id
  LEFT JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    AND (p_to IS NULL OR je.date<=p_to)
  WHERE a.company_id=p_company_id
  GROUP BY a.id,a.code,a.name,a.type ORDER BY a.code;
$$;

CREATE OR REPLACE FUNCTION public.get_monthly_profit_loss(p_company_id UUID,p_year INTEGER)
RETURNS TABLE(month_number INTEGER,revenue NUMERIC,expenses NUMERIC)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT m.month_number,
    COALESCE(sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END),0),
    COALESCE(sum(CASE WHEN a.type='expense' THEN jl.debit-jl.credit ELSE 0 END),0)
  FROM generate_series(1,12) m(month_number)
  LEFT JOIN journal_entries je ON je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    AND EXTRACT(YEAR FROM je.date)=p_year AND EXTRACT(MONTH FROM je.date)=m.month_number
  LEFT JOIN journal_lines jl ON jl.journal_entry_id=je.id AND jl.company_id=p_company_id
  LEFT JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
  GROUP BY m.month_number ORDER BY m.month_number;
$$;

CREATE OR REPLACE FUNCTION public.get_top_clients_by_revenue(
  p_company_id UUID,p_from DATE,p_to DATE,p_limit INTEGER DEFAULT 5
) RETURNS TABLE(contact_id UUID,name TEXT,revenue NUMERIC,entry_count BIGINT)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT c.id,c.name,sum(jl.credit-jl.debit),count(DISTINCT je.id)
  FROM journal_lines jl
  JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id AND a.type='revenue'
  JOIN contacts c ON c.id=jl.contact_id AND c.company_id=p_company_id
  WHERE jl.company_id=p_company_id AND je.date BETWEEN p_from AND p_to
  GROUP BY c.id,c.name HAVING sum(jl.credit-jl.debit)<>0
  ORDER BY 3 DESC LIMIT LEAST(GREATEST(p_limit,1),100);
$$;

CREATE OR REPLACE FUNCTION public.get_vat_ledger_lines(
  p_company_id UUID,p_from DATE,p_to DATE,p_limit INTEGER DEFAULT 500,p_offset INTEGER DEFAULT 0
) RETURNS TABLE(entry_date DATE,entry_number INTEGER,description TEXT,vat_type TEXT,amount NUMERIC,total_count BIGINT)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT je.date,je.number,COALESCE(jl.description,je.description),
    CASE a.code WHEN '2120' THEN 'sales' ELSE 'purchases' END,
    CASE a.code WHEN '2120' THEN jl.credit-jl.debit ELSE jl.debit-jl.credit END,count(*) OVER()
  FROM journal_lines jl
  JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id AND a.code IN('2120','1180')
  WHERE jl.company_id=p_company_id AND je.date BETWEEN p_from AND p_to
  ORDER BY je.date,je.number,jl.id
  LIMIT LEAST(GREATEST(p_limit,1),500) OFFSET GREATEST(p_offset,0);
$$;

CREATE OR REPLACE FUNCTION public.get_vat_return_summary(p_company_id UUID,p_from DATE,p_to DATE)
RETURNS JSONB LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  WITH vat AS (
    SELECT COALESCE(sum(CASE WHEN a.code='2120' THEN jl.credit-jl.debit ELSE 0 END),0) output_vat,
      COALESCE(sum(CASE WHEN a.code='1180' THEN jl.debit-jl.credit ELSE 0 END),0) input_vat
    FROM journal_lines jl
    JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
      AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
    WHERE jl.company_id=p_company_id AND je.date BETWEEN p_from AND p_to
  ), sales AS (
    SELECT COALESCE(sum(i.subtotal),0) total_sales,
      COALESCE(sum(i.subtotal) FILTER(WHERE COALESCE(i.tax_rate,0)=0),0) zero_sales,count(*) invoice_count
    FROM invoices i JOIN journal_entries je ON je.id=i.journal_entry_id AND je.company_id=p_company_id
      AND je.status='posted' AND je.deleted_at IS NULL
    WHERE i.company_id=p_company_id AND i.date BETWEEN p_from AND p_to
      AND i.status<>'cancelled' AND i.deleted_at IS NULL
  ), credits AS (
    SELECT COALESCE(sum(cn.subtotal),0) credit_sales
    FROM credit_notes cn JOIN journal_entries je ON je.id=cn.journal_entry_id AND je.company_id=p_company_id
      AND je.status='posted' AND je.deleted_at IS NULL
    WHERE cn.company_id=p_company_id AND cn.date BETWEEN p_from AND p_to
      AND cn.status='approved' AND cn.deleted_at IS NULL
  ), purchases AS (
    SELECT COALESCE(sum(pi.subtotal),0) total_purchases,count(*) purchase_count
    FROM purchase_invoices pi JOIN journal_entries je ON je.id=pi.journal_entry_id AND je.company_id=p_company_id
      AND je.status='posted' AND je.deleted_at IS NULL
    WHERE pi.company_id=p_company_id AND pi.date BETWEEN p_from AND p_to AND pi.status<>'cancelled'
  )
  SELECT jsonb_build_object(
    'outputVat',vat.output_vat,'inputVat',vat.input_vat,
    'totalSales',GREATEST(sales.total_sales-credits.credit_sales,0),'zeroRatedSales',sales.zero_sales,
    'totalPurchases',purchases.total_purchases,'invoiceCount',sales.invoice_count,'purchaseCount',purchases.purchase_count
  ) FROM vat,sales,credits,purchases;
$$;

CREATE OR REPLACE FUNCTION public.get_equity_changes_summary(
  p_company_id UUID,p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL
) RETURNS JSONB LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT jsonb_build_object(
    'openingCapital',COALESCE(sum(CASE WHEN a.code='3100' THEN jl.credit-jl.debit ELSE 0 END) FILTER(WHERE p_from IS NOT NULL AND je.date<p_from),0),
    'openingRetained',COALESCE(sum(CASE WHEN a.code='3200' THEN jl.credit-jl.debit ELSE 0 END) FILTER(WHERE p_from IS NOT NULL AND je.date<p_from),0),
    'openingOtherEquity',COALESCE(sum(CASE WHEN a.type='equity' AND a.code NOT IN('3100','3200') THEN jl.credit-jl.debit ELSE 0 END) FILTER(WHERE p_from IS NOT NULL AND je.date<p_from),0),
    'openingPriorNetIncome',COALESCE(sum(CASE WHEN a.type IN('revenue','expense') THEN jl.credit-jl.debit ELSE 0 END) FILTER(WHERE p_from IS NOT NULL AND je.date<p_from),0),
    'periodCapitalChange',COALESCE(sum(CASE WHEN a.code='3100' THEN jl.credit-jl.debit ELSE 0 END) FILTER(WHERE (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)),0),
    'periodRetainedChange',COALESCE(sum(CASE WHEN a.code='3200' THEN jl.credit-jl.debit ELSE 0 END) FILTER(WHERE (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)),0),
    'periodRevenue',COALESCE(sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END) FILTER(WHERE (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)),0),
    'periodExpenses',COALESCE(sum(CASE WHEN a.type='expense' THEN jl.debit-jl.credit ELSE 0 END) FILTER(WHERE (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)),0)
  )
  FROM journal_lines jl
  JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
  WHERE jl.company_id=p_company_id AND (p_to IS NULL OR je.date<=p_to);
$$;

CREATE OR REPLACE FUNCTION public.get_cost_center_profitability(
  p_company_id UUID,p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL
) RETURNS TABLE(cost_center_id UUID,code TEXT,name TEXT,revenue NUMERIC,expenses NUMERIC)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT cc.id,cc.code,cc.name,
    COALESCE(sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END),0),
    COALESCE(sum(CASE WHEN a.type='expense' THEN jl.debit-jl.credit ELSE 0 END),0)
  FROM cost_centers cc
  LEFT JOIN journal_lines jl ON jl.cost_center_id=cc.id AND jl.company_id=p_company_id
  LEFT JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    AND (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)
  LEFT JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id AND je.id IS NOT NULL
  WHERE cc.company_id=p_company_id
  GROUP BY cc.id,cc.code,cc.name ORDER BY cc.code;
$$;

CREATE OR REPLACE FUNCTION public.get_contact_balances(
  p_company_id UUID,p_type TEXT DEFAULT 'all',p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL
) RETURNS TABLE(contact_id UUID,name TEXT,contact_type TEXT,phone TEXT,tax_number TEXT,
  opening NUMERIC,period_debit NUMERIC,period_credit NUMERIC,closing NUMERIC)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT c.id,c.name,c.type,c.phone,c.tax_number,
    COALESCE(sum(jl.debit-jl.credit) FILTER(WHERE p_from IS NOT NULL AND je.date<p_from AND a.id IS NOT NULL),0),
    COALESCE(sum(jl.debit) FILTER(WHERE (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to) AND a.id IS NOT NULL),0),
    COALESCE(sum(jl.credit) FILTER(WHERE (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to) AND a.id IS NOT NULL),0),
    COALESCE(sum(jl.debit-jl.credit) FILTER(WHERE (p_to IS NULL OR je.date<=p_to) AND a.id IS NOT NULL),0)
  FROM contacts c
  LEFT JOIN journal_lines jl ON jl.contact_id=c.id AND jl.company_id=p_company_id
  LEFT JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  LEFT JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id AND je.id IS NOT NULL
    AND ((c.type='client' AND a.code IN('1130','2180')) OR (c.type='supplier' AND a.code='2110')
      OR (c.type='subcontractor' AND a.code IN('2110','2150')) OR (c.type='both' AND a.code IN('1130','2110','2180')))
  WHERE c.company_id=p_company_id AND (p_type='all' OR (p_type='client' AND c.type IN('client','both'))
    OR (p_type='supplier' AND c.type IN('supplier','subcontractor','both')))
  GROUP BY c.id,c.name,c.type,c.phone,c.tax_number
  HAVING COALESCE(sum(abs(jl.debit)+abs(jl.credit)) FILTER(WHERE (p_to IS NULL OR je.date<=p_to) AND a.id IS NOT NULL),0)>0
  ORDER BY c.name;
$$;

CREATE OR REPLACE FUNCTION public.get_account_period_totals(
  p_company_id UUID,p_account_type TEXT DEFAULT NULL,p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL
) RETURNS TABLE(account_id UUID,code TEXT,name TEXT,account_type TEXT,debit NUMERIC,credit NUMERIC)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT a.id,a.code,a.name,a.type,
    COALESCE(sum(CASE WHEN je.id IS NOT NULL THEN jl.debit ELSE 0 END),0),
    COALESCE(sum(CASE WHEN je.id IS NOT NULL THEN jl.credit ELSE 0 END),0)
  FROM accounts a
  LEFT JOIN journal_lines jl ON jl.account_id=a.id AND jl.company_id=p_company_id
  LEFT JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    AND (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)
  WHERE a.company_id=p_company_id AND (p_account_type IS NULL OR a.type=p_account_type)
  GROUP BY a.id,a.code,a.name,a.type ORDER BY a.code;
$$;

CREATE OR REPLACE FUNCTION public.get_report_projects(
  p_company_id UUID,p_active_only BOOLEAN DEFAULT FALSE
) RETURNS TABLE(
  project_id UUID,name TEXT,contract_value NUMERIC,client_id UUID,client_name TEXT,status TEXT,
  start_date DATE,end_date DATE
) LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT p.id,p.name,p.contract_value,p.client_id,c.name,p.status,p.start_date,p.end_date
  FROM projects p LEFT JOIN contacts c ON c.id=p.client_id AND c.company_id=p_company_id
  WHERE p.company_id=p_company_id AND (NOT p_active_only OR p.status='active')
  ORDER BY p.name,p.id;
$$;

CREATE OR REPLACE FUNCTION public.get_project_billing_totals(
  p_company_id UUID,p_project_ids UUID[] DEFAULT NULL,p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL
) RETURNS TABLE(project_id UUID,billed NUMERIC,credits NUMERIC,net_billed NUMERIC)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  WITH billed AS (
    SELECT i.project_id,sum(i.subtotal) amount
    FROM invoices i
    JOIN journal_entries je ON je.id=i.journal_entry_id AND je.company_id=p_company_id
      AND je.status='posted' AND je.deleted_at IS NULL
    JOIN projects p ON p.id=i.project_id AND p.company_id=p_company_id
    WHERE i.company_id=p_company_id AND i.project_id IS NOT NULL AND i.status<>'cancelled' AND i.deleted_at IS NULL
      AND (p_project_ids IS NULL OR i.project_id=ANY(p_project_ids))
      AND (p_from IS NULL OR i.date>=p_from) AND (p_to IS NULL OR i.date<=p_to)
    GROUP BY i.project_id
  ), credits AS (
    SELECT cn.project_id,sum(cn.subtotal) amount
    FROM credit_notes cn
    JOIN journal_entries je ON je.id=cn.journal_entry_id AND je.company_id=p_company_id
      AND je.status='posted' AND je.deleted_at IS NULL
    JOIN projects p ON p.id=cn.project_id AND p.company_id=p_company_id
    WHERE cn.company_id=p_company_id AND cn.project_id IS NOT NULL AND cn.status='approved' AND cn.deleted_at IS NULL
      AND (p_project_ids IS NULL OR cn.project_id=ANY(p_project_ids))
      AND (p_from IS NULL OR cn.date>=p_from) AND (p_to IS NULL OR cn.date<=p_to)
    GROUP BY cn.project_id
  )
  SELECT COALESCE(b.project_id,c.project_id),COALESCE(b.amount,0),COALESCE(c.amount,0),COALESCE(b.amount,0)-COALESCE(c.amount,0)
  FROM billed b FULL JOIN credits c ON c.project_id=b.project_id;
$$;

CREATE OR REPLACE FUNCTION public.get_project_account_totals(
  p_company_id UUID,p_project_ids UUID[] DEFAULT NULL,p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL
) RETURNS TABLE(project_id UUID,account_id UUID,code TEXT,name TEXT,account_type TEXT,debit NUMERIC,credit NUMERIC)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT jl.project_id,a.id,a.code,a.name,a.type,sum(jl.debit),sum(jl.credit)
  FROM journal_lines jl
  JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
  JOIN projects p ON p.id=jl.project_id AND p.company_id=p_company_id
  WHERE jl.company_id=p_company_id AND jl.project_id IS NOT NULL
    AND (p_project_ids IS NULL OR jl.project_id=ANY(p_project_ids))
    AND (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)
  GROUP BY jl.project_id,a.id,a.code,a.name,a.type ORDER BY jl.project_id,a.code;
$$;

CREATE OR REPLACE FUNCTION public.get_project_profitability(p_company_id UUID,p_limit INTEGER DEFAULT 10)
RETURNS TABLE(project_id UUID,name TEXT,revenue NUMERIC,expenses NUMERIC,margin NUMERIC)
LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT p.id,p.name,
    COALESCE(sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END),0),
    COALESCE(sum(CASE WHEN a.type='expense' THEN jl.debit-jl.credit ELSE 0 END),0),
    CASE WHEN COALESCE(sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END),0)=0 THEN 0
      ELSE (sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END)
        -sum(CASE WHEN a.type='expense' THEN jl.debit-jl.credit ELSE 0 END))*100
        /NULLIF(sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END),0) END
  FROM projects p
  LEFT JOIN journal_lines jl ON jl.project_id=p.id AND jl.company_id=p_company_id
  LEFT JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
    AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
  LEFT JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id AND je.id IS NOT NULL
  WHERE p.company_id=p_company_id AND p.status IN('active','completed')
  GROUP BY p.id,p.name ORDER BY 5 DESC NULLS LAST
  LIMIT LEAST(GREATEST(p_limit,1),100);
$$;

CREATE OR REPLACE FUNCTION public.get_assistant_company_snapshot(p_company_id UUID)
RETURNS JSONB LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  WITH ledger AS (
    SELECT COALESCE(sum(CASE WHEN a.type='revenue' THEN jl.credit-jl.debit ELSE 0 END),0) revenue,
      COALESCE(sum(CASE WHEN a.type='expense' THEN jl.debit-jl.credit ELSE 0 END),0) expenses
    FROM journal_lines jl
    JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
      AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
    WHERE jl.company_id=p_company_id
  ), invoices_due AS (
    SELECT count(*) unpaid_count,
      count(*) FILTER(WHERE i.due_date<CURRENT_DATE) overdue_count,
      COALESCE(sum(GREATEST(i.total-COALESCE(i.paid_amount,0),0)),0) outstanding,
      COALESCE(sum(GREATEST(i.total-COALESCE(i.paid_amount,0),0)) FILTER(WHERE i.due_date<CURRENT_DATE),0) overdue
    FROM invoices i
    JOIN journal_entries je ON je.id=i.journal_entry_id AND je.company_id=p_company_id
      AND je.status='posted' AND je.deleted_at IS NULL
    WHERE i.company_id=p_company_id AND i.status IN('unpaid','partial') AND i.deleted_at IS NULL
  ), counters AS (
    SELECT
      (SELECT count(*) FROM projects p WHERE p.company_id=p_company_id) total_projects,
      (SELECT count(*) FROM projects p WHERE p.company_id=p_company_id AND p.status='active') active_projects,
      (SELECT count(*) FROM projects p WHERE p.company_id=p_company_id AND p.status='completed') completed_projects,
      (SELECT count(*) FROM contacts c WHERE c.company_id=p_company_id AND c.type IN('client','both')
        AND COALESCE(c.is_active,TRUE) AND c.deleted_at IS NULL) clients,
      (SELECT count(*) FROM contacts c WHERE c.company_id=p_company_id AND c.type IN('supplier','subcontractor','both')
        AND COALESCE(c.is_active,TRUE) AND c.deleted_at IS NULL) suppliers,
      (SELECT count(*) FROM journal_entries je WHERE je.company_id=p_company_id AND je.deleted_at IS NULL
        AND (je.status='posted' OR je.reversed_by IS NOT NULL)) journal_entries,
      (SELECT count(*) FROM journal_entries je WHERE je.company_id=p_company_id AND je.deleted_at IS NULL
        AND (je.status='posted' OR je.reversed_by IS NOT NULL)
        AND date_trunc('month',je.date::TIMESTAMP)=date_trunc('month',CURRENT_DATE::TIMESTAMP)) month_journal_entries,
      (SELECT count(*) FROM approval_requests ar WHERE ar.company_id=p_company_id AND ar.status IN('pending','processing')) pending_approvals,
      (SELECT COALESCE(jsonb_agg(x.name ORDER BY x.name),'[]'::JSONB)
        FROM (SELECT p.name FROM projects p WHERE p.company_id=p_company_id AND p.status='active' ORDER BY p.name LIMIT 5) x) active_project_names
  )
  SELECT jsonb_build_object(
    'revenue',ledger.revenue,'expenses',ledger.expenses,'netProfit',ledger.revenue-ledger.expenses,
    'unpaidInvoices',invoices_due.unpaid_count,'outstandingInvoices',invoices_due.outstanding,
    'overdueInvoiceCount',invoices_due.overdue_count,'overdueInvoices',invoices_due.overdue,
    'totalProjects',counters.total_projects,
    'activeProjects',counters.active_projects,'completedProjects',counters.completed_projects,
    'clients',counters.clients,'suppliers',counters.suppliers,'journalEntries',counters.journal_entries,
    'monthJournalEntries',counters.month_journal_entries,'pendingApprovals',counters.pending_approvals,
    'activeProjectNames',counters.active_project_names
  ) FROM ledger,invoices_due,counters;
$$;

CREATE OR REPLACE FUNCTION public.get_project_budget_rows(
  p_company_id UUID,p_project_id UUID DEFAULT NULL
) RETURNS TABLE(
  id UUID,company_id UUID,project_id UUID,project_name TEXT,category TEXT,subcategory TEXT,
  amount NUMERIC,period TEXT,notes TEXT,created_by UUID,created_at TIMESTAMPTZ,updated_at TIMESTAMPTZ,
  actual_spent NUMERIC
) LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT b.id,b.company_id,b.project_id,p.name,b.category,b.subcategory,b.amount,b.period,b.notes,
    b.created_by,b.created_at,b.updated_at,
    COALESCE((
      SELECT sum(jl.debit-jl.credit)
      FROM journal_lines jl
      JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
        AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
      JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id AND a.type='expense'
      WHERE jl.company_id=p_company_id AND jl.project_id=b.project_id
        AND CASE b.category
          WHEN 'materials' THEN a.code LIKE '51%'
          WHEN 'labor' THEN a.code LIKE '52%'
          WHEN 'equipment' THEN a.code LIKE '53%'
          WHEN 'subcontractor' THEN a.code LIKE '54%'
          WHEN 'overhead' THEN a.code LIKE '55%'
          ELSE a.code NOT LIKE '51%' AND a.code NOT LIKE '52%' AND a.code NOT LIKE '53%'
            AND a.code NOT LIKE '54%' AND a.code NOT LIKE '55%'
        END
    ),0)
  FROM project_budgets b
  JOIN projects p ON p.id=b.project_id AND p.company_id=p_company_id
  WHERE b.company_id=p_company_id AND (p_project_id IS NULL OR b.project_id=p_project_id)
  ORDER BY b.created_at DESC,b.id;
$$;

CREATE OR REPLACE FUNCTION public.create_project_budget_atomic(
  p_company_id UUID,p_project_id UUID,p_category TEXT,p_subcategory TEXT,p_amount NUMERIC,
  p_period TEXT,p_notes TEXT,p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_budget project_budgets%ROWTYPE;
BEGIN
  IF p_category NOT IN('materials','labor','equipment','subcontractor','overhead','other')
    OR p_period NOT IN('total','monthly','quarterly','phase')
    OR p_amount IS NULL OR p_amount<=0 OR p_amount<>ROUND(p_amount,2)
    OR LENGTH(COALESCE(p_subcategory,''))>100 OR LENGTH(COALESCE(p_notes,''))>1000 THEN
    RAISE EXCEPTION 'بيانات الميزانية غير صالحة';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE) THEN
    RAISE EXCEPTION 'المستخدم غير صالح';
  END IF;
  PERFORM 1 FROM projects WHERE id=p_project_id AND company_id=p_company_id
    AND status NOT IN('cancelled') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المشروع غير موجود'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    p_company_id::TEXT||':budget:'||p_project_id::TEXT||':'||p_category,0));
  -- Actuals are classified at project/category level, so allowing two budget
  -- rows for that scope would duplicate the same actual and make variance lie.
  IF EXISTS(
    SELECT 1 FROM project_budgets WHERE company_id=p_company_id AND project_id=p_project_id AND category=p_category
  ) THEN RAISE EXCEPTION 'توجد ميزانية لهذه الفئة في المشروع'; END IF;
  PERFORM set_config('app.budget_write_company',p_company_id::TEXT,TRUE);
  INSERT INTO project_budgets(company_id,project_id,category,subcategory,amount,period,notes,created_by)
  VALUES(p_company_id,p_project_id,p_category,NULLIF(BTRIM(p_subcategory),''),ROUND(p_amount,2),p_period,
    NULLIF(BTRIM(p_notes),''),p_user_id) RETURNING * INTO v_budget;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','project_budget',v_budget.id,to_jsonb(v_budget));
  RETURN to_jsonb(v_budget);
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_project_budget_write()
RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
DECLARE v_company UUID:=COALESCE(NEW.company_id,OLD.company_id);
BEGIN
  IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'budget company is immutable'; END IF;
  IF current_setting('app.business_data_reset',TRUE)=v_company::TEXT THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF current_setting('app.budget_write_company',TRUE) IS DISTINCT FROM v_company::TEXT THEN
    RAISE EXCEPTION 'project budgets require audited functions';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;
DROP TRIGGER IF EXISTS trg_guard_project_budget_write ON project_budgets;
CREATE TRIGGER trg_guard_project_budget_write BEFORE INSERT OR UPDATE OR DELETE ON project_budgets
FOR EACH ROW EXECUTE FUNCTION public.guard_project_budget_write();

REVOKE ALL ON FUNCTION public.get_financial_statement_rows(UUID,DATE,DATE) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.get_report_projects(UUID,BOOLEAN) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.get_assistant_company_snapshot(UUID) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.get_project_budget_rows(UUID,UUID) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.create_project_budget_atomic(UUID,UUID,TEXT,TEXT,NUMERIC,TEXT,TEXT,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_financial_statement_rows(UUID,DATE,DATE) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_report_projects(UUID,BOOLEAN) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_assistant_company_snapshot(UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_project_budget_rows(UUID,UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.create_project_budget_atomic(UUID,UUID,TEXT,TEXT,NUMERIC,TEXT,TEXT,UUID) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 062-project-task-dependencies-and-critical-path.sql
-- ----------------------------------------------------------------------------

-- 062 - Real critical path (CPM) for the Gantt chart.
--
-- The Gantt endpoint previously "computed" the critical path with a heuristic:
--   duration >= 30% of the project OR progress = 0  ⇒ critical
-- That is not a critical path. It flags every unstarted task (including tasks
-- with slack) and misses long chains of short tasks, so the schedule risk shown
-- to a construction project manager was simply wrong.
--
-- A real critical path needs a task dependency graph. This migration adds one
-- (finish-to-start with lag, the dependency type construction schedules use)
-- and implements the standard CPM forward/backward pass in PostgreSQL:
--
--   forward pass  → earliest start/finish (ES/EF)
--   backward pass → latest start/finish (LS/LF)
--   total float   = LS - ES ; tasks with float <= 0 are on the critical path
--
-- Everything is company scoped and cycle safe.

-- ===== Task dependency graph =================================================
CREATE TABLE IF NOT EXISTS project_task_dependencies (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id),
  project_id UUID NOT NULL REFERENCES projects(id),
  -- The task that can only start after `predecessor_task_id` finishes.
  successor_task_id UUID NOT NULL REFERENCES project_tasks(id) ON DELETE CASCADE,
  predecessor_task_id UUID NOT NULL REFERENCES project_tasks(id) ON DELETE CASCADE,
  -- Working-day offset applied after the predecessor finishes (may be negative
  -- for overlap/"lead", which is common in construction schedules).
  lag_days INT NOT NULL DEFAULT 0,
  created_by UUID REFERENCES users(id),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  CONSTRAINT project_task_dependencies_no_self CHECK (successor_task_id <> predecessor_task_id),
  CONSTRAINT project_task_dependencies_lag_sane CHECK (lag_days BETWEEN -365 AND 365),
  CONSTRAINT project_task_dependencies_unique UNIQUE (successor_task_id, predecessor_task_id)
);
CREATE INDEX IF NOT EXISTS idx_task_deps_project ON project_task_dependencies(company_id, project_id);
CREATE INDEX IF NOT EXISTS idx_task_deps_successor ON project_task_dependencies(successor_task_id);
CREATE INDEX IF NOT EXISTS idx_task_deps_predecessor ON project_task_dependencies(predecessor_task_id);

ALTER TABLE project_task_dependencies ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  -- Mirror the tenant policy shape used by 027 for every other tenant table.
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='public' AND tablename='project_task_dependencies'
      AND policyname='project_task_dependencies_tenant_isolation'
  ) THEN
    EXECUTE $ddl$
      CREATE POLICY project_task_dependencies_tenant_isolation
        ON project_task_dependencies
        USING (company_id::TEXT = current_setting('app.current_company', TRUE))
        WITH CHECK (company_id::TEXT = current_setting('app.current_company', TRUE));
    $ddl$;
  END IF;
END;
$$;

-- ===== Dependency writers ====================================================
-- A dependency edge is a schedule decision: it must be tenant checked, must
-- reference two tasks of the SAME project, and must never create a cycle
-- (a cycle would make the CPM non-terminating and the schedule meaningless).
CREATE OR REPLACE FUNCTION public.create_task_dependency_atomic(
  p_company_id UUID, p_successor_task_id UUID, p_predecessor_task_id UUID,
  p_lag_days INT, p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_row project_task_dependencies%ROWTYPE;
  v_successor project_tasks%ROWTYPE;
  v_predecessor project_tasks%ROWTYPE;
  v_lag INT := COALESCE(p_lag_days, 0);
BEGIN
  PERFORM assert_relationship_actor(p_company_id, p_user_id);
  IF p_successor_task_id IS NULL OR p_predecessor_task_id IS NULL
    OR p_successor_task_id = p_predecessor_task_id
    OR v_lag < -365 OR v_lag > 365 THEN
    RAISE EXCEPTION 'بيانات الاعتمادية غير صالحة';
  END IF;

  -- Lock both endpoints in a stable order so concurrent edge inserts cannot
  -- interleave into a cycle that each transaction individually considers safe.
  SELECT * INTO v_successor FROM project_tasks
    WHERE id = LEAST(p_successor_task_id, p_predecessor_task_id) AND company_id = p_company_id FOR UPDATE;
  SELECT * INTO v_predecessor FROM project_tasks
    WHERE id = GREATEST(p_successor_task_id, p_predecessor_task_id) AND company_id = p_company_id FOR UPDATE;

  SELECT * INTO v_successor FROM project_tasks
    WHERE id = p_successor_task_id AND company_id = p_company_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'المهمة غير موجودة'; END IF;
  SELECT * INTO v_predecessor FROM project_tasks
    WHERE id = p_predecessor_task_id AND company_id = p_company_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'المهمة غير موجودة'; END IF;
  IF v_successor.project_id <> v_predecessor.project_id THEN
    RAISE EXCEPTION 'بيانات الاعتمادية غير صالحة';
  END IF;

  -- Cycle guard: the new edge is predecessor → successor, so a cycle exists if
  -- the predecessor is already reachable FROM the successor.
  IF EXISTS (
    WITH RECURSIVE reachable(task_id) AS (
      SELECT p_successor_task_id
      UNION
      SELECT d.successor_task_id
      FROM project_task_dependencies d
      JOIN reachable r ON d.predecessor_task_id = r.task_id
      WHERE d.company_id = p_company_id
    )
    SELECT 1 FROM reachable WHERE task_id = p_predecessor_task_id
  ) THEN
    RAISE EXCEPTION 'دورة في اعتماديات المهام';
  END IF;

  PERFORM set_config('app.task_dependency_write_company', p_company_id::TEXT, TRUE);
  INSERT INTO project_task_dependencies(
    company_id, project_id, successor_task_id, predecessor_task_id, lag_days, created_by)
  VALUES (p_company_id, v_successor.project_id, p_successor_task_id, p_predecessor_task_id, v_lag, p_user_id)
  RETURNING * INTO v_row;

  INSERT INTO audit_log(company_id, user_id, action, entity_type, entity_id, new_values)
  VALUES (p_company_id, p_user_id, 'create', 'project_task_dependency', v_row.id, to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_task_dependency_atomic(
  p_company_id UUID, p_dependency_id UUID, p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row project_task_dependencies%ROWTYPE;
BEGIN
  PERFORM assert_relationship_actor(p_company_id, p_user_id);
  SELECT * INTO v_row FROM project_task_dependencies
    WHERE id = p_dependency_id AND company_id = p_company_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'الاعتمادية غير موجودة'; END IF;

  PERFORM set_config('app.task_dependency_write_company', p_company_id::TEXT, TRUE);
  DELETE FROM project_task_dependencies WHERE id = p_dependency_id AND company_id = p_company_id;
  INSERT INTO audit_log(company_id, user_id, action, entity_type, entity_id, old_values)
  VALUES (p_company_id, p_user_id, 'delete', 'project_task_dependency', v_row.id, to_jsonb(v_row));
  RETURN to_jsonb(v_row);
END;
$$;

-- Direct writes bypass the tenant + cycle checks above, so block them the same
-- way project budgets are protected.
CREATE OR REPLACE FUNCTION public.guard_task_dependency_write()
RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
DECLARE v_company UUID := COALESCE(NEW.company_id, OLD.company_id);
BEGIN
  IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN
    RAISE EXCEPTION 'dependency company is immutable';
  END IF;
  IF current_setting('app.business_data_reset', TRUE) = v_company::TEXT THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  -- ON DELETE CASCADE from project_tasks must stay possible when a task is
  -- removed through its own audited function.
  IF TG_OP='DELETE' AND current_setting('app.relationship_write_company', TRUE) = v_company::TEXT THEN
    RETURN OLD;
  END IF;
  IF current_setting('app.task_dependency_write_company', TRUE) IS DISTINCT FROM v_company::TEXT THEN
    RAISE EXCEPTION 'task dependencies require audited functions';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;
DROP TRIGGER IF EXISTS trg_guard_task_dependency_write ON project_task_dependencies;
CREATE TRIGGER trg_guard_task_dependency_write
BEFORE INSERT OR UPDATE OR DELETE ON project_task_dependencies
FOR EACH ROW EXECUTE FUNCTION public.guard_task_dependency_write();

-- ===== Critical path (CPM) ===================================================
-- Standard CPM over the finish-to-start graph, in calendar days.
--
--   duration = end_date - start_date + 1  (inclusive, matching the UI)
--   ES(t) = max(EF(pred) + lag)  over predecessors, else 0
--   EF(t) = ES(t) + duration
--   LF(t) = min(LS(succ) - lag)  over successors, else project finish
--   LS(t) = LF(t) - duration
--   total_float = LS - ES ; critical ⇔ total_float <= 0
--
-- Tasks with no dependency edges at all are scheduled by their own dates and
-- are only critical when they genuinely finish at the project end date.
CREATE OR REPLACE FUNCTION public.get_project_critical_path(
  p_company_id UUID, p_project_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public STABLE AS $$
DECLARE v_result JSONB;
BEGIN
  IF p_company_id IS NULL OR p_project_id IS NULL THEN
    RETURN jsonb_build_object('tasks', '[]'::JSONB, 'criticalPath', '[]'::JSONB, 'hasCycle', FALSE);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM projects WHERE id = p_project_id AND company_id = p_company_id) THEN
    RETURN jsonb_build_object('tasks', '[]'::JSONB, 'criticalPath', '[]'::JSONB, 'hasCycle', FALSE);
  END IF;

  WITH RECURSIVE
  task AS (
    SELECT t.id, t.name, t.start_date, t.end_date,
           GREATEST((t.end_date - t.start_date) + 1, 1) AS duration,
           COALESCE(t.progress, 0) AS progress
    FROM project_tasks t
    WHERE t.company_id = p_company_id AND t.project_id = p_project_id
  ),
  edge AS (
    -- Only edges whose BOTH endpoints are inside this project/tenant.
    SELECT d.successor_task_id, d.predecessor_task_id, d.lag_days
    FROM project_task_dependencies d
    JOIN task s ON s.id = d.successor_task_id
    JOIN task p ON p.id = d.predecessor_task_id
    WHERE d.company_id = p_company_id AND d.project_id = p_project_id
  ),
  -- Forward pass. Depth is bounded by the task count, which also makes a
  -- (guarded-against but defensively handled) cycle terminate.
  forward(id, duration, ef, depth) AS (
    SELECT t.id, t.duration, t.duration, 1
    FROM task t
    WHERE NOT EXISTS (SELECT 1 FROM edge e WHERE e.successor_task_id = t.id)
    UNION ALL
    SELECT t.id, t.duration, f.ef + e.lag_days + t.duration, f.depth + 1
    FROM forward f
    JOIN edge e ON e.predecessor_task_id = f.id
    JOIN task t ON t.id = e.successor_task_id
    WHERE f.depth <= (SELECT count(*) FROM task)
  ),
  early AS (
    SELECT t.id, t.duration, COALESCE(MAX(f.ef), t.duration) AS ef
    FROM task t LEFT JOIN forward f ON f.id = t.id
    GROUP BY t.id, t.duration
  ),
  finish AS (SELECT COALESCE(MAX(ef), 0) AS project_finish FROM early),
  -- Backward pass from the project finish.
  backward(id, duration, ls, depth) AS (
    SELECT e.id, e.duration, (SELECT project_finish FROM finish) - e.duration, 1
    FROM early e
    WHERE NOT EXISTS (SELECT 1 FROM edge d WHERE d.predecessor_task_id = e.id)
    UNION ALL
    SELECT e.id, e.duration, b.ls - d.lag_days - e.duration, b.depth + 1
    FROM backward b
    JOIN edge d ON d.successor_task_id = b.id
    JOIN early e ON e.id = d.predecessor_task_id
    WHERE b.depth <= (SELECT count(*) FROM task)
  ),
  late AS (
    SELECT e.id, e.duration, e.ef,
           COALESCE(MIN(b.ls), (SELECT project_finish FROM finish) - e.duration) AS ls
    FROM early e LEFT JOIN backward b ON b.id = e.id
    GROUP BY e.id, e.duration, e.ef
  ),
  scheduled AS (
    SELECT l.id, t.name, t.start_date, t.end_date, l.duration, t.progress,
           l.ef - l.duration AS es, l.ef, l.ls, l.ls + l.duration AS lf,
           l.ls - (l.ef - l.duration) AS total_float
    FROM late l JOIN task t ON t.id = l.id
  )
  SELECT jsonb_build_object(
    'tasks', COALESCE(jsonb_agg(jsonb_build_object(
      'id', s.id, 'name', s.name,
      'earliestStart', s.es, 'earliestFinish', s.ef,
      'latestStart', s.ls, 'latestFinish', s.lf,
      'totalFloat', s.total_float,
      'isCritical', s.total_float <= 0
    ) ORDER BY s.es, s.end_date), '[]'::JSONB),
    'criticalPath', COALESCE((
      SELECT jsonb_agg(c.id ORDER BY c.es, c.end_date)
      FROM scheduled c WHERE c.total_float <= 0
    ), '[]'::JSONB),
    'projectDuration', (SELECT project_finish FROM finish),
    'hasCycle', FALSE
  ) INTO v_result
  FROM scheduled s;

  RETURN COALESCE(v_result,
    jsonb_build_object('tasks', '[]'::JSONB, 'criticalPath', '[]'::JSONB, 'hasCycle', FALSE));
END;
$$;

REVOKE ALL ON FUNCTION public.create_task_dependency_atomic(UUID,UUID,UUID,INT,UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.delete_task_dependency_atomic(UUID,UUID,UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.get_project_critical_path(UUID,UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_task_dependency_atomic(UUID,UUID,UUID,INT,UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.delete_task_dependency_atomic(UUID,UUID,UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_project_critical_path(UUID,UUID) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 063-rls-policy-consistency.sql
-- ----------------------------------------------------------------------------

-- ============================================================
-- 063 — RLS policy consistency across tenant tables
--
-- Migration 027 installed the tenant isolation layer:
--     USING (company_id = public.tenant_company_id())
-- where `tenant_company_id()` reads `company_id` from the request JWT claims.
--
-- Three defects survived it. None of them is visible on a local PostgreSQL
-- superuser session (which bypasses RLS entirely) and none is visible while
-- every query runs through the service role (which also bypasses RLS). They
-- only surface under Supabase's `anon` / `authenticated` roles — i.e. exactly
-- the layer the migration suite never exercised.
--
--   1) `invoices` still carries the legacy permissive policy `company_isolation`
--      from 011, created as `USING (true)` with the comment "permissive for now,
--      will be tightened when using anon key". 027 dropped `company_isolation_
--      invoices` and `tenant_isolation_invoices` but never the bare
--      `company_isolation` name, so the policy stayed.
--
--      PostgreSQL OR-combines PERMISSIVE policies. `true OR (company_id = ...)`
--      is `true`, so the isolation policy on the ledger's most sensitive table
--      was dead on arrival: any `authenticated` request read EVERY tenant's
--      invoices. Reproduced against a real engine before writing this fix.
--
--   2) `project_task_dependencies` (062) claims in its own comment to "mirror
--      the tenant policy shape used by 027", but matches on
--      `current_setting('app.current_company', TRUE)` — a GUC that nothing in
--      this repository ever sets. It therefore evaluates to NULL and denies all
--      rows for any RLS-bound role: fail-closed, but permanently broken, and
--      inconsistent with the other 74 tenant tables.
--
--   3) `public.tenant_company_id()` is SECURITY DEFINER without a pinned
--      `search_path`. It is the only such function left in the schema, and it
--      is the one function granted to `anon` and `authenticated` — the exact
--      combination a search_path hijack needs. Every other SECURITY DEFINER
--      function in the schema already pins `search_path=public`.
--
--   4) 027 drove its enrolment loop from a hardcoded `tenant_tables[]` array,
--      so it only ever covered the tables that existed when it was written.
--      51 of the 130 tables that carry a `company_id` were added by later
--      migrations and had RLS switched off altogether — no policy to get wrong,
--      because the row filter was never armed. Part 4 below enrols the table
--      set discovered from the catalogue rather than a literal list, so tenant
--      tables added in future are covered automatically.
--
-- Idempotent and safe to re-run.
-- ============================================================

-- ------------------------------------------------------------
-- 1) Pin search_path on the tenant claim helper.
--    Recreated with the identical body plus `SET search_path`; policies that
--    reference it keep working because the signature is unchanged.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.tenant_company_id()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT NULLIF(
    NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'company_id',
    ''
  )::uuid;
$$;

-- ------------------------------------------------------------
-- 2) Remove every legacy permissive policy that neutralises tenant isolation.
--
--    Scanned generically rather than by name: any PERMISSIVE policy whose USING
--    expression is literally `true` on a table that owns a `company_id` column
--    defeats that table's isolation policy the same way, so the sweep also
--    catches equivalents that predate this migration on other tables.
-- ------------------------------------------------------------
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT c.relname AS tbl, pol.polname AS pol
    FROM pg_policy pol
    JOIN pg_class c      ON c.oid = pol.polrelid
    JOIN pg_namespace n  ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND pol.polpermissive
      AND coalesce(pg_get_expr(pol.polqual, pol.polrelid), 'true') = 'true'
      AND EXISTS (
        SELECT 1 FROM pg_attribute a
        WHERE a.attrelid = c.oid AND a.attname = 'company_id' AND NOT a.attisdropped
      )
      -- Never drop the real isolation policy itself.
      AND pol.polname <> 'tenant_isolation_' || c.relname
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', r.pol, r.tbl);
    RAISE NOTICE '063: dropped permissive policy %.%', r.tbl, r.pol;
  END LOOP;
END $$;

-- ------------------------------------------------------------
-- 3+4) Enable RLS and install the canonical isolation policy on EVERY table that
--    owns a `company_id`, not just the ones 027 happened to list.
--
--    027 drove its loop from a hardcoded `tenant_tables[]` array, so the 51
--    tenant tables added by later migrations were never enrolled and still had
--    RLS switched off entirely. Discovering the table set from the catalogue
--    instead of a literal list is what stops that drift from recurring: any
--    future table with a `company_id` is covered the moment this runs.
--
--    Enabling RLS here cannot lock the application out. No table in this schema
--    grants SELECT/INSERT/UPDATE/DELETE to `anon` or `authenticated` (verified
--    against the catalogue), the application connects through the service role,
--    and both the service role and the table owner bypass RLS. For the roles
--    that RLS does bind, this converts silent full access into tenant-scoped
--    access — defence in depth behind the existing privilege layer.
-- ------------------------------------------------------------
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT c.relname AS tbl, c.oid AS reloid, c.relrowsecurity AS rls_on
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'r'
      AND EXISTS (
        SELECT 1 FROM pg_attribute a
        WHERE a.attrelid = c.oid AND a.attname = 'company_id' AND NOT a.attisdropped
      )
  LOOP
    IF NOT r.rls_on THEN
      EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', r.tbl);
      RAISE NOTICE '063: enabled RLS on %', r.tbl;
    END IF;

    -- Drop a stale isolation policy only when its expression is not already the
    -- canonical one, so re-runs do not churn healthy tables.
    IF EXISTS (
      SELECT 1 FROM pg_policy p
      WHERE p.polrelid = r.reloid
        AND p.polname = 'tenant_isolation_' || r.tbl
        AND pg_get_expr(p.polqual, p.polrelid) IS DISTINCT FROM '(company_id = tenant_company_id())'
    ) THEN
      EXECUTE format('DROP POLICY IF EXISTS %I ON %I', 'tenant_isolation_' || r.tbl, r.tbl);
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM pg_policy p
      WHERE p.polrelid = r.reloid AND p.polname = 'tenant_isolation_' || r.tbl
    ) THEN
      EXECUTE format(
        'CREATE POLICY %I ON %I
           FOR ALL
           USING (company_id = public.tenant_company_id())
           WITH CHECK (company_id = public.tenant_company_id())',
        'tenant_isolation_' || r.tbl, r.tbl
      );
      RAISE NOTICE '063: installed canonical isolation policy on %', r.tbl;
    END IF;
  END LOOP;
END $$;

-- 062's policy name differs from the canonical one, so the block above added
-- the correct policy alongside it. Remove the GUC-based duplicate: leaving it
-- in place would OR a permanently-NULL predicate into the table's ACL, which is
-- harmless today but misleading to read.
DROP POLICY IF EXISTS project_task_dependencies_tenant_isolation ON project_task_dependencies;

-- ----------------------------------------------------------------------------
-- BEGIN 064-supabase-linter-hardening.sql
-- ----------------------------------------------------------------------------

-- ============================================================
-- 064 — Supabase linter hardening
--
-- Driven by the Supabase database linter output captured from the LIVE
-- project (2026-08-17). Four finding classes, and the same lesson as 027/063
-- applies: every fix below is discovered from the catalogue, never from a
-- hand-written list, so functions added later are covered automatically.
--
--   1) `function_search_path_mutable` (19 hits): legacy functions from
--      007/011/012/015/022/023/027/029/031/038 predate the repo convention of
--      pinning `search_path`. An unpinned function resolves table and function
--      names through the CALLER's search_path, so a role that can create
--      objects in an earlier schema can shadow `invoices` or `digest()` and
--      have privileged code execute against the impostor. Everything from 049
--      onwards already pins; this sweeps every remaining unpinned function.
--
--      The pin is `public, extensions, pg_temp` — not bare `public` — because
--      on hosted Supabase pgcrypto lives in the `extensions` schema, so a
--      function pinned to `public` alone cannot see `digest()` there. On CI /
--      local PostgreSQL no `extensions` schema exists and PostgreSQL simply
--      ignores the missing entry, so the same pin is valid everywhere.
--
--   2) The same pgcrypto placement breaks functions that 049+ ALREADY pinned
--      to `search_path=public` and that call `digest()`: correct on CI (where
--      CREATE EXTENSION installs into public), broken on hosted Supabase.
--      Those get their pin widened to include `extensions` too.
--
--   3) `materialized_view_in_api`: `mv_trial_balance` is selectable by
--      `anon`/`authenticated`. Materialized views are NOT subject to RLS, so
--      unlike the tables around it this is a live cross-tenant read of every
--      company's trial balance for anyone holding the anon key. The
--      application reads it exclusively through the service role; nothing
--      legitimate loses access by revoking the API roles.
--
--   4) `anon_security_definer_function_executable`:
--      - `tenant_company_id()`: flagged because it is SECURITY DEFINER and
--        callable by anon/authenticated (the EXECUTE grant is required — RLS
--        policy expressions evaluate as the querying role). But the function
--        only reads `request.jwt.claims`, a GUC every role can already read
--        about its own request: DEFINER buys nothing and is pure lint
--        surface. Recreated as SECURITY INVOKER — same signature, same body,
--        same behaviour under RLS.
--      - `rls_auto_enable()`: exists on the live project but in NO migration
--        in this repository — it was created directly on the instance
--        (dashboard / Supabase assistant). Unknown SECURITY DEFINER plpgsql
--        reachable by `anon` over `/rest/v1/rpc/` is an unacceptable surface,
--        so its EXECUTE is revoked here defensively. It is deliberately NOT
--        dropped: it is not this repository's object, and 063 already covers
--        (better, and idempotently) what its name suggests it does. Drop it
--        manually after confirming no event trigger depends on it:
--          SELECT evtname FROM pg_event_trigger
--          WHERE evtfoid = 'public.rls_auto_enable()'::regprocedure;
--          DROP FUNCTION public.rls_auto_enable();
--
-- Idempotent and safe to re-run.
-- ============================================================

-- ------------------------------------------------------------
-- 1) tenant_company_id: SECURITY INVOKER, pinned. CREATE OR REPLACE keeps the
--    OID, so every tenant_isolation_* policy referencing it is untouched.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.tenant_company_id()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
  SELECT NULLIF(
    NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'company_id',
    ''
  )::uuid;
$$;

-- ------------------------------------------------------------
-- 2) Pin search_path on every remaining unpinned function in public.
--    Catalogue-driven; skips extension-owned members (pg_depend deptype 'e')
--    so a locally-installed pgcrypto is not rewritten, and covers both
--    functions and procedures via ALTER ROUTINE.
-- ------------------------------------------------------------
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    JOIN pg_language l  ON l.oid = p.prolang
    WHERE n.nspname = 'public'
      AND p.prokind IN ('f', 'p')
      AND l.lanname IN ('sql', 'plpgsql')
      AND NOT EXISTS (
        SELECT 1 FROM unnest(coalesce(p.proconfig, '{}')) cfg
        WHERE cfg LIKE 'search_path=%'
      )
      AND NOT EXISTS (
        SELECT 1 FROM pg_depend d
        WHERE d.objid = p.oid AND d.deptype = 'e'
      )
  LOOP
    EXECUTE format('ALTER ROUTINE %s SET search_path = public, extensions, pg_temp', r.sig);
    RAISE NOTICE '064: pinned search_path on %', r.sig;
  END LOOP;
END $$;

-- ------------------------------------------------------------
-- 3) Widen the pin on already-pinned functions that call digest():
--    `search_path=public` cannot resolve pgcrypto on hosted Supabase, where
--    the extension lives in `extensions`. Only exact `public`-pinned bodies
--    that reference digest( are touched; everything else keeps its pin.
-- ------------------------------------------------------------
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prokind IN ('f', 'p')
      AND p.prosrc LIKE '%digest(%'
      AND EXISTS (
        SELECT 1 FROM unnest(coalesce(p.proconfig, '{}')) cfg
        WHERE cfg IN ('search_path=public', 'search_path="public"')
      )
      AND NOT EXISTS (
        SELECT 1 FROM pg_depend d
        WHERE d.objid = p.oid AND d.deptype = 'e'
      )
  LOOP
    EXECUTE format('ALTER ROUTINE %s SET search_path = public, extensions, pg_temp', r.sig);
    RAISE NOTICE '064: widened search_path (digest caller) on %', r.sig;
  END LOOP;
END $$;

-- ------------------------------------------------------------
-- 4) Materialized views are not covered by RLS: no API role may read them.
--    Applied to every MV in public, not just mv_trial_balance, and to future
--    ones via default privileges — MVs and tables share the relation
--    privilege machinery, and the app touches MVs through the service role
--    only.
-- ------------------------------------------------------------
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT c.relname AS mv
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind = 'm'
  LOOP
    EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC, anon, authenticated', r.mv);
    RAISE NOTICE '064: revoked API-role access on materialized view %', r.mv;
  END LOOP;
END $$;

-- ------------------------------------------------------------
-- 5) rls_auto_enable(): out-of-repo SECURITY DEFINER function on the live
--    instance. Revoke API-role EXECUTE if present (guarded — it does not
--    exist in CI databases built purely from these migrations).
-- ------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'rls_auto_enable' AND p.pronargs = 0
  ) THEN
    REVOKE ALL ON FUNCTION public.rls_auto_enable() FROM PUBLIC, anon, authenticated;
    RAISE NOTICE '064: revoked API-role EXECUTE on out-of-repo rls_auto_enable()';
  END IF;
END $$;

-- ----------------------------------------------------------------------------
-- BEGIN 065-repair-additional-user-voucher-approvals.sql
-- ----------------------------------------------------------------------------

-- 065 - Repair the additional-user voucher approval prerequisites.
--
-- The sole company admin bypasses Telegram confirmation, while additional
-- users read company_telegram_configs and can enter the pending approval path.
-- Historical/partially-applied installations can therefore work for the admin
-- but fail with a generic 500 only for additional users when one optional
-- config column is absent or approval_requests came from migration 017's
-- stricter shape (approver_id NOT NULL).
--
-- Keep the policy fail-closed: a requester does not choose an approver when the
-- voucher is created. The admin/Telegram identity is validated when responding.

ALTER TABLE company_telegram_configs
  ADD COLUMN IF NOT EXISTS chat_id TEXT NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS is_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS approvals_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS approval_threshold NUMERIC(15,2) NOT NULL DEFAULT 5000.00;

ALTER TABLE user_permissions
  ADD COLUMN IF NOT EXISTS bypass_telegram_confirmation BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE approval_requests
  ADD COLUMN IF NOT EXISTS transaction_type TEXT,
  ADD COLUMN IF NOT EXISTS transaction_id TEXT,
  ADD COLUMN IF NOT EXISTS amount NUMERIC(15,2),
  ADD COLUMN IF NOT EXISTS requester_id UUID REFERENCES users(id),
  ADD COLUMN IF NOT EXISTS approver_chat_id TEXT,
  ADD COLUMN IF NOT EXISTS message TEXT,
  ADD COLUMN IF NOT EXISTS approved_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS entity_type TEXT,
  ADD COLUMN IF NOT EXISTS entity_id UUID,
  ADD COLUMN IF NOT EXISTS description TEXT,
  ADD COLUMN IF NOT EXISTS approver_id UUID REFERENCES users(id),
  ADD COLUMN IF NOT EXISTS approved_by UUID REFERENCES users(id),
  ADD COLUMN IF NOT EXISTS approval_comments TEXT,
  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

-- Migration 017 originally required approver_id at request creation. Voucher
-- approvals deliberately resolve and authorize the approver at decision time.
ALTER TABLE approval_requests ALTER COLUMN approver_id DROP NOT NULL;

-- Normalize nullable values left by older table variants without weakening the
-- control: NULL/negative thresholds disable automatic threshold triggering;
-- lookup failures in application code still hold vouchers as pending.
UPDATE company_telegram_configs
SET chat_id = COALESCE(chat_id, ''),
    is_enabled = COALESCE(is_enabled, FALSE),
    approvals_enabled = COALESCE(approvals_enabled, FALSE),
    approval_threshold = GREATEST(COALESCE(approval_threshold, 0), 0)
WHERE chat_id IS NULL
   OR is_enabled IS NULL
   OR approvals_enabled IS NULL
   OR approval_threshold IS NULL
   OR approval_threshold < 0;

ALTER TABLE company_telegram_configs
  ALTER COLUMN chat_id SET DEFAULT '',
  ALTER COLUMN chat_id SET NOT NULL,
  ALTER COLUMN is_enabled SET DEFAULT FALSE,
  ALTER COLUMN is_enabled SET NOT NULL,
  ALTER COLUMN approvals_enabled SET DEFAULT FALSE,
  ALTER COLUMN approvals_enabled SET NOT NULL,
  ALTER COLUMN approval_threshold SET DEFAULT 5000.00,
  ALTER COLUMN approval_threshold SET NOT NULL;

-- ----------------------------------------------------------------------------
-- BEGIN 066-global-backup-journal.sql
-- ----------------------------------------------------------------------------

-- 066 - Global backup journal for the developer's whole-database backups.
--
-- The scheduled global backup (scripts/global-backup.ts, driven by the
-- .github/workflows/global-backup.yml cron) keeps its operational state here:
-- what was dumped, where the artifact is stored, and the Telegram message id
-- so the retention policy ("keep the last N copies") can delete old artifacts
-- from storage AND from the Telegram chat.
--
-- This is a PLATFORM-LEVEL operational table: it carries no company_id by
-- design (it journals the whole database, not a tenant), it is never touched
-- by tenant API routes, and it is tiny (one row per backup).

CREATE TABLE IF NOT EXISTS global_backup_journal (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  filename TEXT NOT NULL,
  size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0),
  sha256 TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  storage_path TEXT,
  telegram_message_id TEXT,
  extra JSONB
);

CREATE INDEX IF NOT EXISTS idx_global_backup_journal_created
  ON global_backup_journal(created_at ASC);

-- ----------------------------------------------------------------------------
-- BEGIN 067-audit-hardening-fixes.sql
-- ----------------------------------------------------------------------------

-- ============================================================
-- 067 — Audit hardening fixes (2026-08-19)
--
-- 1. `registration_attempts`: dedicated counter for the registration
--    rate limit (account-farming / mass tenant creation defense).
-- 2. Re-asserts the hardened `create_journal_entry` (same body as
--    migration 047) so any environment that somehow ran the weak
--    bootstrap-only version (supabase-full-schema.sql) ends up with the
--    balanced, tenant-checked implementation. Idempotent by design.
-- ============================================================

-- ---------- 1. Registration rate-limit store ----------

CREATE TABLE IF NOT EXISTS registration_attempts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT NOT NULL,
  ip_address TEXT NOT NULL DEFAULT 'unknown',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_registration_attempts_email_created
  ON registration_attempts (email, created_at);
CREATE INDEX IF NOT EXISTS idx_registration_attempts_ip_created
  ON registration_attempts (ip_address, created_at);

ALTER TABLE registration_attempts ENABLE ROW LEVEL SECURITY;

-- The settings upsert in /api/settings writes updated_at; the canonical
-- bootstrap table lacked the column (42703 on every settings save).
ALTER TABLE settings ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

DROP POLICY IF EXISTS "registration_attempts service only" ON public.registration_attempts;
CREATE POLICY "registration_attempts service only"
  ON public.registration_attempts FOR ALL
  TO service_role USING (TRUE) WITH CHECK (TRUE);

-- ---------- 2. Re-assert hardened create_journal_entry ----------
-- (verbatim from 047-harden-atomic-journal-entry.sql; the function below
--  keeps every guard: balance tolerance, per-line validation, tenant
--  scoping of accounts/contacts/projects, and debit/credit exclusivity)

CREATE OR REPLACE FUNCTION public.create_journal_entry(
  p_company_id UUID,
  p_date DATE,
  p_type TEXT,
  p_description TEXT,
  p_created_by UUID,
  p_lines JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_entry_id UUID;
  v_number INT;
  v_total_debit NUMERIC := 0;
  v_total_credit NUMERIC := 0;
  v_line JSONB;
  v_account RECORD;
  v_debit NUMERIC;
  v_credit NUMERIC;
  v_contact_id UUID;
  v_project_id UUID;
  v_resolved_lines JSONB := '[]'::JSONB;
BEGIN
  IF p_company_id IS NULL OR p_created_by IS NULL OR p_date IS NULL THEN
    RAISE EXCEPTION 'بيانات القيد الأساسية غير مكتملة';
  END IF;
  IF p_type NOT IN ('general', 'opening_balance', 'accrual', 'closing', 'reversing') THEN
    RAISE EXCEPTION 'نوع القيد غير صالح';
  END IF;
  IF jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) < 2 THEN
    RAISE EXCEPTION 'يجب أن يحتوي القيد على سطرين على الأقل';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM users WHERE id = p_created_by AND company_id = p_company_id AND is_active = true
  ) THEN
    RAISE EXCEPTION 'المستخدم المنشئ لا ينتمي إلى الشركة أو غير نشط';
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    BEGIN
      v_debit := COALESCE((v_line->>'debit')::NUMERIC, 0);
      v_credit := COALESCE((v_line->>'credit')::NUMERIC, 0);
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'مبلغ مدين أو دائن غير صالح';
    END;
    IF v_debit < 0 OR v_credit < 0 OR (v_debit = 0 AND v_credit = 0) OR (v_debit > 0 AND v_credit > 0) THEN
      RAISE EXCEPTION 'يجب أن يكون كل سطر مديناً أو دائناً موجباً فقط';
    END IF;
    IF v_debit <> ROUND(v_debit, 2) OR v_credit <> ROUND(v_credit, 2)
       OR v_debit > 9999999999999.99 OR v_credit > 9999999999999.99 THEN
      RAISE EXCEPTION 'المبالغ يجب ألا تتجاوز منزلتين عشريتين والحد المحاسبي المسموح';
    END IF;

    BEGIN
      SELECT id, code, name INTO STRICT v_account
      FROM accounts
      WHERE id = (v_line->>'accountId')::UUID
        AND company_id = p_company_id
        AND COALESCE(is_active, true) = true
        AND COALESCE(is_header, false) = false;
    EXCEPTION WHEN no_data_found THEN
      RAISE EXCEPTION 'الحساب المحدد غير موجود أو غير نشط أو حساب رئيسي';
    WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'معرف الحساب غير صالح';
    END;

    IF NULLIF(v_line->>'contactId', '') IS NOT NULL THEN
      BEGIN
        v_contact_id := (v_line->>'contactId')::UUID;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'معرف الطرف غير صالح';
      END;
      IF NOT EXISTS (SELECT 1 FROM contacts WHERE id = v_contact_id AND company_id = p_company_id) THEN
        RAISE EXCEPTION 'الطرف المحدد لا ينتمي إلى الشركة';
      END IF;
    ELSE
      v_contact_id := NULL;
    END IF;

    IF NULLIF(v_line->>'projectId', '') IS NOT NULL THEN
      BEGIN
        v_project_id := (v_line->>'projectId')::UUID;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'معرف المشروع غير صالح';
      END;
      IF NOT EXISTS (SELECT 1 FROM projects WHERE id = v_project_id AND company_id = p_company_id) THEN
        RAISE EXCEPTION 'المشروع المحدد لا ينتمي إلى الشركة';
      END IF;
    ELSE
      v_project_id := NULL;
    END IF;

    v_total_debit := v_total_debit + v_debit;
    v_total_credit := v_total_credit + v_credit;
    v_resolved_lines := v_resolved_lines || jsonb_build_array(jsonb_build_object(
      'accountId', v_account.id, 'accountCode', v_account.code, 'accountName', v_account.name,
      'debit', v_debit, 'credit', v_credit, 'description', NULLIF(v_line->>'description', ''),
      'contactId', v_contact_id, 'projectId', v_project_id
    ));
  END LOOP;

  IF ABS(v_total_debit - v_total_credit) > 0.005 THEN
    RAISE EXCEPTION 'خطأ في الموازنة: مجموع المدين (%) لا يساوي مجموع الدائن (%)', v_total_debit, v_total_credit;
  END IF;
  IF EXISTS (
    SELECT 1 FROM (
      SELECT l->>'accountId' AS account_id,
             SUM((l->>'debit')::NUMERIC) AS debit,
             SUM((l->>'credit')::NUMERIC) AS credit
      FROM jsonb_array_elements(v_resolved_lines) AS l
      GROUP BY l->>'accountId'
    ) grouped WHERE debit > 0 AND credit > 0
  ) THEN
    RAISE EXCEPTION 'لا يجوز ترحيل الحساب نفسه مديناً ودائناً في القيد الواحد';
  END IF;

  v_number := next_journal_number(p_company_id, EXTRACT(YEAR FROM p_date)::INT);
  INSERT INTO journal_entries (company_id, number, date, type, description, created_by)
  VALUES (p_company_id, v_number, p_date, p_type, COALESCE(p_description, ''), p_created_by)
  RETURNING id INTO v_entry_id;

  INSERT INTO journal_lines (
    company_id, journal_entry_id, account_id, account_code, account_name,
    debit, credit, description, contact_id, project_id
  )
  SELECT p_company_id, v_entry_id,
         (line->>'accountId')::UUID, line->>'accountCode', line->>'accountName',
         (line->>'debit')::NUMERIC, (line->>'credit')::NUMERIC,
         NULLIF(line->>'description', ''),
         NULLIF(line->>'contactId', '')::UUID, NULLIF(line->>'projectId', '')::UUID
  FROM jsonb_array_elements(v_resolved_lines) AS line;

  RETURN jsonb_build_object(
    'id', v_entry_id, 'number', v_number,
    'total_debit', v_total_debit, 'total_credit', v_total_credit,
    'lines_count', jsonb_array_length(v_resolved_lines)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.create_journal_entry(UUID, DATE, TEXT, TEXT, UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_journal_entry(UUID, DATE, TEXT, TEXT, UUID, JSONB) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 068-telegram-approval-actor-fallback.sql
-- ----------------------------------------------------------------------------

-- 068 - Telegram approval decisions: robust approver resolution.
--
-- Vouchers (and other financial operations) created by an additional
-- (non-admin) user above the approval threshold are answered from the
-- Telegram-bound chat. The decision RPC resolved the approver exclusively
-- through company_telegram_configs.configured_by, which:
--   * did not exist before migration 059, so legacy rows hold NULL,
--   * goes stale when the configuring admin is deactivated or downgraded.
-- In both cases the admin who owns the bound chat received the request, but
-- pressing "موافق ✅" failed with the generic "انتهى الطلب أو لا تملك صلاحية
-- معالجته" error even when answered within seconds.
--
-- Fix in two parts:
--   1. Backfill configured_by from the company's active admin for every
--      enabled configuration whose current value is missing or stale.
--   2. Make the decision RPC resolve the actor from the bound chat itself and
--      fall back to an active admin instead of hard-failing. The bound chat is
--      the authorization factor (only that chat receives the buttons); the
--      resolved admin is recorded for the audit trail.

-- 1) Backfill configured_by for enabled configurations. The communication
--    write guard requires the audited-function GUC, so we set it per tenant.
DO $$
DECLARE
  cfg RECORD;
BEGIN
  FOR cfg IN
    SELECT DISTINCT c.company_id
    FROM company_telegram_configs c
    WHERE c.is_enabled = TRUE
      AND NULLIF(BTRIM(c.chat_id), '') IS NOT NULL
      AND (
        c.configured_by IS NULL
        OR NOT EXISTS (
          SELECT 1
          FROM users u2
          WHERE u2.id = c.configured_by
            AND u2.company_id = c.company_id
            AND u2.is_active = TRUE
            AND u2.role = 'admin'
        )
      )
  LOOP
    PERFORM set_config('app.communication_write_company', cfg.company_id::TEXT, TRUE);
    UPDATE company_telegram_configs c
    SET configured_by = (
          SELECT u.id
          FROM users u
          WHERE u.company_id = cfg.company_id AND u.is_active = TRUE AND u.role = 'admin'
          ORDER BY u.created_at, u.id
          LIMIT 1
        ),
        updated_at = NOW()
    WHERE c.company_id = cfg.company_id;
  END LOOP;
END;
$$;

-- 2) Robust approver resolution in the Telegram decision RPC.
CREATE OR REPLACE FUNCTION public.respond_approval_by_telegram_atomic(
  p_approval_id UUID,p_action TEXT,p_chat_id TEXT,p_comments TEXT DEFAULT ''
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_request approval_requests%ROWTYPE;
  v_config company_telegram_configs%ROWTYPE;
  v_actor UUID;
  v_type TEXT;
  v_result JSONB;
BEGIN
  IF p_action NOT IN('approve','reject') OR LENGTH(COALESCE(p_comments,''))>2000 OR NULLIF(p_chat_id,'') IS NULL
  THEN RAISE EXCEPTION 'قرار الاعتماد غير صالح'; END IF;

  SELECT * INTO v_request FROM approval_requests WHERE id=p_approval_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'طلب الاعتماد غير موجود'; END IF;

  SELECT * INTO v_config FROM company_telegram_configs
  WHERE company_id=v_request.company_id AND is_enabled=TRUE AND approvals_enabled=TRUE AND chat_id=p_chat_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'حساب تيليجرام غير مخول بالاعتماد'; END IF;

  -- The bound chat is the authorization factor (only it receives the buttons).
  -- configured_by can be NULL on legacy rows or stale after an admin change, so
  -- resolve the actor from the bound chat and fall back to an active admin
  -- instead of rejecting a legitimate approval from the bound chat.
  v_actor := v_config.configured_by;
  IF v_actor IS NULL OR NOT EXISTS(
    SELECT 1 FROM users WHERE id=v_actor AND company_id=v_request.company_id AND is_active=TRUE AND role='admin'
  ) THEN
    SELECT id INTO v_actor FROM users
    WHERE company_id=v_request.company_id AND is_active=TRUE AND role='admin'
    ORDER BY created_at, id LIMIT 1;
  END IF;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'لا يوجد مدير نشط لاعتماد الطلب'; END IF;

  v_type:=COALESCE(v_request.entity_type,v_request.transaction_type);
  IF v_type='voucher_disbursement' THEN
    v_result:=respond_voucher_disbursement_approval(v_request.company_id,p_approval_id,p_action,v_actor,p_chat_id,p_comments);
  ELSIF v_type='voucher_receipt' THEN
    v_result:=respond_voucher_receipt_approval(v_request.company_id,p_approval_id,p_action,v_actor,p_chat_id,p_comments);
  ELSE
    v_result:=respond_approval_request_atomic(v_request.company_id,p_approval_id,p_action,v_actor,p_comments)
      ||jsonb_build_object('approver_chat_id',p_chat_id);
    UPDATE approval_requests SET approver_chat_id=p_chat_id WHERE id=p_approval_id;
  END IF;
  RETURN v_result||jsonb_build_object('company_id',v_request.company_id,'requester_id',v_request.requester_id,'entity_type',v_type);
END;
$$;

-- ----------------------------------------------------------------------------
-- BEGIN 069-fiscal-year-controls.sql
-- ----------------------------------------------------------------------------

-- 069 - Fiscal-year controls: one open year, and ledger postings must fall
-- within an open fiscal year.
--
-- Answering three accounting controls that were previously missing:
--   1. Every company now has an open fiscal year from the moment it is created
--      (bootstrap trigger) and any legacy company without one is backfilled.
--   2. Ledger postings dated inside a closed year, or outside every open year,
--      are rejected (closing/reversing system entries are exempt).
--   3. A company can never hold two open fiscal years at once.

-- 1) Backfill: any existing company that has no fiscal years at all gets the
--    current calendar year as its open fiscal year.
DO $$
DECLARE v_year INTEGER := EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER;
BEGIN
  INSERT INTO fiscal_years(company_id, name, start_date, end_date, status)
  SELECT c.id, 'السنة المالية ' || v_year,
         make_date(v_year, 1, 1), make_date(v_year, 12, 31), 'open'
  FROM companies c
  WHERE NOT EXISTS (SELECT 1 FROM fiscal_years fy WHERE fy.company_id = c.id)
  ON CONFLICT DO NOTHING;
END;
$$;

-- 2) Hard invariant: only ONE open fiscal year per company.
CREATE UNIQUE INDEX IF NOT EXISTS uq_fiscal_year_single_open
  ON fiscal_years(company_id) WHERE status = 'open';

-- 3) Bootstrap new companies with the current calendar year as their open
--    fiscal year. Covers registration, first-run setup, and any other path
--    that inserts a company row.
CREATE OR REPLACE FUNCTION public.bootstrap_company_fiscal_year()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_year INTEGER := EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER;
BEGIN
  INSERT INTO fiscal_years(company_id, name, start_date, end_date, status)
  VALUES (NEW.id, 'السنة المالية ' || v_year, make_date(v_year,1,1), make_date(v_year,12,31), 'open')
  ON CONFLICT (company_id, name) DO NOTHING;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_company_fiscal_year_bootstrap ON companies;
CREATE TRIGGER trg_company_fiscal_year_bootstrap AFTER INSERT ON companies
  FOR EACH ROW EXECUTE FUNCTION public.bootstrap_company_fiscal_year();

-- 4) DB-enforced non-overlap of fiscal periods. Covers BOTH creation and the
--    edit path (a later date change can silently create an overlap otherwise).
CREATE OR REPLACE FUNCTION public.guard_fiscal_year_no_overlap()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM fiscal_years
    WHERE company_id=NEW.company_id AND id IS DISTINCT FROM NEW.id
      AND start_date<=NEW.end_date AND end_date>=NEW.start_date)
  THEN RAISE EXCEPTION 'الفترة المالية تتداخل مع فترة موجودة';
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_guard_fiscal_year_no_overlap ON fiscal_years;
CREATE TRIGGER trg_guard_fiscal_year_no_overlap
  BEFORE INSERT OR UPDATE OF start_date,end_date,company_id ON fiscal_years
  FOR EACH ROW EXECUTE FUNCTION public.guard_fiscal_year_no_overlap();

-- 5) Clear error when a transition would open a second fiscal year (e.g. the
--    reopen path). The unique index above is the hard backstop.
CREATE OR REPLACE FUNCTION public.guard_single_open_fiscal_year()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
  IF NEW.status='open' AND OLD.status<>'open' AND EXISTS(
    SELECT 1 FROM fiscal_years
    WHERE company_id=NEW.company_id AND status='open' AND id<>NEW.id
  ) THEN
    RAISE EXCEPTION 'لا يمكن فتح أكثر من سنة مالية واحدة في نفس الوقت';
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_guard_single_open_fiscal_year ON fiscal_years;
CREATE TRIGGER trg_guard_single_open_fiscal_year BEFORE UPDATE OF status ON fiscal_years
  FOR EACH ROW EXECUTE FUNCTION public.guard_single_open_fiscal_year();

-- 6) Strict posting guard. An entry dated inside a CLOSED year is rejected,
--    and once a company has fiscal years, an entry dated outside every OPEN
--    year is rejected. Closing/reversing entries are system entries and are
--    exempt from the guard.
CREATE OR REPLACE FUNCTION public.enforce_open_fiscal_year()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  -- Serialize every ledger write with fiscal close/reopen for this tenant.
  PERFORM pg_advisory_xact_lock(hashtextextended('fiscal-ledger:'||NEW.company_id::TEXT,0));
  IF NEW.type IN ('closing','reversing') THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM fiscal_years WHERE company_id=NEW.company_id AND status='closed'
    AND NEW.date BETWEEN start_date AND end_date) THEN
    RAISE EXCEPTION 'لا يمكن الترحيل إلى سنة مالية مقفلة';
  END IF;
  IF EXISTS (SELECT 1 FROM fiscal_years WHERE company_id=NEW.company_id)
    AND NOT EXISTS (SELECT 1 FROM fiscal_years WHERE company_id=NEW.company_id AND status='open'
      AND NEW.date BETWEEN start_date AND end_date) THEN
    RAISE EXCEPTION 'لا توجد سنة مالية مفتوحة تغطي تاريخ العملية';
  END IF;
  RETURN NEW;
END;
$$;

-- 7) Atomic fiscal-year creation: validates dates, blocks date overlaps and a
--    second open year, and records an audit entry (the app previously checked
--    overlaps with a racy read-then-write).
CREATE OR REPLACE FUNCTION public.create_fiscal_year_atomic(
  p_company_id UUID, p_name TEXT, p_start_date DATE, p_end_date DATE, p_user_id UUID
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_year fiscal_years%ROWTYPE;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  IF NULLIF(BTRIM(p_name),'') IS NULL OR LENGTH(p_name)>200 OR p_start_date IS NULL OR p_end_date IS NULL
    OR p_end_date < p_start_date THEN RAISE EXCEPTION 'بيانات السنة المالية غير صالحة'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('fiscal-year:'||p_company_id::TEXT,0));
  IF EXISTS(SELECT 1 FROM fiscal_years WHERE company_id=p_company_id
    AND start_date<=p_end_date AND end_date>=p_start_date)
  THEN RAISE EXCEPTION 'الفترة المالية تتداخل مع فترة موجودة'; END IF;
  IF EXISTS(SELECT 1 FROM fiscal_years WHERE company_id=p_company_id AND status='open')
  THEN RAISE EXCEPTION 'لا يمكن فتح أكثر من سنة مالية واحدة في نفس الوقت'; END IF;
  INSERT INTO fiscal_years(company_id,name,start_date,end_date,status)
  VALUES(p_company_id,BTRIM(p_name),p_start_date,p_end_date,'open') RETURNING * INTO v_year;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','fiscal_year',v_year.id,to_jsonb(v_year));
  RETURN to_jsonb(v_year);
END;
$$;
REVOKE ALL ON FUNCTION public.create_fiscal_year_atomic(UUID,TEXT,DATE,DATE,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_fiscal_year_atomic(UUID,TEXT,DATE,DATE,UUID) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 070-operational-document-numbers.sql
-- ----------------------------------------------------------------------------

-- Stable tenant-scoped numbers for operational transactions that previously
-- exposed UUIDs only. Human prefixes are presentation-level (CT/STK/BR); the
-- database stores the concurrency-safe numeric sequence.

ALTER TABLE cash_transactions ADD COLUMN IF NOT EXISTS number INTEGER;
ALTER TABLE inventory_transactions ADD COLUMN IF NOT EXISTS number INTEGER;
ALTER TABLE bank_reconciliation ADD COLUMN IF NOT EXISTS number INTEGER;

WITH ranked AS (
  SELECT id, row_number() OVER (PARTITION BY company_id ORDER BY created_at, id)::INTEGER AS seq
  FROM cash_transactions
) UPDATE cash_transactions target SET number=ranked.seq FROM ranked
  WHERE target.id=ranked.id AND target.number IS NULL;

WITH ranked AS (
  SELECT id, row_number() OVER (PARTITION BY company_id ORDER BY created_at, id)::INTEGER AS seq
  FROM inventory_transactions
) UPDATE inventory_transactions target SET number=ranked.seq FROM ranked
  WHERE target.id=ranked.id AND target.number IS NULL;

WITH ranked AS (
  SELECT id, row_number() OVER (PARTITION BY company_id ORDER BY created_at, id)::INTEGER AS seq
  FROM bank_reconciliation
) UPDATE bank_reconciliation target SET number=ranked.seq FROM ranked
  WHERE target.id=ranked.id AND target.number IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_cash_transactions_company_number
  ON cash_transactions(company_id, number);
CREATE UNIQUE INDEX IF NOT EXISTS uq_inventory_transactions_company_number
  ON inventory_transactions(company_id, number);
CREATE UNIQUE INDEX IF NOT EXISTS uq_bank_reconciliation_company_number
  ON bank_reconciliation(company_id, number);

CREATE OR REPLACE FUNCTION public.assign_operational_document_number()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_next INTEGER;
BEGIN
  IF NEW.company_id IS NULL THEN RAISE EXCEPTION 'company_id is required for document numbering'; END IF;
  IF NEW.number IS NOT NULL THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'operational-number:' || TG_TABLE_NAME || ':' || NEW.company_id::TEXT, 0
  ));
  EXECUTE format('SELECT COALESCE(MAX(number),0)+1 FROM public.%I WHERE company_id=$1', TG_TABLE_NAME)
    INTO v_next USING NEW.company_id;
  NEW.number := v_next;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_cash_transaction_number ON cash_transactions;
CREATE TRIGGER trg_cash_transaction_number BEFORE INSERT ON cash_transactions
  FOR EACH ROW EXECUTE FUNCTION public.assign_operational_document_number();
DROP TRIGGER IF EXISTS trg_inventory_transaction_number ON inventory_transactions;
CREATE TRIGGER trg_inventory_transaction_number BEFORE INSERT ON inventory_transactions
  FOR EACH ROW EXECUTE FUNCTION public.assign_operational_document_number();
DROP TRIGGER IF EXISTS trg_bank_reconciliation_number ON bank_reconciliation;
CREATE TRIGGER trg_bank_reconciliation_number BEFORE INSERT ON bank_reconciliation
  FOR EACH ROW EXECUTE FUNCTION public.assign_operational_document_number();

ALTER TABLE cash_transactions ALTER COLUMN number SET NOT NULL;
ALTER TABLE inventory_transactions ALTER COLUMN number SET NOT NULL;
ALTER TABLE bank_reconciliation ALTER COLUMN number SET NOT NULL;

REVOKE ALL ON FUNCTION public.assign_operational_document_number() FROM PUBLIC,anon,authenticated;

-- ----------------------------------------------------------------------------
-- BEGIN 071-project-costing-integrity.sql
-- ----------------------------------------------------------------------------

-- ============================================================================
-- 071: Project costing integrity
--
-- 1. Inventory issue/return movements can now be allocated to a project.
--    Before this, material issued from stock was posted to the cost of sales
--    account (5100) WITHOUT a project_id, so direct material costs never
--    appeared in any project profitability / WIP report. Now the movement
--    accepts an optional p_project_id, validates it (tenant + active), tags
--    the cost journal line with projectId, and stores it on the transaction.
-- 2. This mirrors the tenant/active validation used by every other project
--    cost entry point (post_project_expense, post_equipment_cost, …).
-- ============================================================================

DROP FUNCTION IF EXISTS public.post_inventory_movement_atomic(
  UUID,UUID,UUID,TEXT,NUMERIC,NUMERIC,DATE,TEXT,UUID,UUID
);

CREATE OR REPLACE FUNCTION public.post_inventory_movement_atomic(
  p_company_id UUID,p_item_id UUID,p_warehouse_id UUID,p_type TEXT,p_quantity NUMERIC,
  p_unit_price NUMERIC,p_date DATE,p_notes TEXT,p_to_warehouse_id UUID,p_user_id UUID,
  p_project_id UUID DEFAULT NULL
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_item inventory_items%ROWTYPE; v_target inventory_items%ROWTYPE; v_warehouse warehouses%ROWTYPE;
  v_before NUMERIC; v_after NUMERIC; v_target_before NUMERIC; v_target_after NUMERIC;
  v_cost NUMERIC; v_value NUMERIC; v_diff NUMERIC; v_kind TEXT; v_txn inventory_transactions%ROWTYPE;
  v_inventory UUID; v_income UUID; v_cost_account UUID; v_debit UUID; v_credit UUID;
  v_journal JSONB; v_journal_id UUID; v_txn_id UUID:=gen_random_uuid(); v_lines JSONB;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  v_kind:=CASE WHEN p_type='adjust' THEN 'adjustment' ELSE p_type END;
  IF v_kind NOT IN('add','issue','adjustment','transfer','return') OR p_date IS NULL
    OR p_quantity IS NULL OR p_quantity<0 OR p_quantity<>round(p_quantity,2)
    OR (v_kind<>'adjustment' AND p_quantity<=0)
    OR (p_unit_price IS NOT NULL AND (p_unit_price<0 OR p_unit_price<>round(p_unit_price,2)))
    OR length(COALESCE(p_notes,''))>500
  THEN RAISE EXCEPTION 'بيانات الحركة المخزنية غير صالحة'; END IF;

  -- Project allocation is only meaningful for consumption (issue / return of
  -- material to a project). Reject it for stock-in, adjustment and transfer,
  -- and validate the project is an active tenant project like every other
  -- project-cost entry point.
  IF p_project_id IS NOT NULL THEN
    IF v_kind NOT IN ('issue','return') THEN
      RAISE EXCEPTION 'ربط المشروع مسموح فقط لحركات الصرف والإرجاع';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM projects WHERE id=p_project_id AND company_id=p_company_id AND status='active') THEN
      RAISE EXCEPTION 'المشروع غير صالح أو غير نشط';
    END IF;
  END IF;

  SELECT * INTO v_item FROM inventory_items WHERE id=p_item_id AND company_id=p_company_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'الصنف غير موجود'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('inventory-stock:'||p_company_id::TEXT||':'||lower(v_item.code),0));
  SELECT * INTO v_item FROM inventory_items WHERE id=p_item_id AND company_id=p_company_id FOR UPDATE;
  IF NOT COALESCE(v_item.is_active,TRUE) THEN RAISE EXCEPTION 'الصنف غير نشط'; END IF;
  IF v_item.warehouse_id<>p_warehouse_id THEN RAISE EXCEPTION 'الصنف لا ينتمي إلى مستودع المصدر'; END IF;
  SELECT * INTO v_warehouse FROM warehouses WHERE id=p_warehouse_id AND company_id=p_company_id AND COALESCE(is_active,TRUE);
  IF NOT FOUND THEN RAISE EXCEPTION 'مستودع المصدر غير موجود'; END IF;

  v_before:=COALESCE(v_item.quantity,0); v_after:=v_before; v_cost:=COALESCE(v_item.unit_price,0);
  IF v_kind='add' THEN
    v_cost:=COALESCE(p_unit_price,v_cost);
    IF v_cost<0 THEN RAISE EXCEPTION 'تكلفة الإضافة غير صالحة'; END IF;
    v_after:=round(v_before+p_quantity,2);
    IF v_after>0 THEN
      v_cost:=round(((v_before*COALESCE(v_item.unit_price,0))+(p_quantity*v_cost))/v_after,2);
    END IF;
    v_value:=round(p_quantity*COALESCE(p_unit_price,v_item.unit_price,0),2);
    v_debit:=NULL; v_credit:=NULL;
  ELSIF v_kind='issue' THEN
    IF v_before+0.005<p_quantity THEN RAISE EXCEPTION 'الكمية غير متوفرة في المخزون'; END IF;
    v_after:=round(v_before-p_quantity,2); v_value:=round(p_quantity*v_cost,2);
  ELSIF v_kind='return' THEN
    v_after:=round(v_before+p_quantity,2); v_value:=round(p_quantity*v_cost,2);
  ELSIF v_kind='adjustment' THEN
    v_diff:=round(p_quantity-v_before,2);
    IF abs(v_diff)<0.005 THEN RAISE EXCEPTION 'لا فرق عن الرصيد الحالي'; END IF;
    v_after:=p_quantity; v_value:=round(abs(v_diff)*v_cost,2);
  ELSE
    IF p_to_warehouse_id IS NULL OR p_to_warehouse_id=p_warehouse_id THEN RAISE EXCEPTION 'مستودع الوجهة غير صالح'; END IF;
    IF v_before+0.005<p_quantity THEN RAISE EXCEPTION 'الكمية غير متوفرة في المخزون'; END IF;
    IF NOT EXISTS(SELECT 1 FROM warehouses WHERE id=p_to_warehouse_id AND company_id=p_company_id AND COALESCE(is_active,TRUE))
    THEN RAISE EXCEPTION 'مستودع الوجهة غير موجود'; END IF;
    SELECT * INTO v_target FROM inventory_items WHERE company_id=p_company_id AND warehouse_id=p_to_warehouse_id
      AND lower(code)=lower(v_item.code) FOR UPDATE;
    IF v_target.id IS NULL THEN
      INSERT INTO inventory_items(company_id,code,name,unit,warehouse_id,quantity,unit_price,category,is_active)
      VALUES(p_company_id,v_item.code,v_item.name,v_item.unit,p_to_warehouse_id,0,v_cost,v_item.category,TRUE)
      RETURNING * INTO v_target;
    ELSIF NOT COALESCE(v_target.is_active,TRUE) THEN
      RAISE EXCEPTION 'صنف الوجهة غير نشط';
    END IF;
    v_target_before:=COALESCE(v_target.quantity,0); v_target_after:=round(v_target_before+p_quantity,2);
    UPDATE inventory_items SET quantity=v_target_after,
      unit_price=CASE WHEN v_target_after=0 THEN v_cost
        ELSE round(((v_target_before*COALESCE(v_target.unit_price,0))+(p_quantity*v_cost))/v_target_after,2) END,
      updated_at=now() WHERE id=v_target.id;
    v_after:=round(v_before-p_quantity,2); v_value:=round(p_quantity*v_cost,2);
  END IF;

  -- Financially effective stock movements are posted in the same transaction.
  -- The cost line (inventory <-> cost of sales) is tagged with the project so
  -- the material cost flows into project profitability / WIP reports.
  IF v_kind<>'transfer' AND v_value>0 THEN
    SELECT id INTO v_inventory FROM accounts WHERE company_id=p_company_id AND code='1170'
      AND COALESCE(is_active,TRUE) AND NOT COALESCE(is_header,FALSE);
    SELECT id INTO v_income FROM accounts WHERE company_id=p_company_id AND code='4200'
      AND COALESCE(is_active,TRUE) AND NOT COALESCE(is_header,FALSE);
    SELECT id INTO v_cost_account FROM accounts WHERE company_id=p_company_id AND code='5100'
      AND COALESCE(is_active,TRUE) AND NOT COALESCE(is_header,FALSE);
    IF v_inventory IS NULL THEN RAISE EXCEPTION 'حساب المخزون 1170 غير موجود'; END IF;
    IF v_kind='add' OR (v_kind='adjustment' AND v_diff>0) THEN v_debit:=v_inventory; v_credit:=v_income;
    ELSIF v_kind='return' THEN v_debit:=v_inventory; v_credit:=v_cost_account;
    ELSE v_debit:=v_cost_account; v_credit:=v_inventory; END IF;
    IF v_debit IS NULL OR v_credit IS NULL THEN RAISE EXCEPTION 'حساب مقابل حركة المخزون غير موجود'; END IF;
    v_lines:=jsonb_build_array(
      jsonb_build_object('accountId',v_debit,'debit',v_value,'credit',0,'projectId',p_project_id),
      jsonb_build_object('accountId',v_credit,'debit',0,'credit',v_value,'projectId',p_project_id)
    );
    v_journal:=create_journal_entry(p_company_id,p_date,'general','حركة مخزون: '||v_item.name,p_user_id,v_lines);
    v_journal_id:=(v_journal->>'id')::UUID;
    UPDATE journal_entries SET reference_type='inventory_movement',reference_id=v_txn_id
      WHERE id=v_journal_id AND company_id=p_company_id;
  END IF;

  UPDATE inventory_items SET quantity=v_after,unit_price=v_cost,updated_at=now() WHERE id=v_item.id;
  INSERT INTO inventory_transactions(
    id,company_id,item_id,warehouse_id,to_warehouse_id,type,quantity,unit_price,total_value,
    balance_before,balance_after,date,notes,reference_type,reference_id,created_by,project_id
  ) VALUES(
    v_txn_id,p_company_id,v_item.id,p_warehouse_id,p_to_warehouse_id,v_kind,
    CASE WHEN v_kind='adjustment' THEN abs(v_diff) ELSE p_quantity END,
    v_cost,v_value,v_before,v_after,p_date,NULLIF(btrim(p_notes),''),
    CASE WHEN v_journal_id IS NULL THEN NULL ELSE 'journal_entry' END,v_journal_id,p_user_id,p_project_id
  ) RETURNING * INTO v_txn;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','inventory_transaction',v_txn.id,
    to_jsonb(v_txn)||CASE WHEN v_kind='transfer' THEN jsonb_build_object('target_item_id',v_target.id,
      'target_balance_before',v_target_before,'target_balance_after',v_target_after) ELSE '{}'::JSONB END);
  RETURN jsonb_build_object('transaction',to_jsonb(v_txn),'source_quantity',v_after,
    'target_quantity',CASE WHEN v_kind='transfer' THEN v_target_after ELSE NULL END,'journal_entry_id',v_journal_id);
END;
$$;

REVOKE ALL ON FUNCTION public.post_inventory_movement_atomic(UUID,UUID,UUID,TEXT,NUMERIC,NUMERIC,DATE,TEXT,UUID,UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.post_inventory_movement_atomic(UUID,UUID,UUID,TEXT,NUMERIC,NUMERIC,DATE,TEXT,UUID,UUID,UUID) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 072-project-costing-allocation.sql
-- ----------------------------------------------------------------------------

-- ============================================================================
-- 072: Project costing — direct labor allocation & overhead (indirect) costs
--
-- Follows international construction-accounting practice (Sage 300 CRE,
-- QuickBooks for Contractors, Viewpoint, NetSuite job costing):
--
--  1. DIRECT LABOR -> project
--     Each salary-sheet item (an employee's salary line) can now carry an
--     optional project_id. When the salary sheet is eventually posted to the
--     ledger, the direct-labour cost is attributed to that project — the same
--     "tag payroll lines to job + cost code" pattern the majors use.
--     (Base wages live on account 5210 / direct labour 5120 and are
--     recognised as project labour by the shared cost classifier.)
--
--  2. INDIRECT / OVERHEAD costs -> project
--     A company may define one or more overhead-allocation rules. Each rule
--     picks an allocation basis and a rate:
--        basis = 'direct_cost'  -> allocated = rate x project direct cost
--        basis = 'direct_labor' -> allocated = rate x project direct labour
--     This mirrors Sage 300's overhead-type-and-rate-on-a-cost-category and
--     the standard "percentage of direct cost / direct labour" methods. The
--     allocated amount is reported SEPARATELY from direct costs so true job
--     profitability can be seen (direct profit vs. profit after overhead).
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1) Direct labor -> project: salary item carries an optional project.
-- ---------------------------------------------------------------------------
ALTER TABLE salary_items
  ADD COLUMN IF NOT EXISTS project_id UUID REFERENCES projects(id);

CREATE INDEX IF NOT EXISTS idx_salary_items_project
  ON salary_items(company_id, project_id);

-- Tenant guard: a salary item's project must belong to the same company as the
-- item (mirrors the guard used by the other project-cost entry points).
CREATE OR REPLACE FUNCTION public.guard_salary_item_project_tenant()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF NEW.project_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM projects WHERE id=NEW.project_id AND company_id=NEW.company_id
  ) THEN
    RAISE EXCEPTION 'salary item project tenant mismatch';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_guard_salary_item_project_tenant ON salary_items;
CREATE TRIGGER trg_guard_salary_item_project_tenant
  BEFORE INSERT OR UPDATE ON salary_items
  FOR EACH ROW EXECUTE FUNCTION public.guard_salary_item_project_tenant();

-- ---------------------------------------------------------------------------
-- 2) Overhead (indirect) allocation rules
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS overhead_allocations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  allocation_basis TEXT NOT NULL DEFAULT 'direct_cost'
    CHECK (allocation_basis IN ('direct_cost', 'direct_labor')),
  rate NUMERIC(10,4) NOT NULL DEFAULT 0
    CHECK (rate >= 0 AND rate <= 1 AND rate = ROUND(rate, 4)),
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(company_id, name)
);

CREATE INDEX IF NOT EXISTS idx_overhead_allocations_company
  ON overhead_allocations(company_id, is_active);

-- Update timestamp on rule edits.
CREATE OR REPLACE FUNCTION public.touch_overhead_allocation()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_touch_overhead_allocation ON overhead_allocations;
CREATE TRIGGER trg_touch_overhead_allocation
  BEFORE UPDATE ON overhead_allocations
  FOR EACH ROW EXECUTE FUNCTION public.touch_overhead_allocation();

REVOKE ALL ON TABLE public.overhead_allocations FROM PUBLIC, anon, authenticated;

ALTER TABLE public.overhead_allocations ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation_overhead_allocations ON public.overhead_allocations;
CREATE POLICY tenant_isolation_overhead_allocations ON public.overhead_allocations
  FOR ALL
  USING (company_id = public.tenant_company_id())
  WITH CHECK (company_id = public.tenant_company_id());

-- ---------------------------------------------------------------------------
-- 3) Per-project costing + allocated overhead (single source for reports)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_project_costing_overhead(
  p_company_id UUID,
  p_project_ids UUID[] DEFAULT NULL,
  p_from DATE DEFAULT NULL,
  p_to DATE DEFAULT NULL
) RETURNS TABLE(
  project_id UUID,
  direct_cost NUMERIC,
  direct_labor NUMERIC,
  allocated_overhead NUMERIC,
  allocation_basis TEXT,
  rate NUMERIC
) LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  WITH totals AS (
    SELECT jl.project_id,
      COALESCE(sum(CASE WHEN a.type='expense' THEN jl.debit-jl.credit ELSE 0 END),0) AS direct_cost,
      COALESCE(sum(CASE WHEN a.type='expense'
        AND (a.code LIKE '512%' OR a.code LIKE '521%') THEN jl.debit-jl.credit ELSE 0 END),0) AS direct_labor
    FROM journal_lines jl
    JOIN journal_entries je ON je.id=jl.journal_entry_id AND je.company_id=p_company_id
      AND je.deleted_at IS NULL AND (je.status='posted' OR je.reversed_by IS NOT NULL)
    JOIN accounts a ON a.id=jl.account_id AND a.company_id=p_company_id
    JOIN projects p ON p.id=jl.project_id AND p.company_id=p_company_id
    WHERE jl.company_id=p_company_id AND jl.project_id IS NOT NULL
      AND (p_project_ids IS NULL OR jl.project_id=ANY(p_project_ids))
      AND (p_from IS NULL OR je.date>=p_from) AND (p_to IS NULL OR je.date<=p_to)
    GROUP BY jl.project_id
  ),
  rules AS (
    SELECT allocation_basis, rate, row_number() OVER (ORDER BY created_at, id) AS rn
    FROM overhead_allocations
    WHERE company_id=p_company_id AND is_active=TRUE
  ),
  combined AS (
    SELECT t.project_id, t.direct_cost, t.direct_labor,
      COALESCE(sum(r.rate * CASE WHEN r.allocation_basis='direct_labor' THEN t.direct_labor ELSE t.direct_cost END),0) AS allocated_overhead,
      min(r.allocation_basis) AS basis,
      COALESCE(sum(r.rate),0) AS rate
    FROM totals t CROSS JOIN rules r
    GROUP BY t.project_id, t.direct_cost, t.direct_labor
  )
  SELECT t.project_id, t.direct_cost, t.direct_labor,
    COALESCE(c.allocated_overhead,0),
    COALESCE(c.basis, 'direct_cost'),
    COALESCE(c.rate,0)
  FROM totals t LEFT JOIN combined c ON c.project_id=t.project_id;
$$;

REVOKE ALL ON FUNCTION public.get_project_costing_overhead(UUID, UUID[], DATE, DATE)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_project_costing_overhead(UUID, UUID[], DATE, DATE)
  TO service_role;

-- ---------------------------------------------------------------------------
-- 4) create_salary_sheet now accepts an optional project_id per item so each
--    employee's labour cost can be allocated to a project (direct labour).
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.create_salary_sheet(
  p_company_id UUID, p_name TEXT, p_month INTEGER, p_year INTEGER,
  p_date DATE, p_items JSONB
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_sheet salary_sheets%ROWTYPE; v_item JSONB; v_employee UUID; v_project UUID;
  v_basic NUMERIC; v_allowances NUMERIC; v_deductions NUMERIC;
BEGIN
  IF NULLIF(BTRIM(p_name),'') IS NULL OR LENGTH(p_name)>200 OR p_month NOT BETWEEN 1 AND 12 OR p_year NOT BETWEEN 2000 AND 9999 THEN
    RAISE EXCEPTION 'بيانات كشف الرواتب غير صالحة';
  END IF;
  IF jsonb_typeof(COALESCE(p_items,'[]'::JSONB))<>'array' OR jsonb_array_length(COALESCE(p_items,'[]'::JSONB))>1000 THEN
    RAISE EXCEPTION 'بنود كشف الرواتب غير صالحة';
  END IF;
  INSERT INTO salary_sheets(company_id,name,month,year,date,status)
  VALUES(p_company_id,BTRIM(p_name),p_month,p_year,p_date,'draft') RETURNING * INTO v_sheet;
  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items,'[]'::JSONB))
  LOOP
    BEGIN
      v_employee:=(v_item->>'employee_id')::UUID;
      v_basic:=COALESCE((v_item->>'basic_salary')::NUMERIC,0);
      v_allowances:=COALESCE((v_item->>'allowances')::NUMERIC,0);
      v_deductions:=COALESCE((v_item->>'deductions')::NUMERIC,0);
      v_project:=NULLIF((v_item->>'project_id')::TEXT,'')::UUID;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'أحد بنود كشف الرواتب غير صالح';
    END;
    IF NOT EXISTS(SELECT 1 FROM employees WHERE id=v_employee AND company_id=p_company_id AND COALESCE(is_active,TRUE)=TRUE) THEN
      RAISE EXCEPTION 'أحد الموظفين غير موجود أو غير نشط';
    END IF;
    IF v_project IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM projects WHERE id=v_project AND company_id=p_company_id AND status='active'
    ) THEN
      RAISE EXCEPTION 'المشروع المرتبط ببند الرواتب غير صالح أو غير نشط';
    END IF;
    IF v_basic<0 OR v_allowances<0 OR v_deductions<0 OR v_basic<>ROUND(v_basic,2)
      OR v_allowances<>ROUND(v_allowances,2) OR v_deductions<>ROUND(v_deductions,2)
      OR v_basic+v_allowances-v_deductions<0 THEN RAISE EXCEPTION 'أحد بنود كشف الرواتب غير صالح'; END IF;
    INSERT INTO salary_items(company_id,sheet_id,employee_id,basic_salary,allowances,deductions,net_pay,project_id)
    VALUES(p_company_id,v_sheet.id,v_employee,v_basic,v_allowances,v_deductions,v_basic+v_allowances-v_deductions,v_project);
  END LOOP;
  RETURN to_jsonb(v_sheet);
END;
$$;

REVOKE ALL ON FUNCTION public.create_salary_sheet(UUID,TEXT,INTEGER,INTEGER,DATE,JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_salary_sheet(UUID,TEXT,INTEGER,INTEGER,DATE,JSONB) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 073-project-no-auto-invoice.sql
-- ----------------------------------------------------------------------------

-- ============================================================================
-- 073: Project is a reference record — it must never auto-create an invoice
--
-- Business rule (requested): creating a project must NOT create an invoice,
-- must NOT post a journal entry, and must NOT affect the client's balance.
-- The client link on the project is reference-only (for reviewing a client's
-- projects). Invoices are created manually and can be derived from the
-- project; only invoices move the client balance.
--
-- The previous create_project_atomic accepted p_auto_invoice and, when true,
-- created a sales invoice (and effectively touched the client). We remove
-- that path entirely while keeping the function signature stable so existing
-- callers and the wrapper continue to work.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.create_project_atomic(
  p_company_id UUID,p_name TEXT,p_client_id UUID,p_contract_value NUMERIC,
  p_start_date DATE,p_end_date DATE,p_status TEXT,p_description TEXT,p_location TEXT,
  p_items JSONB,p_auto_invoice BOOLEAN,p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_project projects%ROWTYPE;
  v_client UUID:=p_client_id;
  v_contact contacts%ROWTYPE;
  v_item JSONB;
  v_qty NUMERIC;
  v_price NUMERIC;
  v_items_total NUMERIC:=0;
BEGIN
  IF NULLIF(btrim(p_name),'') IS NULL OR length(p_name)>300 OR p_contract_value<=0
    OR p_start_date IS NULL OR (p_end_date IS NOT NULL AND p_end_date<p_start_date)
    OR p_status NOT IN ('active','on_hold') OR jsonb_typeof(p_items)<>'array'
    OR jsonb_array_length(p_items)>1000 OR length(COALESCE(p_description,''))>5000
    OR length(COALESCE(p_location,''))>1000
  THEN RAISE EXCEPTION 'بيانات المشروع غير صالحة'; END IF;
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  PERFORM set_config('app.project_write_company',p_company_id::TEXT,TRUE);

  IF v_client IS NULL THEN
    -- A project without a chosen client stays reference-only (no cash-customer
    -- auto-creation, no invoice). The client link is optional for projects.
    v_client:=NULL;
  ELSIF NOT EXISTS(
    SELECT 1 FROM contacts WHERE id=v_client AND company_id=p_company_id AND COALESCE(is_active,TRUE)
  ) THEN RAISE EXCEPTION 'العميل غير موجود'; END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    BEGIN v_qty:=(v_item->>'quantity')::NUMERIC; v_price:=(v_item->>'unit_price')::NUMERIC;
    EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'بند جدول كميات غير صالح'; END;
    IF NULLIF(btrim(v_item->>'description'),'') IS NULL OR v_qty<=0 OR v_price<0
    THEN RAISE EXCEPTION 'بند جدول كميات غير صالح'; END IF;
    v_items_total:=v_items_total+round(v_qty*v_price,2);
  END LOOP;
  IF jsonb_array_length(p_items)>0 AND abs(v_items_total-p_contract_value)>0.01 THEN
    RAISE EXCEPTION 'قيمة العقد لا تطابق إجمالي جدول الكميات';
  END IF;

  INSERT INTO projects(
    company_id,name,client_id,contract_value,start_date,end_date,status,
    description,location,created_by
  ) VALUES(
    p_company_id,btrim(p_name),v_client,p_contract_value,p_start_date,p_end_date,
    p_status,NULLIF(btrim(p_description),''),NULLIF(btrim(p_location),''),p_user_id
  ) RETURNING * INTO v_project;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_qty:=(v_item->>'quantity')::NUMERIC; v_price:=(v_item->>'unit_price')::NUMERIC;
    INSERT INTO boq_items(company_id,project_id,description,unit,quantity,unit_price,total)
    VALUES(p_company_id,v_project.id,btrim(v_item->>'description'),COALESCE(NULLIF(btrim(v_item->>'unit'),''),'واحدة'),v_qty,v_price,round(v_qty*v_price,2));
  END LOOP;

  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values)
  VALUES(p_company_id,p_user_id,'create','project',v_project.id,to_jsonb(v_project));
  RETURN to_jsonb(v_project)||jsonb_build_object(
    'invoice',NULL,
    'boq_items_count',jsonb_array_length(p_items)
  );
END;
$$;

-- ----------------------------------------------------------------------------
-- BEGIN 074-voucher-auto-settlement.sql
-- ----------------------------------------------------------------------------

-- ============================================================================
-- 074: Voucher auto-settlement — apply undirected payments/disbursements to
-- the oldest open invoices.
--
-- Client receipts already supported FIFO (oldest unpaid invoice first) when
-- no allocations were supplied. This adds the mirror for supplier/
-- subcontractor DISBURSEMENTS so an undirected payment to a supplier settles
-- his oldest purchase invoices, matching the user's requested behavior:
-- "settle the oldest invoices from the balance/payments, same for supplier."
-- ============================================================================

DROP FUNCTION IF EXISTS public.create_voucher_disbursement_atomic(
  UUID,DATE,TEXT,UUID,UUID,NUMERIC,UUID,TEXT,JSONB,BOOLEAN,UUID
);

CREATE OR REPLACE FUNCTION public.create_voucher_disbursement_atomic(
 p_company_id UUID,p_date DATE,p_disbursement_type TEXT,p_contact_id UUID,p_employee_id UUID,p_amount NUMERIC,
 p_bank_safe_id UUID,p_reason TEXT,p_allocations JSONB,p_request_approval BOOLEAN,p_user_id UUID,
 p_auto_fifo BOOLEAN DEFAULT FALSE
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_bank banks_safes%ROWTYPE; v_voucher voucher_disbursements%ROWTYPE; v_number INTEGER; v_counterpart UUID;
 v_journal JSONB; v_journal_id UUID; v_balance NUMERIC; v_item JSONB; v_invoice purchase_invoices%ROWTYPE;
 v_alloc NUMERIC; v_alloc_total NUMERIC:=0; v_applied NUMERIC:=0; v_remaining NUMERIC; v_new_paid NUMERIC; v_approval approval_requests%ROWTYPE;
BEGIN
 IF p_date IS NULL OR p_disbursement_type NOT IN ('supplier','employee_advance','subcontractor','client_refund','other')
  OR p_amount<=0 OR p_amount<>ROUND(p_amount,2) OR NULLIF(BTRIM(p_reason),'') IS NULL OR LENGTH(p_reason)>500
  OR jsonb_typeof(p_allocations)<>'array' OR jsonb_array_length(p_allocations)>100 THEN RAISE EXCEPTION 'بيانات سند الصرف غير صالحة'; END IF;
 IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE) THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
 IF p_contact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=p_contact_id AND company_id=p_company_id) THEN RAISE EXCEPTION 'الطرف غير موجود'; END IF;
 IF p_employee_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM employees WHERE id=p_employee_id AND company_id=p_company_id AND is_active=TRUE) THEN RAISE EXCEPTION 'الموظف غير موجود'; END IF;
 SELECT * INTO v_bank FROM banks_safes WHERE id=p_bank_safe_id AND company_id=p_company_id AND is_active=TRUE FOR UPDATE;
 IF NOT FOUND OR v_bank.account_id IS NULL THEN RAISE EXCEPTION 'البنك أو الخزينة غير موجود'; END IF;
 SELECT id INTO v_counterpart FROM accounts WHERE company_id=p_company_id AND code=CASE p_disbursement_type
  WHEN 'supplier' THEN '2110' WHEN 'employee_advance' THEN '1160' WHEN 'subcontractor' THEN '2150'
  WHEN 'client_refund' THEN '1130' ELSE '5400' END AND COALESCE(is_active,TRUE)=TRUE AND COALESCE(is_header,FALSE)=FALSE;
 IF v_counterpart IS NULL OR v_counterpart=v_bank.account_id THEN RAISE EXCEPTION 'الحساب المقابل غير صالح'; END IF;

 FOR v_item IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
  BEGIN v_alloc:=(v_item->>'amount')::NUMERIC; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'مبلغ التخصيص غير صالح'; END;
  IF NULLIF(v_item->>'invoice_id','') IS NULL OR v_alloc<=0 OR v_alloc<>ROUND(v_alloc,2) THEN RAISE EXCEPTION 'بيانات تخصيص الفواتير غير صالحة'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_allocations) x WHERE x->>'invoice_id'=v_item->>'invoice_id' GROUP BY x->>'invoice_id' HAVING COUNT(*)>1) THEN RAISE EXCEPTION 'تخصيص فاتورة مكرر'; END IF;
  SELECT * INTO v_invoice FROM purchase_invoices WHERE id=(v_item->>'invoice_id')::UUID AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND OR v_invoice.status IN ('cancelled','paid') THEN RAISE EXCEPTION 'فاتورة الشراء غير صالحة للتخصيص'; END IF;
  IF p_contact_id IS NOT NULL AND v_invoice.supplier_id<>p_contact_id THEN RAISE EXCEPTION 'الفاتورة لا تخص الطرف المحدد'; END IF;
  IF v_invoice.paid_amount+v_alloc>v_invoice.total+0.005 THEN RAISE EXCEPTION 'التخصيص يتجاوز المتبقي على الفاتورة'; END IF;
  v_alloc_total:=v_alloc_total+v_alloc;
 END LOOP;
 IF v_alloc_total>p_amount+0.005 THEN RAISE EXCEPTION 'مجموع التخصيصات يتجاوز مبلغ السند'; END IF;

 v_number:=next_voucher_number(p_company_id,'voucher_disbursements');
 INSERT INTO voucher_disbursements(company_id,number,date,disbursement_type,contact_id,employee_id,amount,bank_safe_id,reason,created_by,status)
 VALUES(p_company_id,v_number,p_date,p_disbursement_type,p_contact_id,p_employee_id,p_amount,p_bank_safe_id,BTRIM(p_reason),p_user_id,
  CASE WHEN p_request_approval THEN 'pending' ELSE 'approved' END) RETURNING * INTO v_voucher;

 IF p_request_approval THEN
  INSERT INTO approval_requests(company_id,transaction_type,transaction_id,entity_type,entity_id,amount,requester_id,status,message,description)
  VALUES(p_company_id,'voucher_disbursement',v_voucher.id::TEXT,'voucher_disbursement',v_voucher.id,p_amount,p_user_id,'pending',BTRIM(p_reason),BTRIM(p_reason)) RETURNING * INTO v_approval;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
   INSERT INTO disbursement_invoice_items(company_id,voucher_disbursement_id,purchase_invoice_id,amount,journal_entry_id)
   VALUES(p_company_id,v_voucher.id,(v_item->>'invoice_id')::UUID,(v_item->>'amount')::NUMERIC,NULL);
  END LOOP;
  INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values) VALUES(p_company_id,p_user_id,'request_approval','voucher_disbursement',v_voucher.id,jsonb_build_object('approval_id',v_approval.id,'amount',p_amount));
  RETURN to_jsonb(v_voucher)||jsonb_build_object('requires_approval',TRUE,'approval_id',v_approval.id);
 END IF;

 v_balance:=get_account_balance(p_company_id,v_bank.account_id,NULL,NULL);
 IF v_balance+0.005<p_amount THEN RAISE EXCEPTION 'الرصيد غير كاف للصرف'; END IF;
 v_journal:=create_journal_entry(p_company_id,p_date,'general','سند صرف رقم '||v_number||': '||BTRIM(p_reason),p_user_id,jsonb_build_array(
  jsonb_build_object('accountId',v_counterpart,'debit',p_amount,'credit',0,'contactId',p_contact_id),
  jsonb_build_object('accountId',v_bank.account_id,'debit',0,'credit',p_amount)));
 v_journal_id:=(v_journal->>'id')::UUID;
 UPDATE journal_entries SET reference_type='voucher_disbursement',reference_id=v_voucher.id WHERE id=v_journal_id AND company_id=p_company_id;
 FOR v_item IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
  SELECT * INTO v_invoice FROM purchase_invoices WHERE id=(v_item->>'invoice_id')::UUID AND company_id=p_company_id FOR UPDATE;
  v_alloc:=(v_item->>'amount')::NUMERIC; v_new_paid:=ROUND(v_invoice.paid_amount+v_alloc,2);
  UPDATE purchase_invoices SET paid_amount=v_new_paid,status=CASE WHEN v_new_paid>=v_invoice.total-0.005 THEN 'paid' ELSE 'partial' END WHERE id=v_invoice.id;
  INSERT INTO disbursement_invoice_items(company_id,voucher_disbursement_id,purchase_invoice_id,amount,journal_entry_id)
  VALUES(p_company_id,v_voucher.id,v_invoice.id,v_alloc,v_journal_id);
  v_applied:=v_applied+v_alloc;
 END LOOP;

 -- Supplier / subcontractor FIFO: an undirected disbursement settles the
 -- oldest open purchase invoices of the same supplier.
 IF jsonb_array_length(p_allocations)=0 AND COALESCE(p_auto_fifo,FALSE)
    AND p_disbursement_type IN ('supplier','subcontractor') AND p_contact_id IS NOT NULL THEN
  v_remaining:=p_amount;
  FOR v_invoice IN SELECT * FROM purchase_invoices
   WHERE company_id=p_company_id AND supplier_id=p_contact_id AND status NOT IN ('cancelled','paid')
   ORDER BY date,number FOR UPDATE LOOP
   EXIT WHEN v_remaining<=0.005;
   v_alloc:=LEAST(v_remaining,ROUND(v_invoice.total-v_invoice.paid_amount,2)); CONTINUE WHEN v_alloc<=0;
   v_new_paid:=ROUND(v_invoice.paid_amount+v_alloc,2);
   UPDATE purchase_invoices SET paid_amount=v_new_paid,status=CASE WHEN v_new_paid>=v_invoice.total-0.005 THEN 'paid' ELSE 'partial' END WHERE id=v_invoice.id;
   INSERT INTO disbursement_invoice_items(company_id,voucher_disbursement_id,purchase_invoice_id,amount,journal_entry_id)
   VALUES(p_company_id,v_voucher.id,v_invoice.id,v_alloc,v_journal_id);
   v_applied:=v_applied+v_alloc; v_remaining:=v_remaining-v_alloc;
  END LOOP;
 END IF;
 UPDATE voucher_disbursements SET journal_entry_id=v_journal_id WHERE id=v_voucher.id RETURNING * INTO v_voucher;
 INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,new_values) VALUES(p_company_id,p_user_id,'post','voucher_disbursement',v_voucher.id,to_jsonb(v_voucher));
 RETURN to_jsonb(v_voucher)||jsonb_build_object('requires_approval',FALSE,'allocated_amount',ROUND(v_applied,2),'unapplied_amount',ROUND(p_amount-v_applied,2));
END;
$$;

REVOKE ALL ON FUNCTION public.create_voucher_disbursement_atomic(UUID,DATE,TEXT,UUID,UUID,NUMERIC,UUID,TEXT,JSONB,BOOLEAN,UUID,BOOLEAN) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_voucher_disbursement_atomic(UUID,DATE,TEXT,UUID,UUID,NUMERIC,UUID,TEXT,JSONB,BOOLEAN,UUID,BOOLEAN) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 075-purchase-invoice-other-expenses.sql
-- ----------------------------------------------------------------------------

-- ============================================================================
-- 075: Purchase invoice — additional "other expenses" line
--
-- A purchase invoice can carry extra costs that are NOT owed to the supplier
-- (freight, fuel, car rental, labour, maintenance, etc.). These increase the
-- cost base of the purchase (they are debited to the cost/inventory account
-- alongside the line items) but are credited to a payment account rather than
-- to the supplier's payable, so the supplier balance stays clean.
--
--   Debit  cost account          = items subtotal + other expenses
--   Credit supplier payable      = items subtotal (+ VAT)
--   Credit payment account       = other expenses total
--
-- The per-item cost therefore rises above the supplier's unit price, matching
-- the requested behaviour.
-- ============================================================================

ALTER TABLE purchase_invoices
  ADD COLUMN IF NOT EXISTS other_expenses_total NUMERIC(15,2) NOT NULL DEFAULT 0;

-- Resolve an account by code/optional id for an "other expense" line.
CREATE OR REPLACE FUNCTION public.resolve_other_expense_account(
  p_company_id UUID, p_code TEXT, p_account_id UUID
) RETURNS UUID LANGUAGE sql SECURITY DEFINER SET search_path=public STABLE AS $$
  SELECT id FROM accounts
  WHERE company_id=p_company_id
    AND ((p_account_id IS NOT NULL AND id=p_account_id) OR (p_account_id IS NULL AND code=COALESCE(NULLIF(p_code,''),'5400')))
    AND type='expense' AND COALESCE(is_active,TRUE) AND NOT COALESCE(is_header,FALSE)
  LIMIT 1;
$$;

DROP FUNCTION IF EXISTS public.create_purchase_invoice_atomic(
  UUID,UUID,UUID,UUID,UUID,BOOLEAN,DATE,JSONB,NUMERIC,TEXT,UUID
);

CREATE OR REPLACE FUNCTION public.create_purchase_invoice_atomic(
  p_company_id UUID,p_supplier_id UUID,p_purchase_order_id UUID,p_project_id UUID,
  p_custody_id UUID,p_link_to_project BOOLEAN,p_date DATE,p_items JSONB,
  p_tax_rate NUMERIC,p_notes TEXT,p_user_id UUID,
  p_other_expenses JSONB DEFAULT '[]'::JSONB,
  p_payment_account_id UUID DEFAULT NULL
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  v_result JSONB;
  v_invoice_id UUID;
  v_inv_number TEXT;
  v_oe JSONB;
  v_oe_desc TEXT;
  v_oe_amount NUMERIC;
  v_oe_code TEXT;
  v_oe_account_id UUID;
  v_oe_acc UUID;
  v_other_total NUMERIC:=0;
  v_pay_acc UUID;
  v_lines JSONB:='[]'::JSONB;
  v_journal JSONB;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_user_id AND company_id=p_company_id AND is_active=TRUE)
  THEN RAISE EXCEPTION 'المستخدم غير صالح'; END IF;
  PERFORM set_config('app.custody_write_company',p_company_id::TEXT,TRUE);

  -- Validate other expenses first so nothing is partially committed.
  IF jsonb_typeof(COALESCE(p_other_expenses,'[]'::JSONB))<>'array' OR jsonb_array_length(p_other_expenses)>100
  THEN RAISE EXCEPTION 'بيانات المصروفات الإضافية غير صالحة'; END IF;
  FOR v_oe IN SELECT value FROM jsonb_array_elements(COALESCE(p_other_expenses,'[]'::JSONB)) LOOP
    BEGIN
      v_oe_amount:=(v_oe->>'amount')::NUMERIC;
    EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'مبلغ مصروف إضافي غير صالح'; END;
    v_oe_desc:=COALESCE(BTRIM(v_oe->>'description'),'');
    v_oe_code:=COALESCE(v_oe->>'account_code','5400');
    IF NULLIF(v_oe_desc,'') IS NULL OR LENGTH(v_oe_desc)>200 OR v_oe_amount IS NULL OR v_oe_amount<=0
      OR v_oe_amount<>ROUND(v_oe_amount,2) THEN RAISE EXCEPTION 'بند مصروف إضافي غير صالح'; END IF;
    v_other_total:=v_other_total+v_oe_amount;
  END LOOP;

  v_result:=create_purchase_invoice_atomic_v55_internal(p_company_id,p_supplier_id,p_purchase_order_id,
    p_project_id,p_custody_id,p_link_to_project,p_date,p_items,p_tax_rate,p_notes,p_user_id);
  v_invoice_id:=(v_result->>'id')::UUID;
  v_inv_number:=COALESCE(v_result->>'invoice_number',v_result->>'number');

  IF v_other_total>0 THEN
    IF p_payment_account_id IS NOT NULL THEN
      SELECT id INTO v_pay_acc FROM accounts WHERE id=p_payment_account_id AND company_id=p_company_id
        AND COALESCE(is_active,TRUE) AND NOT COALESCE(is_header,FALSE);
      IF v_pay_acc IS NULL THEN RAISE EXCEPTION 'حساب دفع المصروفات الإضافية غير صالح'; END IF;
    ELSE
      SELECT id INTO v_pay_acc FROM accounts WHERE company_id=p_company_id AND code='1110'
        AND COALESCE(is_active,TRUE) AND NOT COALESCE(is_header,FALSE);
      IF v_pay_acc IS NULL THEN RAISE EXCEPTION 'حساب دفع المصروفات الإضافية غير موجود'; END IF;
    END IF;
    FOR v_oe IN SELECT value FROM jsonb_array_elements(p_other_expenses) LOOP
      v_oe_amount:=(v_oe->>'amount')::NUMERIC;
      v_oe_desc:=COALESCE(BTRIM(v_oe->>'description'),'');
      v_oe_code:=COALESCE(v_oe->>'account_code','5400');
      v_oe_account_id:=NULLIF(v_oe->>'account_id','')::UUID;
      v_oe_acc:=resolve_other_expense_account(p_company_id,v_oe_code,v_oe_account_id);
      IF v_oe_acc IS NULL THEN RAISE EXCEPTION 'حساب مصروف «%» غير موجود', v_oe_code; END IF;
      v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
        'accountId',v_oe_acc,'debit',v_oe_amount,'credit',0,'description',v_oe_desc,'projectId',(v_result->>'project_id')::UUID));
    END LOOP;
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'accountId',v_pay_acc,'debit',0,'credit',v_other_total,'description','مصاريف إضافية فاتورة '||v_inv_number));
    v_journal:=create_journal_entry(p_company_id,p_date,'general','مصاريف إضافية فاتورة '||v_inv_number,p_user_id,v_lines);
    UPDATE purchase_invoices SET other_expenses_total=v_other_total WHERE id=v_invoice_id AND company_id=p_company_id;
  END IF;

  RETURN v_result||jsonb_build_object('other_expenses_total',v_other_total,
    'other_expenses_journal_entry_id',CASE WHEN v_journal IS NULL THEN NULL ELSE v_journal->>'id' END);
END;
$$;

REVOKE ALL ON FUNCTION public.create_purchase_invoice_atomic(UUID,UUID,UUID,UUID,UUID,BOOLEAN,DATE,JSONB,NUMERIC,TEXT,UUID,JSONB,UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_purchase_invoice_atomic(UUID,UUID,UUID,UUID,UUID,BOOLEAN,DATE,JSONB,NUMERIC,TEXT,UUID,JSONB,UUID) TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 076-lock-down-audit-tables-and-helper.sql
-- ----------------------------------------------------------------------------

-- 076: Lock down platform/audit tables and an internal SECURITY DEFINER helper.
--
-- Supabase applies broad default table grants to API roles when tables are
-- created. RLS blocks ordinary row operations, but TRUNCATE does not invoke
-- RLS, so platform-only tables must also have their table privileges revoked.
-- The expense-account resolver is an internal helper called only by the
-- service-role purchase-invoice RPC and must not be executable through the
-- public PostgREST roles.

REVOKE ALL PRIVILEGES ON TABLE public.global_backup_journal
  FROM PUBLIC, anon, authenticated;
REVOKE ALL PRIVILEGES ON TABLE public.registration_attempts
  FROM PUBLIC, anon, authenticated;

GRANT ALL PRIVILEGES ON TABLE public.global_backup_journal TO service_role;
GRANT ALL PRIVILEGES ON TABLE public.registration_attempts TO service_role;

REVOKE ALL ON FUNCTION public.resolve_other_expense_account(UUID, TEXT, UUID)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_other_expense_account(UUID, TEXT, UUID)
  TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 076-posted-journal-immutability-and-balance.sql
-- ----------------------------------------------------------------------------

-- ============================================================
-- 076 — Posted-journal immutability + whole-entry balance
--
-- Two ledger invariants were previously held only by application code and the
-- atomic RPCs. Because every API route writes through the service role
-- (which bypasses RLS), a direct write — or any future route that forgets an
-- application check — could still mutate or delete a posted entry, or create
-- an entry whose debit/credit totals do not match. Both invariants are now
-- enforced in the database itself, on EVERY write path:
--
--   1. Immutability of completed entries. A journal entry that carries lines
--      cannot be deleted, and its financial fields cannot change. The only
--      writes allowed are:
--        * audit/reversal links: reference_type, reference_id, reversal_of,
--          reversed_by (written by the audited reversal/lifecycle functions);
--        * the approval lifecycle: posted -> pending (approval request),
--          pending -> posted (approval, stamping approved_by/approved_at),
--          pending -> rejected (rejection);
--        * the company-wide reset flow (app.business_data_reset), the same
--          transaction-scoped escape hatch every other tenant guard uses.
--      The sole supported way to undo a completed entry remains the reversing
--      entry, which keeps the original in the audit trail.
--
--   2. Whole-entry balance at COMMIT. A DEFERRABLE INITIALLY DEFERRED
--      constraint trigger on journal_lines verifies at commit that every
--      entry which has lines is exactly balanced (SUM(debit) = SUM(credit),
--      no tolerance: NUMERIC(15,2) is exact). Direct multi-line inserts, line
--      edits, or line deletions that would leave an entry unbalanced abort the
--      transaction instead of corrupting the ledger. An entry without lines is
--      exempt: it is either in the brief header-then-lines creation window or
--      an orphan awaiting the writer's cleanup, and it carries no ledger data
--      (zero/zero lines are impossible — the row-integrity trigger from 048
--      rejects them, so "sums are 0" unambiguously means "no lines").
--
-- Idempotent by design (CREATE OR REPLACE / DROP TRIGGER IF EXISTS /
-- DROP CONSTRAINT IF EXISTS), matching the rest of the chain.
-- ============================================================

-- ---------- 1) Immutability guard (BEFORE UPDATE OR DELETE) ----------

CREATE OR REPLACE FUNCTION public.guard_journal_entry_immutability()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_company UUID := COALESCE(NEW.company_id, OLD.company_id);
BEGIN
  -- Company-wide reset (reset_company_business_data) intentionally wipes the
  -- tenant's ledger; every other tenant guard honours this same GUC.
  IF current_setting('app.business_data_reset', TRUE) = v_company::TEXT THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  -- A line-less header is not a completed entry: it is either mid-creation
  -- (its lines follow in the writer's next statement) or an orphan the
  -- writer is cleaning up after a failed line insert. Allow the cleanup.
  IF NOT EXISTS (SELECT 1 FROM journal_lines WHERE journal_entry_id = OLD.id) THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'posted journal entry cannot be deleted; reverse it with post_journal_reversal instead'
      USING ERRCODE = '23514';
  END IF;

  -- Financial and audit fields of a completed entry are immutable. The
  -- remaining columns (reference_type, reference_id, reversal_of,
  -- reversed_by, status, and approved_by/approved_at while not posted) are
  -- checked below; anything else changing is tampering.
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.company_id IS DISTINCT FROM OLD.company_id
     OR NEW.number IS DISTINCT FROM OLD.number
     OR NEW.date IS DISTINCT FROM OLD.date
     OR NEW.type IS DISTINCT FROM OLD.type
     OR NEW.description IS DISTINCT FROM OLD.description
     OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.cost_center_id IS DISTINCT FROM OLD.cost_center_id
     OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
     OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
     OR NEW.reference IS DISTINCT FROM OLD.reference THEN
    RAISE EXCEPTION 'posted journal entry is immutable; post a reversing entry instead of editing it'
      USING ERRCODE = '23514';
  END IF;

  -- Approval metadata may only be stamped while the entry is not posted.
  IF COALESCE(OLD.status, 'posted') = 'posted'
     AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by
          OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN
    RAISE EXCEPTION 'posted journal entry is immutable; post a reversing entry instead of editing it'
      USING ERRCODE = '23514';
  END IF;

  -- Status may only follow the documented lifecycle transitions.
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (COALESCE(OLD.status, 'posted') = 'posted' AND NEW.status = 'pending')
    OR (COALESCE(OLD.status, 'posted') = 'pending' AND NEW.status IN ('posted', 'rejected'))
  ) THEN
    RAISE EXCEPTION 'invalid journal entry status transition % -> %', OLD.status, NEW.status
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_guard_journal_entry_immutability ON public.journal_entries;
CREATE TRIGGER trg_guard_journal_entry_immutability
BEFORE UPDATE OR DELETE ON public.journal_entries
FOR EACH ROW EXECUTE FUNCTION public.guard_journal_entry_immutability();

-- ---------- 2) Whole-entry balance, enforced at COMMIT ----------

-- A constraint-trigger function is an ordinary row trigger function; the
-- constraint (DEFERRABLE INITIALLY DEFERRED) is declared on the ALTER TABLE
-- below.
CREATE OR REPLACE FUNCTION public.check_journal_entry_balance()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_company UUID := COALESCE(NEW.company_id, OLD.company_id);
  v_entry_id UUID := COALESCE(NEW.journal_entry_id, OLD.journal_entry_id);
  v_debit NUMERIC;
  v_credit NUMERIC;
BEGIN
  -- The company-wide reset removes the whole ledger; mirror the row guard.
  IF v_company IS NOT NULL
     AND current_setting('app.business_data_reset', TRUE) = v_company::TEXT THEN
    RETURN NULL;
  END IF;
  SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0)
    INTO v_debit, v_credit
    FROM journal_lines
   WHERE journal_entry_id = v_entry_id;
  IF v_debit = 0 AND v_credit = 0 THEN
    -- No lines committed for this entry (creation window / orphan cleanup):
    -- there is no ledger data to balance yet.
    RETURN NULL;
  END IF;
  IF v_debit IS DISTINCT FROM v_credit THEN
    RAISE EXCEPTION 'journal entry % is unbalanced: debit total % <> credit total %',
      v_entry_id, v_debit, v_credit
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;

-- Constraint triggers are dropped with the plain DROP TRIGGER statement.
DROP TRIGGER IF EXISTS trg_chk_journal_entry_balanced ON public.journal_lines;
CREATE CONSTRAINT TRIGGER trg_chk_journal_entry_balanced
AFTER INSERT OR UPDATE OR DELETE ON public.journal_lines
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.check_journal_entry_balance();

-- ----------------------------------------------------------------------------
-- BEGIN 077-lock-down-internal-trigger-functions.sql
-- ----------------------------------------------------------------------------

-- 077: Internal trigger functions must not be directly executable by API roles.
-- Revoking direct EXECUTE does not disable their attached triggers.

REVOKE ALL ON FUNCTION public.bootstrap_company_fiscal_year()
  FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.guard_salary_item_project_tenant()
  FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.touch_overhead_allocation()
  FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.bootstrap_company_fiscal_year() TO service_role;
GRANT EXECUTE ON FUNCTION public.guard_salary_item_project_tenant() TO service_role;
GRANT EXECUTE ON FUNCTION public.touch_overhead_allocation() TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 077-rate-limit-store.sql
-- ----------------------------------------------------------------------------

-- ============================================================
-- 077 — Shared, atomic rate-limit store
--
-- The in-memory limiter (src/lib/memory-rate-limit.ts) keeps its buckets in a
-- per-process Map: on serverless every cold instance starts empty, so a
-- client can bypass the business-route budget by rotating instances. The
-- auth routes already count against real tables (login_attempts, etc.); this
-- migration gives the ~220 business routes the same guarantee with ONE
-- generic store:
--
--   rate_limit_buckets(key, window_start, hits)
--
-- `hit_rate_limit(p_key, p_window_ms, p_max)` is a SINGLE atomic statement
-- (INSERT ... ON CONFLICT DO UPDATE): concurrent hits on the same key are
-- serialized on the row and each one sees the previous increment, so the
-- distributed budget can never be over-allocated. The application keeps the
-- in-memory limiter as a cheap fast path (instant local rejection) and this
-- store as the authoritative cross-instance share.
--
-- Rows are bounded by the number of active (principal, read/write) keys and
-- are pruned by `prune_rate_limit_buckets` (call it from any maintenance
-- job; the window itself only recycles, never deletes, rows).
--
-- Idempotent by design (IF NOT EXISTS / CREATE OR REPLACE), matching the
-- rest of the chain.
-- ============================================================

CREATE TABLE IF NOT EXISTS rate_limit_buckets (
  key TEXT PRIMARY KEY,
  window_start TIMESTAMPTZ NOT NULL,
  hits INTEGER NOT NULL DEFAULT 1 CHECK (hits >= 0)
);

-- The store is written exclusively through the service role (every API route
-- runs as service role); no API role may read or tamper with the counters.
ALTER TABLE rate_limit_buckets ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "rate_limit_buckets service only" ON public.rate_limit_buckets;
CREATE POLICY "rate_limit_buckets service only"
  ON public.rate_limit_buckets FOR ALL
  TO service_role USING (TRUE) WITH CHECK (TRUE);

CREATE OR REPLACE FUNCTION public.hit_rate_limit(
  p_key TEXT,
  p_window_ms INTEGER,
  p_max INTEGER
) RETURNS JSONB
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_now TIMESTAMPTZ := NOW();
  v_window INTERVAL := make_interval(secs => p_window_ms / 1000.0);
  v_row rate_limit_buckets%ROWTYPE;
BEGIN
  IF p_key IS NULL OR LENGTH(p_key) > 200 THEN
    RAISE EXCEPTION 'invalid rate limit key';
  END IF;
  IF p_window_ms IS NULL OR p_window_ms < 1000 THEN
    RAISE EXCEPTION 'invalid rate limit window';
  END IF;
  IF p_max IS NULL OR p_max < 1 THEN
    RAISE EXCEPTION 'invalid rate limit budget';
  END IF;

  -- Atomic read-modify-write: the ON CONFLICT target row is locked, so two
  -- concurrent hits on the same key can never both pass the budget.
  INSERT INTO rate_limit_buckets(key, window_start, hits)
  VALUES (p_key, v_now, 1)
  ON CONFLICT (key) DO UPDATE SET
    window_start = CASE WHEN rate_limit_buckets.window_start < v_now - v_window
                        THEN v_now ELSE rate_limit_buckets.window_start END,
    hits = CASE WHEN rate_limit_buckets.window_start < v_now - v_window
                THEN 1 ELSE rate_limit_buckets.hits + 1 END
  RETURNING * INTO v_row;

  IF v_row.hits > p_max THEN
    RETURN jsonb_build_object(
      'allowed', FALSE,
      'retry_after_seconds', GREATEST(1, CEIL(EXTRACT(EPOCH FROM (v_row.window_start + v_window - v_now)))::INTEGER)
    );
  END IF;
  RETURN jsonb_build_object('allowed', TRUE, 'retry_after_seconds', 0);
END;
$$;

-- Maintenance: drop buckets idle for longer than the given window so the
-- table does not accumulate keys of long-gone users.
CREATE OR REPLACE FUNCTION public.prune_rate_limit_buckets(p_max_age_ms INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_removed INTEGER;
BEGIN
  IF p_max_age_ms IS NULL OR p_max_age_ms < 1000 THEN
    RAISE EXCEPTION 'invalid prune window';
  END IF;
  DELETE FROM rate_limit_buckets
  WHERE window_start < NOW() - make_interval(secs => p_max_age_ms / 1000.0);
  GET DIAGNOSTICS v_removed = ROW_COUNT;
  RETURN COALESCE(v_removed, 0);
END;
$$;

REVOKE ALL ON FUNCTION public.hit_rate_limit(TEXT, INTEGER, INTEGER) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.prune_rate_limit_buckets(INTEGER) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.hit_rate_limit(TEXT, INTEGER, INTEGER) TO service_role;
GRANT EXECUTE ON FUNCTION public.prune_rate_limit_buckets(INTEGER) TO service_role;
REVOKE ALL ON TABLE rate_limit_buckets FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE rate_limit_buckets TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 078-server-only-public-schema-privileges.sql
-- ----------------------------------------------------------------------------

-- 078: The application is server-only with respect to PostgreSQL/Supabase.
-- Browser code never queries public tables directly; every request passes
-- through authenticated API routes using service_role. Remove Supabase's broad
-- API-role grants (including TRUNCATE, which bypasses RLS) and prevent them
-- from returning on objects created by later migrations.

REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA public
  FROM anon, authenticated;
REVOKE ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public
  FROM anon, authenticated;

GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO service_role;
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE ALL ON TABLES FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE ALL ON SEQUENCES FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT ALL ON TABLES TO service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT ALL ON SEQUENCES TO service_role;

-- ----------------------------------------------------------------------------
-- BEGIN 079-server-only-function-privileges.sql
-- ----------------------------------------------------------------------------

-- 079: Keep the public RPC surface server-only.
-- The browser never invokes PostgreSQL functions directly. API routes call
-- them with service_role after application authentication/authorization.
-- PostgreSQL grants EXECUTE on new functions to PUBLIC by default, so revoke
-- both current and future grants from API roles and PUBLIC.

REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT EXECUTE ON FUNCTIONS TO service_role;

-- RLS policy expressions execute as the querying API role. This SECURITY
-- INVOKER helper only reads that role's own request.jwt.claims GUC and is the
-- sole intentional API-role function grant.
GRANT EXECUTE ON FUNCTION public.tenant_company_id()
  TO anon, authenticated, service_role;

